import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, getDocs, orderBy, where, doc, getDoc, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, MainView, ProfessorSubView, Module, Exam, Feedback } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Filter, Download, BookOpen, ChevronRight, ShieldCheck,
  Eye, X, Layers, Star, PlayCircle, FileSpreadsheet, Award, CheckCircle2,
  Clock, ClipboardCheck
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'course_details' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  const [realModules, setRealModules] = useState<Module[]>([]);
  const [realExams, setRealExams] = useState<Exam[]>([]);
  const [realCertificates, setRealCertificates] = useState<any[]>([]);
  const [realFeedbacks, setRealFeedbacks] = useState<Feedback[]>([]);
  const [showMindMap, setShowMindMap] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
        const snapCourses = await getDocs(qCourses);
        setCourses(snapCourses.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));

        const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapStudents = await getDocs(qStudents);
        setTotalStudents(snapStudents.size);

        const qFeedbacks = query(collection(db, 'feedbacks'));
        const snapFeedbacks = await getDocs(qFeedbacks);
        setRealFeedbacks(snapFeedbacks.docs.map(doc => ({ id: doc.id, ...doc.data() } as Feedback)));

        const qCerts = query(collection(db, 'certificates'), orderBy('issuedAt', 'desc'));
        const snapCerts = await getDocs(qCerts);
        setRealCertificates(snapCerts.docs.map(d => ({ id: d.id, ...d.data(), issuedAt: d.data().issuedAt?.toDate() })));
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (selectedCourse) {
      // Buscar módulos reais
      const qModules = query(collection(db, 'modulos'), where('courseId', '==', selectedCourse.id), orderBy('order', 'asc'));
      const unsubModules = onSnapshot(qModules, (snap) => {
        setRealModules(snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)));
      });

      // Buscar avaliações reais
      const qExams = query(collection(db, 'exams'), where('courseId', '==', selectedCourse.id));
      const unsubExams = onSnapshot(qExams, (snap) => {
        setRealExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
      });

      return () => {
        unsubModules();
        unsubExams();
      };
    }
  }, [selectedCourse]);

  const engagementRate = useMemo(() => {
    if (realFeedbacks.length === 0) return "0.0%";
    const sum = realFeedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0);
    const avg = (sum / (realFeedbacks.length * 5)) * 100;
    return `${avg.toFixed(1)}%`;
  }, [realFeedbacks]);

  const openCourseReport = (course: Course) => {
    setSelectedCourse(course);
    setSubView('course_details');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleExportMatrix = () => {
    const csvContent = "Disciplina,Professor,Categoria,Status,Inscritos,Data Criacao\n" + 
      courses.map(c => {
        const date = c.createdAt?.toDate ? c.createdAt.toDate().toLocaleDateString('pt-BR') : '---';
        return `${c.nome},${c.professorResponsavel},${c.categoria},${c.status},${c.inscritos},${date}`;
      }).join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "matriz_academica.csv");
    link.click();
  };

  // --- COMPONENTE: MAPA MENTAL ACADÊMICO REAL ---
  const MindMapOverlay = () => (
    <div className="fixed inset-0 z-[1000] bg-slate-950/95 backdrop-blur-2xl p-10 overflow-auto flex flex-col items-center animate-in fade-in zoom-in-95">
      <header className="w-full flex justify-between items-center mb-20 max-w-7xl">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-500/20"><Layers size={24}/></div>
          <div>
            <h2 className="text-2xl font-black text-white uppercase italic tracking-tighter leading-none">Fluxograma da Disciplina</h2>
            <p className="text-indigo-400 text-[9px] font-black uppercase tracking-[0.3em] mt-2">Estrutura de Conteúdo e Avaliação</p>
          </div>
        </div>
        <button onClick={() => setShowMindMap(false)} className="p-4 bg-white/10 hover:bg-rose-600 text-white rounded-full transition-all border border-white/10"><X size={24}/></button>
      </header>

      <div className="relative flex flex-col items-center gap-24 w-full max-w-5xl">
        <div className="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-2xl border-4 border-white/20 z-10 text-center w-64">
           <p className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-50">Início</p>
           <h3 className="font-black italic uppercase tracking-tight text-lg leading-tight">{selectedCourse?.nome}</h3>
        </div>

        {realModules.map((mod, idx) => {
          const modExams = realExams.filter(e => e.moduleId === mod.id);
          return (
            <div key={mod.id} className="relative flex flex-col items-center w-full">
              <div className="absolute -top-24 w-1 h-24 bg-gradient-to-b from-indigo-500/20 to-indigo-500 z-0"></div>

              <div className="bg-white p-8 rounded-[3rem] shadow-2xl border border-slate-200 flex flex-col items-center w-full max-w-3xl group transition-all duration-500 hover:border-indigo-400">
                <div className="absolute -top-5 left-1/2 -translate-x-1/2 bg-slate-900 text-indigo-400 w-12 h-12 rounded-2xl flex items-center justify-center font-black text-xs italic shadow-xl border border-white/10">0{idx+1}</div>
                <h4 className="text-slate-900 font-black text-xl uppercase italic tracking-tighter mb-6 mt-2">{mod.title}</h4>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 w-full">
                  {/* Lições */}
                  <div className="space-y-3">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2 px-2 italic">Aulas Gravadas</p>
                    {mod.lessons?.length > 0 ? mod.lessons.map((lesson) => (
                      <div key={lesson.id} className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center gap-3">
                        <PlayCircle size={14} className="text-indigo-600" />
                        <span className="text-[9px] font-bold text-slate-600 uppercase italic truncate">{lesson.title}</span>
                      </div>
                    )) : <p className="text-[9px] text-slate-300 uppercase italic p-4">Sem aulas vinculadas</p>}
                  </div>

                  {/* Avaliações */}
                  <div className="space-y-3">
                    <p className="text-[9px] font-black text-amber-500 uppercase tracking-widest mb-2 px-2 italic">Atividades & Provas</p>
                    {modExams.length > 0 ? modExams.map((exam) => (
                      <div key={exam.id} className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center gap-3">
                        <ClipboardCheck size={14} className="text-amber-600" />
                        <div className="flex-1">
                          <p className="text-[9px] font-black text-amber-900 uppercase italic truncate">{exam.title}</p>
                          <p className="text-[7px] font-bold text-amber-600 uppercase italic">{exam.type === 'evaluation' ? 'Avaliação Final' : 'Atividade'}</p>
                        </div>
                      </div>
                    )) : <p className="text-[9px] text-slate-300 uppercase italic p-4">Sem avaliações vinculadas</p>}
                  </div>
                </div>
              </div>
            </div>
          );
        })}

        <div className="absolute -bottom-24 -top-24 w-0.5 bg-indigo-500/10 -z-10 left-1/2 -translate-x-1/2 border-dashed border-l"></div>

        <div className="mt-10 bg-emerald-600 p-8 rounded-[2rem] text-white shadow-2xl border-4 border-white/20 z-10 text-center w-64 mb-20 animate-pulse">
           <p className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-50">Fim da Jornada</p>
           <h3 className="font-black italic uppercase tracking-tight text-lg leading-tight">Certificação Oficial</h3>
        </div>
      </div>
    </div>
  );

  if (loading && subView === 'main') {
    return (
      <div className="h-full flex items-center justify-center p-20">
        <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
      </div>
    );
  }

  // --- VIEW: DETALHES DO CURSO (DADOS REAIS) ---
  if (subView === 'course_details' && selectedCourse) {
    const courseCerts = realCertificates.filter(c => c.courseName === selectedCourse.nome).length;

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20 print:p-0 print:space-y-4">
        {showMindMap && <MindMapOverlay />}

        <div className="relative h-80 rounded-[3rem] overflow-hidden shadow-2xl border border-slate-200 bg-slate-900 print:rounded-none print:h-40">
           {selectedCourse.capaUrl ? (
             <img src={selectedCourse.capaUrl} className="absolute inset-0 w-full h-full object-cover opacity-40 mix-blend-overlay" />
           ) : (
             <div className="absolute inset-0 bg-gradient-to-br from-slate-900 to-indigo-900 opacity-50" />
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-900/40 to-transparent" />
           <div className="absolute top-8 left-8 print:hidden">
              <button onClick={() => setSubView('main')} className="group flex items-center gap-3 px-6 py-3 bg-white/10 backdrop-blur-xl border border-white/20 rounded-2xl text-white text-[10px] font-black uppercase tracking-widest hover:bg-white hover:text-slate-900 transition-all italic"><ArrowLeft size={16}/> Painel Geral</button>
           </div>
           <div className="absolute bottom-10 left-10 right-10 flex flex-col md:flex-row items-end justify-between gap-6 print:bottom-4 print:left-4">
              <div className="space-y-2">
                 <div className="flex items-center gap-3 print:hidden">
                    <span className="px-4 py-1.5 bg-indigo-600 text-white text-[9px] font-black uppercase tracking-widest rounded-full shadow-lg">RELATÓRIO INSTITUCIONAL</span>
                    <span className="px-4 py-1.5 bg-white/10 backdrop-blur-md text-white text-[9px] font-black uppercase tracking-widest rounded-full border border-white/20">{selectedCourse.categoria}</span>
                 </div>
                 <h1 className="text-4xl md:text-6xl font-black text-white uppercase italic tracking-tighter leading-none">{selectedCourse.nome}</h1>
                 <p className="text-indigo-300 text-xs font-bold uppercase tracking-[0.3em] flex items-center gap-2 italic"><ShieldCheck size={14}/> ID: {selectedCourse.id}</p>
              </div>
              <div className="flex gap-4 print:hidden">
                 <button onClick={() => window.print()} className="px-8 py-4 bg-white text-slate-900 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-600 hover:text-white transition-all flex items-center gap-2 italic"><Download size={16}/> Exportar PDF</button>
              </div>
           </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 print:grid-cols-1">
           <div className="lg:col-span-1 space-y-8">
              <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm p-8 flex flex-col items-center text-center group print:p-4">
                 <div className="relative mb-6">
                    <div className="w-32 h-32 rounded-[2rem] overflow-hidden border-4 border-slate-50 shadow-xl print:w-16 print:h-16">
                       {selectedCourse.fotoDocenteUrl ? (
                         <img src={selectedCourse.fotoDocenteUrl} className="w-full h-full object-cover" />
                       ) : (
                         <div className="w-full h-full bg-slate-900 flex items-center justify-center text-white text-4xl font-black italic">{(selectedCourse.professorResponsavel || 'P').charAt(0)}</div>
                       )}
                    </div>
                 </div>
                 <h3 className="text-xl font-black text-slate-900 uppercase italic leading-none">{selectedCourse.professorResponsavel}</h3>
                 <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mt-2 mb-6 italic">Professor Titular</p>
                 <div className="w-full p-6 bg-slate-50 rounded-3xl border border-slate-100 text-left print:p-3">
                    <p className="text-[10px] font-medium text-slate-500 leading-relaxed italic">{selectedCourse.biografiaDocente || 'Perfil docente aguardando preenchimento.'}</p>
                 </div>
              </div>

              <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-2xl space-y-6 print:hidden">
                 <h4 className="text-[10px] font-black uppercase tracking-widest text-indigo-400 italic">Desempenho da Disciplina</h4>
                 <div className="space-y-4">
                    <div className="flex justify-between items-end">
                       <span className="text-[9px] font-bold uppercase text-slate-400">Taxa de Conclusão</span>
                       <span className="text-lg font-black tabular-nums italic">{selectedCourse.inscritos > 0 ? ((courseCerts/selectedCourse.inscritos)*100).toFixed(1) : 0}%</span>
                    </div>
                    <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                       <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${selectedCourse.inscritos > 0 ? (courseCerts/selectedCourse.inscritos)*100 : 0}%` }}></div>
                    </div>
                    <div className="flex justify-between items-end pt-2">
                       <span className="text-[9px] font-bold uppercase text-slate-400">Conteúdo Real</span>
                       <span className="text-lg font-black tabular-nums italic">{realModules.length} Módulos</span>
                    </div>
                 </div>
              </div>
           </div>

           <div className="lg:col-span-3 space-y-8">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6 print:grid-cols-3">
                 <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm print:p-4">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-2">Alunos Ativos</p>
                    <h4 className="text-3xl font-black text-slate-900 tabular-nums italic">{selectedCourse.inscritos}</h4>
                 </div>
                 <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm print:p-4">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-2">Certificados</p>
                    <h4 className="text-3xl font-black text-slate-900 tabular-nums italic">{courseCerts}</h4>
                 </div>
                 <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm print:p-4">
                    <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-2">Aulas Totais</p>
                    <h4 className="text-3xl font-black text-slate-900 tabular-nums italic">{realModules.reduce((acc, m) => acc + (m.lessons?.length || 0), 0)}</h4>
                 </div>
              </div>

              <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
                 <div className="p-10 border-b border-slate-100 bg-slate-50/30 flex items-center justify-between print:p-4">
                    <h3 className="text-xs font-black uppercase tracking-[0.2em] italic text-slate-900 flex items-center gap-3"><Layers size={18} className="text-indigo-600"/> Grade Curricular e Itens Avaliativos</h3>
                    <p className="text-[9px] font-bold text-slate-400 uppercase italic">Dados Sincronizados do Firestore</p>
                 </div>
                 <div className="p-8 space-y-6">
                    {realModules.length === 0 ? (
                      <div className="p-10 text-center italic text-slate-300 uppercase font-black text-xs">Aguardando inserção de dados pelo professor.</div>
                    ) : realModules.map((mod, idx) => {
                      const modExams = realExams.filter(e => e.moduleId === mod.id);
                      return (
                        <div key={mod.id} className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100 hover:border-indigo-200 transition-all group">
                           <div className="flex items-center justify-between mb-8">
                              <div className="flex items-center gap-6">
                                 <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center font-black text-xl italic text-slate-300 group-hover:text-indigo-600 shadow-sm transition-colors">0{idx + 1}</div>
                                 <div>
                                    <h5 className="font-black text-slate-900 text-lg uppercase italic tracking-tight">{mod.title}</h5>
                                    <div className="flex items-center gap-3 mt-1.5">
                                       <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5"><BookOpen size={10}/> {mod.lessons?.length || 0} Aulas</span>
                                       <span className="text-[8px] font-black text-amber-500 uppercase tracking-widest flex items-center gap-1.5"><ClipboardCheck size={10}/> {modExams.length} Avaliações</span>
                                    </div>
                                 </div>
                              </div>
                              <button onClick={() => setShowMindMap(true)} className="p-4 bg-white text-indigo-600 rounded-2xl shadow-sm hover:bg-indigo-600 hover:text-white transition-all italic"><Eye size={18}/></button>
                           </div>

                           <div className="grid grid-cols-1 md:grid-cols-2 gap-3 pl-20">
                              {mod.lessons?.map(l => (
                                <div key={l.id} className="flex items-center gap-2 p-3 bg-white/50 rounded-xl border border-slate-100 text-[9px] font-bold text-slate-500 uppercase italic">
                                   <PlayCircle size={12} className="text-indigo-400" /> {l.title}
                                </div>
                              ))}
                              {modExams.map(e => (
                                <div key={e.id} className="flex items-center gap-2 p-3 bg-amber-50 rounded-xl border border-amber-100 text-[9px] font-black text-amber-700 uppercase italic">
                                   <Award size={12} className="text-amber-500" /> {e.title}
                                </div>
                              ))}
                           </div>
                        </div>
                      );
                    })}
                 </div>
                 <div className="p-10 text-center border-t border-slate-50">
                    <button onClick={() => setShowMindMap(true)} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white px-10 py-5 border border-indigo-100 rounded-2xl transition-all italic tracking-widest shadow-sm flex items-center gap-3 mx-auto"><Layers size={16}/> Visualizar Mapa Acadêmico Completo</button>
                 </div>
              </div>
           </div>
        </div>
      </div>
    );
  }

  // --- VIEW: MATRIZ ACADÊMICA GLOBAL (DADOS REAIS E FILTROS) ---
  if (subView === 'all_courses') {
    const filteredCourses = courses.filter(c => {
      const matchSearch = c.nome.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          c.professorResponsavel.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCat = filterCategory === '' || c.categoria === filterCategory;
      const matchStatus = filterStatus === '' || c.status === filterStatus;
      return matchSearch && matchCat && matchStatus;
    });

    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500 pb-20">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-200 rounded-full transition-colors bg-white shadow-sm border border-slate-200"><ArrowLeft size={20}/></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic">Matriz Acadêmica Global</h1>
            <p className="text-slate-500 text-sm font-medium italic">Gestão completa e exportação de dados curriculares.</p>
          </div>
        </header>

        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex flex-col xl:flex-row justify-between items-center gap-6">
             <div className="flex flex-wrap items-center gap-4 w-full">
                <div className="relative flex-1 min-w-[250px]">
                  <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Pesquisar disciplina ou professor..." className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-[10px] font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
                <div className="flex gap-4">
                  <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="px-6 py-3 bg-white border border-slate-200 rounded-2xl text-[9px] font-black uppercase shadow-sm outline-none">
                    <option value="">Todas Categorias</option>
                    {Array.from(new Set(courses.map(c => c.categoria))).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                  <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="px-6 py-3 bg-white border border-slate-200 rounded-2xl text-[9px] font-black uppercase shadow-sm outline-none">
                    <option value="">Todos Status</option>
                    <option value="ativo">Publicado</option>
                    <option value="rascunho">Rascunho</option>
                  </select>
                </div>
             </div>
             <button onClick={handleExportMatrix} className="flex items-center gap-3 px-8 py-3 bg-emerald-600 text-white rounded-2xl text-[9px] font-black uppercase tracking-widest shadow-xl hover:bg-emerald-700 transition-all italic whitespace-nowrap"><FileSpreadsheet size={18} /> Exportar Matriz Acadêmica</button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                <tr>
                  <th className="px-8 py-5">Disciplina</th>
                  <th className="px-8 py-5">Professor Titular</th>
                  <th className="px-8 py-5">Categoria</th>
                  <th className="px-8 py-5">Status</th>
                  <th className="px-8 py-5">Inscrições</th>
                  <th className="px-8 py-5">Data Criação</th>
                  <th className="px-8 py-5 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredCourses.length === 0 ? (
                  <tr><td colSpan={7} className="p-20 text-center text-[10px] font-black uppercase text-slate-300 italic tracking-widest">Nenhuma disciplina localizada com os filtros atuais.</td></tr>
                ) : filteredCourses.map(c => {
                  const date = c.createdAt?.toDate ? c.createdAt.toDate().toLocaleDateString('pt-BR') : '---';
                  return (
                    <tr key={c.id} className="hover:bg-slate-50 transition-colors group">
                      <td className="px-8 py-5">
                         <div className="flex flex-col">
                            <span className="font-black text-slate-900 text-xs uppercase italic tracking-tight leading-tight">{c.nome}</span>
                            <span className="text-[8px] text-slate-400 font-bold uppercase tracking-widest mt-1">ID: {c.id.substring(0,8)}</span>
