                        <div className="flex-1">
                          <p className="text-[9px] font-black text-amber-900 uppercase italic truncate">{exam.title}</p>
                          <p className="text-[7px] font-bold text-amber-600 uppercase italic">{exam.type === 'evaluation' ? 'Avaliação Final' : 'Atividade'}</p>
