        )}

        <div className="absolute -bottom-24 -top-24 w-0.5 bg-indigo-500/10 -z-10 left-1/2 -translate-x-1/2 border-dashed border-l"></div>

        <div className="mt-10 bg-emerald-600 p-8 rounded-[2rem] text-white shadow-2xl border-4 border-white/20 z-10 text-center w-64 mb-20">
           <p className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-50">Fim da Jornada</p>
           <h3 className="font-black italic uppercase tracking-tight text-lg leading-tight">Certificação Oficial</h3>
        </div>
      </div>
    </div>
  );

  // --- VIEW: GESTÃO DE CERTIFICADOS ---
  if (subView === 'certificates') {
    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500 pb-20">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-2 hover:bg-slate-200 rounded-full transition-colors bg-white shadow-sm border border-slate-200"><ArrowLeft size={20}/></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic">Repositório de Certificados</h1>
            <p className="text-slate-500 text-sm font-medium italic">Monitoramento e validação de diplomas emitidos.</p>
          </div>
