import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, getDocs, orderBy, where, doc, getDoc, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, MainView, ProfessorSubView, Module, Exam, Feedback } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Filter, Download, BookOpen, ChevronRight, ShieldCheck,
  Eye, X, Layers, Star, PlayCircle, FileSpreadsheet, Award, CheckCircle2,
  Clock, ClipboardCheck, Printer, FileDown, Calendar
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'course_details' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [totalStudents, setTotalStudents] = useState(0);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  // Filtros Gerais e Certificados
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [certSearch, setCertSearch] = useState('');
  const [certCourseFilter, setCertCourseFilter] = useState('');
  const [certPeriodFilter, setCertPeriodFilter] = useState('all'); // all, 30, 90, 180

  const [realModules, setRealModules] = useState<Module[]>([]);
  const [realExams, setRealExams] = useState<Exam[]>([]);
  const [realCertificates, setRealCertificates] = useState<any[]>([]);
  const [realFeedbacks, setRealFeedbacks] = useState<Feedback[]>([]);
  const [showMindMap, setShowMindMap] = useState(false);

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
        const snapCourses = await getDocs(qCourses);
        setCourses(snapCourses.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));

        const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
        const snapStudents = await getDocs(qStudents);
        setTotalStudents(snapStudents.size);

        const qFeedbacks = query(collection(db, 'feedbacks'));
        const snapFeedbacks = await getDocs(qFeedbacks);
        setRealFeedbacks(snapFeedbacks.docs.map(doc => ({ id: doc.id, ...doc.data() } as Feedback)));

        const qCerts = query(collection(db, 'certificates'), orderBy('issuedAt', 'desc'));
        const snapCerts = await getDocs(qCerts);
        setRealCertificates(snapCerts.docs.map(d => ({ 
          id: d.id, 
          ...d.data(), 
          issuedAt: d.data().issuedAt?.toDate ? d.data().issuedAt.toDate() : new Date() 
        })));
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  // Sincronização em tempo real quando um curso é selecionado para carregar módulos e exames REAIS
  useEffect(() => {
    if (selectedCourse && subView === 'course_details') {
      // Importante: Referência exata ao courseId para carregar a grade curricular
      const qModules = query(collection(db, 'modulos'), where('courseId', '==', selectedCourse.id));
      const unsubModules = onSnapshot(qModules, (snap) => {
        const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module));
        setRealModules(mods.sort((a, b) => (a.order || 0) - (b.order || 0)));
      });

      const qExams = query(collection(db, 'exams'), where('courseId', '==', selectedCourse.id));
      const unsubExams = onSnapshot(qExams, (snap) => {
        setRealExams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Exam)));
      });

      return () => {
        unsubModules();
        unsubExams();
      };
    }
  }, [selectedCourse, subView]);

  const engagementRate = useMemo(() => {
    if (realFeedbacks.length === 0) return "0.0%";
    const sum = realFeedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0);
    const avg = (sum / (realFeedbacks.length * 5)) * 100;
    return `${avg.toFixed(1)}%`;
  }, [realFeedbacks]);

  const openCourseReport = (course: Course) => {
    setSelectedCourse(course);
    setSubView('course_details');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const filteredCertificates = useMemo(() => {
    return realCertificates.filter(cert => {
      const matchSearch = cert.studentName?.toLowerCase().includes(certSearch.toLowerCase()) || 
                          cert.id.toLowerCase().includes(certSearch.toLowerCase());
      const matchCourse = certCourseFilter === '' || cert.courseName === certCourseFilter;

      let matchPeriod = true;
      if (certPeriodFilter !== 'all') {
        const now = new Date();
        const diffDays = (now.getTime() - cert.issuedAt.getTime()) / (1000 * 3600 * 24);
        matchPeriod = diffDays <= parseInt(certPeriodFilter);
      }

      return matchSearch && matchCourse && matchPeriod;
    });
  }, [realCertificates, certSearch, certCourseFilter, certPeriodFilter]);

  const handleExportCertificates = () => {
    let csvContent = "ID Validação,Aluno,Curso,Data Conclusão\n";
    filteredCertificates.forEach(cert => {
      csvContent += `${cert.id},${cert.studentName},${cert.courseName},${cert.issuedAt.toLocaleDateString('pt-BR')}\n`;
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `relatorio_certificados_${new Date().getTime()}.csv`);
    link.click();
  };

  const handleExportCourseData = (course: Course) => {
    let csvContent = "Estrutura Acadêmica - " + course.nome + "\n";
    csvContent += "Módulo,Tipo,Título,Ordem\n";

    realModules.forEach(mod => {
      csvContent += `${mod.title},Módulo,-,${mod.order}\n`;
      mod.lessons?.forEach(lesson => {
        csvContent += `${mod.title},Aula,${lesson.title},${lesson.order}\n`;
      });
      const modExams = realExams.filter(e => e.moduleId === mod.id);
      modExams.forEach(exam => {
        csvContent += `${mod.title},Avaliação,${exam.title},-\n`;
      });
    });

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `grade_curricular_${course.nome.replace(/\s+/g, '_')}.csv`);
    link.click();
  };

  const handleExportGlobalMatrix = () => {
    const csvContent = "Disciplina,Professor,Categoria,Status,Inscritos,Data Criacao\n" + 
      courses.map(c => {
        const date = c.createdAt?.toDate ? c.createdAt.toDate().toLocaleDateString('pt-BR') : '---';
        return `${c.nome},${c.professorResponsavel},${c.categoria},${c.status},${c.inscritos},${date}`;
      }).join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", "matriz_academica_global.csv");
    link.click();
  };

  // --- COMPONENTE: MAPA MENTAL ACADÊMICO REAL ---
  const MindMapOverlay = () => (
    <div className="fixed inset-0 z-[1000] bg-slate-950/95 backdrop-blur-2xl p-10 overflow-auto flex flex-col items-center animate-in fade-in zoom-in-95">
      <header className="w-full flex justify-between items-center mb-20 max-w-7xl">
        <div className="flex items-center gap-4">
          <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-500/20"><Layers size={24}/></div>
          <div>
            <h2 className="text-2xl font-black text-white uppercase italic tracking-tighter leading-none">Fluxograma da Disciplina</h2>
            <p className="text-indigo-400 text-[9px] font-black uppercase tracking-[0.3em] mt-2">Estrutura de Conteúdo e Avaliação</p>
          </div>
        </div>
        <button onClick={() => setShowMindMap(false)} className="p-4 bg-white/10 hover:bg-rose-600 text-white rounded-full transition-all border border-white/10"><X size={24}/></button>
      </header>

      <div className="relative flex flex-col items-center gap-24 w-full max-w-5xl pb-40">
        <div className="bg-indigo-600 p-8 rounded-[2rem] text-white shadow-2xl border-4 border-white/20 z-10 text-center w-64">
           <p className="text-[9px] font-black uppercase tracking-widest mb-1 opacity-50">Início da Jornada</p>
           <h3 className="font-black italic uppercase tracking-tight text-lg leading-tight">{selectedCourse?.nome}</h3>
        </div>

        {realModules.length > 0 ? realModules.map((mod, idx) => {
          const modExams = realExams.filter(e => e.moduleId === mod.id);
          return (
            <div key={mod.id} className="relative flex flex-col items-center w-full">
