                  <option value="all">Todo o Período</option>
                  <option value="30">Últimos 30 dias</option>
                  <option value="90">Últimos 3 meses</option>
                  <option value="180">Últimos 6 meses</option>
                </select>
              </div>
           </div>
        </div>

        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                <tr>
                  <th className="px-10 py-5">Identificação</th>
                  <th className="px-10 py-5">Aluno Titular</th>
                  <th className="px-10 py-5">Disciplina Concluída</th>
                  <th className="px-10 py-5">Data de Emissão</th>
                  <th className="px-10 py-5 text-center">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredCertificates.length === 0 ? (
                  <tr><td colSpan={5} className="p-32 text-center text-[10px] font-black uppercase text-slate-300 italic tracking-widest">Nenhum certificado localizado para os filtros atuais.</td></tr>
                ) : filteredCertificates.map(cert => (
                  <tr key={cert.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="px-10 py-6">
                      <div className="flex flex-col">
                        <span className="font-mono text-xs text-indigo-600 font-bold">#{cert.id.substring(0,8).toUpperCase()}</span>
                        <span className="text-[7px] font-black text-slate-400 uppercase tracking-widest mt-1 italic">VÁLIDO E AUTENTICADO</span>
                      </div>
                    </td>
                    <td className="px-10 py-6 font-black text-slate-900 text-[11px] uppercase italic">{cert.studentName}</td>
                    <td className="px-10 py-6 font-bold text-slate-600 text-[11px] uppercase italic">{cert.courseName}</td>
                    <td className="px-10 py-6 font-medium text-slate-400 text-[10px] italic">{cert.issuedAt?.toLocaleDateString('pt-BR')}</td>
                    <td className="px-10 py-6">
                      <div className="flex items-center justify-center gap-2">
                        <button title="Visualizar Diploma" className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm"><Eye size={16}/></button>
                        <button title="Imprimir" className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-900 hover:text-white transition-all shadow-sm"><Printer size={16}/></button>
                        <button title="Baixar PDF" className="p-3 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"><FileDown size={16}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  // --- VIEW: DETALHES DO CURSO (RELATÓRIO ACADÊMICO) ---
  if (subView === 'course_details' && selectedCourse) {
    const courseCertsCount = realCertificates.filter(c => c.courseName === selectedCourse.nome).length;

    return (
      <div className="space-y-8 animate-in fade-in duration-500 pb-20 print:p-0">
        {showMindMap && <MindMapOverlay />}

        <div className="relative h-80 rounded-[3rem] overflow-hidden shadow-2xl border border-slate-200 bg-slate-900 print:h-40">
           {selectedCourse.capaUrl ? (
             <img src={selectedCourse.capaUrl} className="absolute inset-0 w-full h-full object-cover opacity-40 mix-blend-overlay" />
           ) : (
             <div className="absolute inset-0 bg-gradient-to-br from-slate-900 to-indigo-900 opacity-50" />
           )}
           <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-900/40 to-transparent" />
           <div className="absolute top-8 left-8 print:hidden">
              <button onClick={() => setSubView('main')} className="group flex items-center gap-3 px-6 py-3 bg-white/10 backdrop-blur-xl border border-white/20 rounded-2xl text-white text-[10px] font-black uppercase tracking-widest hover:bg-white hover:text-slate-900 transition-all italic"><ArrowLeft size={16}/> Painel Geral</button>
           </div>
           <div className="absolute bottom-10 left-10 right-10 flex flex-col md:flex-row items-end justify-between gap-6">
              <div className="space-y-2">
                 <div className="flex items-center gap-3 print:hidden">
                    <span className="px-4 py-1.5 bg-indigo-600 text-white text-[9px] font-black uppercase tracking-widest rounded-full shadow-lg">RELATÓRIO INSTITUCIONAL</span>
                    <span className="px-4 py-1.5 bg-white/10 backdrop-blur-md text-white text-[9px] font-black uppercase tracking-widest rounded-full border border-white/20">{selectedCourse.categoria}</span>
                 </div>
                 <h1 className="text-4xl md:text-6xl font-black text-white uppercase italic tracking-tighter leading-none">{selectedCourse.nome}</h1>
                 <p className="text-indigo-300 text-xs font-bold uppercase tracking-[0.3em] flex items-center gap-2 italic"><ShieldCheck size={14}/> ID: {selectedCourse.id}</p>
              </div>
              <div className="flex gap-4 print:hidden">
                 <button onClick={() => handleExportCourseData(selectedCourse)} className="px-8 py-4 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-2xl hover:bg-emerald-700 transition-all flex items-center gap-3 italic"><FileSpreadsheet size={18}/> Exportar Grade Acadêmica</button>
              </div>
           </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
           <div className="lg:col-span-1 space-y-8">
              <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm p-8 flex flex-col items-center text-center group">
                 <div className="relative mb-6">
                    <div className="w-32 h-32 rounded-[2rem] overflow-hidden border-4 border-slate-50 shadow-xl">
                       {selectedCourse.fotoDocenteUrl ? (
                         <img src={selectedCourse.fotoDocenteUrl} className="w-full h-full object-cover" />
                       ) : (
                         <div className="w-full h-full bg-slate-900 flex items-center justify-center text-white text-4xl font-black italic">{(selectedCourse.professorResponsavel || 'P').charAt(0)}</div>
                       )}
                    </div>
                 </div>
                 <h3 className="text-xl font-black text-slate-900 uppercase italic leading-none">{selectedCourse.professorResponsavel}</h3>
                 <p className="text-[9px] font-black text-indigo-500 uppercase tracking-widest mt-2 mb-6 italic">Professor Titular</p>
                 <div className="w-full p-6 bg-slate-50 rounded-3xl border border-slate-100 text-left">
                    <p className="text-[10px] font-medium text-slate-500 leading-relaxed italic">{selectedCourse.biografiaDocente || 'Perfil docente aguardando preenchimento.'}</p>
