                    <div className="flex justify-between items-end">
                       <span className="text-[9px] font-bold uppercase text-slate-400">Taxa de Conclusão</span>
                       <span className="text-lg font-black tabular-nums italic">{selectedCourse.inscritos > 0 ? ((courseCertsCount/selectedCourse.inscritos)*100).toFixed(1) : 0}%</span>
