                    <div className="h-2 bg-white/10 rounded-full overflow-hidden">
                       <div className="h-full bg-emerald-500 rounded-full" style={{ width: `${selectedCourse.inscritos > 0 ? (courseCertsCount/selectedCourse.inscritos)*100 : 0}%` }}></div>
