export default StudentsView;

import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, where, getDocs, onSnapshot, orderBy, addDoc, serverTimestamp, setDoc, doc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, Mail, Filter, FileSpreadsheet, 
  ChevronRight, MoreVertical, ShieldCheck, GraduationCap, 
  BookOpen, Activity, ArrowUpRight, UserX, CheckCircle2,
  Users, Eye, X, Phone, Calendar, MapPin, Hash, Lock, Save
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCourseFilter, setSelectedCourseFilter] = useState('');
  const [selectedStudent, setSelectedStudent] = useState<User | null>(null);

  // Modal State
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [registerLoading, setRegisterLoading] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    nome: '',
    email: '',
    telefone: '',
    dataNascimento: '',
    documento: '', // CPF/RG
    endereco: {
      rua: '',
      numero: '',
      bairro: '',
      cidade: '',
      uf: ''
    },
    cursoId: '',
    usuario: '',
    senha: ''
  });

  useEffect(() => {
    setLoading(true);
    const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const unsubStudents = onSnapshot(qStudents, (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const qCourses = query(collection(db, 'cursos'), orderBy('nome', 'asc'));
    const unsubCourses = onSnapshot(qCourses, (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });

    return () => {
      unsubStudents();
      unsubCourses();
    };
  }, []);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const name = s.displayName?.toLowerCase() || '';
      const email = s.email?.toLowerCase() || '';
      const matchSearch = name.includes(searchTerm.toLowerCase()) || email.includes(searchTerm.toLowerCase());
      return matchSearch;
    });
  }, [students, searchTerm]);

  const handleRegisterStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    setRegisterLoading(true);
    try {
      const year = new Date().getFullYear();
      const random = Math.random().toString(36).substring(2, 8).toUpperCase();
      const academicId = `MAT-${year}-${random}`;

      const studentData = {
        displayName: formData.nome,
        email: formData.email,
        telefone: formData.telefone,
        dataNascimento: formData.dataNascimento,
        documento: formData.documento,
        endereco: formData.endereco,
        academicId: academicId,
        cursoInicial: formData.cursoId,
        username: formData.usuario,
        password: formData.senha, 
        role: 'aluno',
        status: 'ativo',
        createdAt: serverTimestamp()
      };

      await addDoc(collection(db, 'users'), studentData);

      setIsRegisterModalOpen(false);
      setFormData({
        nome: '', email: '', telefone: '', dataNascimento: '', documento: '',
        endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' } as any,
        cursoId: '', usuario: '', senha: ''
      });
      alert(`Matrícula realizada com sucesso!\nID Acadêmico: ${academicId}`);
    } catch (error) {
      console.error("Erro ao matricular aluno:", error);
      alert("Erro ao realizar matrícula.");
    } finally {
      setRegisterLoading(false);
    }
  };

  const handleExportStudents = () => {
    const csvContent = "Identificação,Nome,Email,Documento,Status\n" + 
      filteredStudents.map(s => `${(s as any).academicId || s.uid},${s.displayName},${s.email},${(s as any).documento || '---'},${(s as any).status || 'ativo'}`).join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `lista_alunos_ead_${new Date().getTime()}.csv`);
    link.click();
  };

  if (loading) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-20">
        <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mb-4"></div>
        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic">Sincronizando Base de Alunos...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Gestão de Alunos</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Monitoramento de progresso e controle de matrículas.</p>
        </div>
        <div className="flex gap-3">
          <button onClick={handleExportStudents} className="flex items-center gap-3 px-6 py-3.5 bg-white border border-slate-200 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all italic shadow-sm">
            <FileSpreadsheet size={18} className="text-emerald-600" /> Exportar Planilha
          </button>
          <button onClick={() => setIsRegisterModalOpen(true)} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-2xl transition-all italic">
            <UserPlus size={18} /> Nova Matrícula
          </button>
        </div>
      </header>

      {/* Estatísticas Rápidas */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between group">
           <div>
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-1">Total de Alunos</p>
             <h3 className="text-4xl font-black text-slate-900 italic tabular-nums">{students.length}</h3>
           </div>
           <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all"><Users size={24}/></div>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between group">
           <div>
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-1">Taxa de Atividade</p>
             <h3 className="text-4xl font-black text-emerald-600 italic tabular-nums">94%</h3>
           </div>
           <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl group-hover:bg-emerald-600 group-hover:text-white transition-all"><Activity size={24}/></div>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between group">
           <div>
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-1">Certificações</p>
             <h3 className="text-4xl font-black text-amber-500 italic tabular-nums">128</h3>
           </div>
           <div className="p-4 bg-amber-50 text-amber-600 rounded-2xl group-hover:bg-amber-600 group-hover:text-white transition-all"><GraduationCap size={24}/></div>
        </div>
      </div>

      {/* Tabela de Alunos */}
      <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex flex-col xl:flex-row gap-6">
          <div className="relative flex-1">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Pesquisar por nome, email ou ID do aluno..." 
              className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            />
          </div>
          <div className="flex gap-4">
            <div className="flex items-center gap-3 px-6 py-4 bg-white border border-slate-200 rounded-2xl shadow-sm">
              <Filter size={14} className="text-indigo-600" />
              <select 
                value={selectedCourseFilter}
                onChange={e => setSelectedCourseFilter(e.target.value)}
                className="bg-transparent border-none text-[9px] font-black uppercase outline-none min-w-[150px]"
              >
                <option value="">Todas as Matrículas</option>
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
              </select>
            </div>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b italic">
              <tr>
                <th className="px-10 py-6">Aluno</th>
                <th className="px-10 py-6">Identificação Acadêmica</th>
                <th className="px-10 py-6">Status de Acesso</th>
                <th className="px-10 py-6 text-center">Gestão</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.length === 0 ? (
                <tr>
                  <td colSpan={5} className="p-32 text-center">
                    <div className="flex flex-col items-center opacity-20">
                      <Users size={64} className="mb-4" />
                      <p className="text-[10px] font-black uppercase tracking-[0.4em] italic">Nenhum aluno localizado na base</p>
                    </div>
                  </td>
                </tr>
              ) : filteredStudents.map(student => (
                <tr key={student.uid} className="hover:bg-indigo-50/10 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-sm italic shadow-lg">
                        {(student.displayName || 'U').charAt(0)}
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-slate-900 text-xs uppercase italic tracking-tight leading-tight">{student.displayName}</span>
                        <span className="text-[10px] text-slate-400 font-bold italic mt-0.5">{student.email}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <span className="text-[10px] font-mono text-indigo-600 font-bold">{(student as any).academicId || `UID-${student.uid.substring(0, 6).toUpperCase()}`}</span>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`flex items-center gap-2 px-4 py-1.5 ${(student as any).status === 'inativo' ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'} text-[8px] font-black uppercase rounded-full border italic w-fit`}>
                      {(student as any).status || 'Ativo'}
                    </span>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex items-center justify-center gap-2">
                       <button onClick={() => setSelectedStudent(student)} className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all">
                          <Eye size={18} />
                       </button>
                       <button className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all">
                          <UserX size={18} />
                       </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL: NOVA MATRÍCULA (TELA CHEIA IMERSIVA E UNIFICADA) */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-slate-950 flex flex-col animate-in fade-in duration-300">
          {/* Header Imersivo */}
          <header className="bg-slate-900 p-8 lg:px-12 flex justify-between items-center shrink-0">
             <div className="flex items-center gap-6">
                <div className="p-5 bg-indigo-600 text-white rounded-[2rem] shadow-2xl shadow-indigo-600/30">
                  <UserPlus size={40} />
                </div>
                <div>
                  <h2 className="text-3xl lg:text-4xl font-black text-white uppercase italic tracking-tighter leading-none">Matrícula Acadêmica</h2>
                  <p className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.4em] mt-3 italic">Portal de Onboarding e Ingresso Discente</p>
                </div>
             </div>
             <button 
                onClick={() => setIsRegisterModalOpen(false)} 
                className="p-5 bg-white/5 text-white rounded-full hover:bg-rose-600 transition-all flex items-center justify-center shadow-lg"
             >
                <X size={32}/>
             </button>
          </header>

          <form onSubmit={handleRegisterStudent} className="flex-1 overflow-y-auto bg-white flex flex-col items-center custom-scrollbar">
            <div className="w-full max-w-6xl p-12 lg:p-20 space-y-24">

              {/* Seção 01: Identidade Pessoal */}
              <div className="space-y-12">
                <div className="flex items-center gap-6">
                  <span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">01</span>
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Identidade Discente</h3>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Dados básicos e civis do aluno</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nome Completo do Aluno</label>
                    <input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="Digite o nome completo conforme documento..." />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Documento (CPF/RG)</label>
                    <input required value={formData.documento} onChange={e => setFormData({...formData, documento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="000.000.000-00" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
