import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, where, getDocs, onSnapshot, orderBy, addDoc, updateDoc, serverTimestamp, setDoc, doc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, Mail, Filter, FileSpreadsheet, 
  ChevronRight, MoreVertical, ShieldCheck, GraduationCap, 
  BookOpen, Activity, ArrowUpRight, UserX, CheckCircle2,
  Users, Eye, X, Phone, Calendar, MapPin, Hash, Lock, Save,
  RefreshCw, UserCog, UserCheck
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCourseFilter, setSelectedCourseFilter] = useState('');

  // Modal State
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);

  // Form State (Shared for Register and Edit)
  const [formData, setFormData] = useState({
    nome: '',
    email: '',
    telefone: '',
    dataNascimento: '',
    documento: '',
    endereco: {
      rua: '',
      numero: '',
      bairro: '',
      cidade: '',
      uf: ''
    },
    cursoId: '',
    usuario: '',
    senha: '',
    status: 'ativo'
  });

  useEffect(() => {
    setLoading(true);
    const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const unsubStudents = onSnapshot(qStudents, (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const qCourses = query(collection(db, 'cursos'), orderBy('nome', 'asc'));
    const unsubCourses = onSnapshot(qCourses, (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });

    return () => {
      unsubStudents();
      unsubCourses();
    };
  }, []);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const name = s.displayName?.toLowerCase() || '';
      const email = s.email?.toLowerCase() || '';
      const academicId = (s as any).academicId?.toLowerCase() || '';
      const matchSearch = name.includes(searchTerm.toLowerCase()) || 
                          email.includes(searchTerm.toLowerCase()) || 
                          academicId.includes(searchTerm.toLowerCase());

      const matchCourse = !selectedCourseFilter || (s as any).cursoInicial === selectedCourseFilter;
      return matchSearch && matchCourse;
    });
  }, [students, searchTerm, selectedCourseFilter]);

  const resetForm = () => {
    setFormData({
      nome: '', email: '', telefone: '', dataNascimento: '', documento: '',
      endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
      cursoId: '', usuario: '', senha: '', status: 'ativo'
    });
    setSelectedStudentId(null);
  };

  const handleOpenEdit = (student: User) => {
    setSelectedStudentId(student.uid);
    setFormData({
      nome: student.displayName || '',
      email: student.email || '',
      telefone: (student as any).telefone || '',
      dataNascimento: (student as any).dataNascimento || '',
      documento: (student as any).documento || '',
      endereco: {
        rua: (student as any).endereco?.rua || '',
        numero: (student as any).endereco?.numero || '',
        bairro: (student as any).endereco?.bairro || '',
        cidade: (student as any).endereco?.cidade || '',
        uf: (student as any).endereco?.uf || ''
      },
      cursoId: (student as any).cursoInicial || '',
      usuario: (student as any).username || '',
      senha: (student as any).password || '',
      status: (student as any).status || 'ativo'
    });
    setIsEditModalOpen(true);
  };

  const handleSaveStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const studentData = {
        displayName: formData.nome,
        email: formData.email,
        telefone: formData.telefone,
        dataNascimento: formData.dataNascimento,
        documento: formData.documento,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        username: formData.usuario,
        password: formData.senha,
        status: formData.status,
        updatedAt: serverTimestamp()
      };

      if (selectedStudentId) {
        // Modo Edição
        await updateDoc(doc(db, 'users', selectedStudentId), studentData);
        alert("Prontuário atualizado com sucesso!");
      } else {
        // Modo Nova Matrícula
        const year = new Date().getFullYear();
        const random = Math.random().toString(36).substring(2, 8).toUpperCase();
        const academicId = `MAT-${year}-${random}`;

        await addDoc(collection(db, 'users'), {
          ...studentData,
          academicId,
          role: 'aluno',
          createdAt: serverTimestamp()
        });
        alert(`Matrícula realizada!\nID Acadêmico: ${academicId}`);
      }

      setIsRegisterModalOpen(false);
      setIsEditModalOpen(false);
      resetForm();
    } catch (error) {
      console.error("Erro ao processar aluno:", error);
      alert("Erro ao salvar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleExportStudents = () => {
    const csvContent = "Identificação,Nome,Email,Documento,Status\n" + 
      filteredStudents.map(s => `${(s as any).academicId || s.uid},${s.displayName},${s.email},${(s as any).documento || '---'},${(s as any).status || 'ativo'}`).join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `base_alunos_ead_${new Date().getTime()}.csv`);
    link.click();
  };

  if (loading) {
    return (
      <div className="h-full flex flex-col items-center justify-center p-20">
        <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent mb-4"></div>
        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest italic">Sincronizando Base Discente...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Gestão de Alunos</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Prontuários acadêmicos e controle de matrículas.</p>
        </div>
        <div className="flex gap-3">
          <button onClick={handleExportStudents} className="flex items-center gap-3 px-6 py-3.5 bg-white border border-slate-200 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-slate-50 transition-all italic shadow-sm">
            <FileSpreadsheet size={18} className="text-emerald-600" /> Exportar Planilha
          </button>
          <button onClick={() => { resetForm(); setIsRegisterModalOpen(true); }} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-2xl transition-all italic">
            <UserPlus size={18} /> Nova Matrícula
          </button>
        </div>
      </header>

      {/* Estatísticas Rápidas */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between group">
           <div>
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-1">Total de Alunos</p>
             <h3 className="text-4xl font-black text-slate-900 italic tabular-nums">{students.length}</h3>
           </div>
           <div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl group-hover:bg-indigo-600 group-hover:text-white transition-all"><Users size={24}/></div>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between group">
           <div>
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-1">Taxa de Atividade</p>
             <h3 className="text-4xl font-black text-emerald-600 italic tabular-nums">94%</h3>
           </div>
           <div className="p-4 bg-emerald-50 text-emerald-600 rounded-2xl group-hover:bg-emerald-600 group-hover:text-white transition-all"><Activity size={24}/></div>
        </div>
        <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm flex items-center justify-between group">
           <div>
             <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest italic mb-1">Certificações</p>
             <h3 className="text-4xl font-black text-amber-500 italic tabular-nums">128</h3>
           </div>
           <div className="p-4 bg-amber-50 text-amber-600 rounded-2xl group-hover:bg-amber-600 group-hover:text-white transition-all"><GraduationCap size={24}/></div>
        </div>
      </div>

      {/* Tabela de Alunos */}
