                    <input value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="Rua, Av..." />
                  </div>
                  <div className="md:col-span-3 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Número</label>
                    <input value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="123" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Bairro</label>
                    <input value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="Bairro" />
                  </div>
                  <div className="md:col-span-5 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Cidade</label>
                    <input value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="Cidade" />
                  </div>
                  <div className="md:col-span-3 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">UF</label>
                    <input value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="UF" />
                  </div>
