                    <select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-[11px] uppercase shadow-inner outline-none appearance-none focus:ring-2 focus:ring-indigo-500 transition-all">
                       <option value="">Selecione a Disciplina...</option>
                       {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                    </select>
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Usuário (Username)</label>
                    <div className="relative">
                      <Hash className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                      <input required value={formData.usuario} onChange={e => setFormData({...formData, usuario: e.target.value})} className="w-full pl-14 pr-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="usuario.aluno" />
