                    <div className="relative">
                      <Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                      <input type="password" required value={formData.senha} onChange={e => setFormData({...formData, senha: e.target.value})} className="w-full pl-14 pr-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner focus:ring-2 focus:ring-indigo-500 transition-all" placeholder="••••••••" />
