                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Status da Matrícula</label>
                    <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-[11px] uppercase shadow-inner outline-none appearance-none focus:ring-2 focus:ring-indigo-500 transition-all">
                       <option value="ativo">Ativo</option>
                       <option value="inativo">Suspenso / Inativo</option>
                    </select>
                  </div>
                </div>
              </div>

              {/* Botões de Ação Unificados */}
              <div className="pt-20 flex gap-6 pb-20">
                 <button 
                    type="button" 
                    onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} 
                    className="px-12 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[11px] font-black uppercase italic hover:bg-slate-200 transition-all active:scale-95"
                 >
                    Descartar Alterações
                 </button>
                 <button 
                    disabled={actionLoading} 
                    type="submit"
                    className={`flex-1 py-6 text-white rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.3em] italic shadow-2xl transition-all flex items-center justify-center gap-4 active:scale-[0.98] ${
                      isEditModalOpen ? 'bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-200'
                    }`}
                 >
                    {actionLoading ? 'Processando...' : <><Save size={20}/> {isEditModalOpen ? 'Atualizar Prontuário Master' : 'Concluir e Ativar Matrícula'}</>}
                 </button>
              </div>

            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, query, where, onSnapshot, orderBy, 
  addDoc, updateDoc, deleteDoc, serverTimestamp, 
  doc, writeBatch, increment 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, Mail, Filter, FileSpreadsheet, 
  ShieldCheck, GraduationCap, BookOpen, Activity, 
  UserX, Users, Eye, X, MapPin, Hash, Lock, Save,
  UserCog, Trash2
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCourseFilter, setSelectedCourseFilter] = useState('');

  // Modal State
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    nome: '',
    email: '',
    telefone: '',
    dataNascimento: '',
    documento: '',
    endereco: {
      rua: '',
      numero: '',
      bairro: '',
      cidade: '',
      uf: ''
    },
    cursoId: '',
    usuario: '',
    senha: '',
    status: 'ativo'
  });

  useEffect(() => {
    setLoading(true);
    const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const unsubStudents = onSnapshot(qStudents, (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const qCourses = query(collection(db, 'cursos'), orderBy('nome', 'asc'));
    const unsubCourses = onSnapshot(qCourses, (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });

    return () => {
      unsubStudents();
      unsubCourses();
    };
  }, []);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const name = s.displayName?.toLowerCase() || '';
      const email = s.email?.toLowerCase() || '';
      const academicId = (s as any).academicId?.toLowerCase() || '';
      const matchSearch = name.includes(searchTerm.toLowerCase()) || 
                          email.includes(searchTerm.toLowerCase()) || 
                          academicId.includes(searchTerm.toLowerCase());

      const matchCourse = !selectedCourseFilter || (s as any).cursoInicial === selectedCourseFilter;
      return matchSearch && matchCourse;
    });
  }, [students, searchTerm, selectedCourseFilter]);

  const resetForm = () => {
    setFormData({
      nome: '', email: '', telefone: '', dataNascimento: '', documento: '',
      endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
      cursoId: '', usuario: '', senha: '', status: 'ativo'
    });
    setSelectedStudentId(null);
  };

  const handleOpenEdit = (student: User) => {
    setSelectedStudentId(student.uid);
    setFormData({
      nome: student.displayName || '',
      email: student.email || '',
      telefone: (student as any).telefone || '',
      dataNascimento: (student as any).dataNascimento || '',
      documento: (student as any).documento || '',
      endereco: {
        rua: (student as any).endereco?.rua || '',
        numero: (student as any).endereco?.numero || '',
        bairro: (student as any).endereco?.bairro || '',
        cidade: (student as any).endereco?.cidade || '',
        uf: (student as any).endereco?.uf || ''
      },
      cursoId: (student as any).cursoInicial || '',
      usuario: (student as any).username || '',
      senha: (student as any).password || '',
      status: (student as any).status || 'ativo'
    });
    setIsEditModalOpen(true);
  };

  const handleSaveStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    const batch = writeBatch(db);

    try {
      const studentData = {
        displayName: formData.nome,
        email: formData.email,
        telefone: formData.telefone,
        dataNascimento: formData.dataNascimento,
        documento: formData.documento,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        username: formData.usuario,
        password: formData.senha,
        status: formData.status,
        updatedAt: serverTimestamp()
      };

      if (selectedStudentId) {
        // Modo Edição
        const studentRef = doc(db, 'users', selectedStudentId);
        batch.update(studentRef, studentData);
        await batch.commit();
        alert("Prontuário atualizado com sucesso!");
      } else {
        // Modo Nova Matrícula com atualização de contador de inscritos
        const year = new Date().getFullYear();
        const random = Math.random().toString(36).substring(2, 8).toUpperCase();
        const academicId = `MAT-${year}-${random}`;

        const newStudentRef = doc(collection(db, 'users'));
        batch.set(newStudentRef, {
          ...studentData,
          academicId,
          role: 'aluno',
          createdAt: serverTimestamp()
        });

        // Incrementa inscritos no curso vinculado para refletir no Dashboard
        if (formData.cursoId) {
          const courseRef = doc(db, 'cursos', formData.cursoId);
          batch.update(courseRef, { inscritos: increment(1) });
        }

        await batch.commit();
        alert(`Matrícula realizada!\nID Acadêmico: ${academicId}`);
      }

      setIsRegisterModalOpen(false);
      setIsEditModalOpen(false);
      resetForm();
    } catch (error) {
      console.error("Erro ao processar aluno:", error);
      alert("Erro ao salvar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleDeleteStudent = async (id: string) => {
    if (!confirm("⚠️ ATENÇÃO: Esta ação removerá o aluno permanentemente da base acadêmica. Deseja prosseguir?")) return;
    setActionLoading(true);
    try {
      const student = students.find(s => s.uid === id);
      const batch = writeBatch(db);

      // Decrementa inscritos se o aluno estava em um curso
      if (student && (student as any).cursoInicial) {
        const courseRef = doc(db, 'cursos', (student as any).cursoInicial);
        batch.update(courseRef, { inscritos: increment(-1) });
      }

      batch.delete(doc(db, 'users', id));
      await batch.commit();

      setIsEditModalOpen(false);
      resetForm();
      alert("Aluno removido com sucesso.");
    } catch (error) {
      console.error("Erro ao deletar:", error);
      alert("Erro ao remover aluno.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleExportStudents = () => {
    const csvContent = "Identificação,Nome,Email,Documento,Status\n" + 
      filteredStudents.map(s => `${(s as any).academicId || s.uid},${s.displayName},${s.email},${(s as any).documento || '---'},${(s as any).status || 'ativo'}`).join("\n");

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `base_alunos_ead_${new Date().getTime()}.csv`);
    link.click();
  };

  if (loading) {
    return (
