  const stats = [
    { label: 'Alunos Ativos', value: totalStudents.toString(), icon: <Users size={20} />, trend: '+12.5%', action: () => onNavigate('alunos') },
    { label: 'Certificados', value: realCertificates.length.toString(), icon: <FileBadge size={20} />, trend: '+4.1%', action: () => setSubView('certificates') },
    { label: 'Engajamento NPS', value: engagementRate, icon: <Activity size={20} />, trend: '+2.0%', action: () => onNavigate('professor', 'feedback') },
  ];

  if (subView === 'main') {
    return (
      <div className="space-y-6 animate-in fade-in duration-700">
        <header>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase italic leading-none">Painel de Controle</h1>
          <p className="text-slate-500 text-sm font-medium mt-2 italic">Gerenciamento operacional e acadêmico centralizado.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {stats.map((stat, i) => (
            <div key={i} onClick={stat.action} className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex items-start justify-between group hover:border-indigo-400 hover:shadow-xl transition-all cursor-pointer">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 italic">{stat.label}</p>
                <div className="flex items-baseline gap-3">
                  <h3 className="text-4xl font-black text-slate-900 tracking-tighter tabular-nums">{stat.value}</h3>
                  <span className="text-[10px] font-black text-emerald-600 flex items-center bg-emerald-50 px-3 py-1 rounded-full italic"><TrendingUp size={10} className="mr-1" /> {stat.trend}</span>
                </div>
              </div>
              <div className="p-5 bg-slate-50 text-slate-400 group-hover:bg-indigo-600 group-hover:text-white rounded-[1.5rem] shadow-inner transition-all transform group-hover:scale-110">{stat.icon}</div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col min-h-[500px]">
            <div className="px-10 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><BookOpen size={20}/></div>
                <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Disciplinas em Foco</h2>
              </div>
              <button onClick={() => setSubView('all_courses')} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white border border-indigo-200 px-6 py-3 rounded-2xl transition-all italic">Ver Matriz Completa</button>
            </div>
            <div className="flex-1 overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                  <tr><th className="px-10 py-5">Disciplina</th><th className="px-10 py-5">Matrículas</th><th className="px-10 py-5">Professor</th><th className="px-10 py-5"></th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {courses.slice(0, 6).map(c => (
                    <tr key={c.id} className="hover:bg-indigo-50/10 transition-colors group">
                      <td className="px-10 py-6"><span className="font-black text-slate-900 text-xs uppercase italic tracking-tight">{c.nome}</span></td>
                      <td className="px-10 py-6 font-black text-slate-600 text-xs tabular-nums italic">{c.inscritos} Alunos</td>
                      <td className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase italic">{c.professorResponsavel}</td>
                      <td className="px-10 py-6 text-right">
