                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="space-y-6">
             <div className="bg-slate-900 text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden group border border-slate-800">
                <div className="relative z-10">
                  <div className="flex items-center gap-2 mb-6"><div className="w-2 h-2 bg-rose-500 rounded-full animate-ping"></div><h3 className="text-[9px] font-black uppercase tracking-[0.3em] text-indigo-400 italic">Transmissão Live Master</h3></div>
                  <h3 className="text-2xl font-black mb-3 uppercase tracking-tighter italic leading-none">Aula em Tempo Real</h3>
                  <p className="text-slate-400 text-[10px] font-medium mb-12 leading-relaxed italic max-w-[200px]">Ambiente para interação docente-discente e apresentações dinâmicas.</p>
                  <button onClick={() => onNavigate('professor', 'live')} className="w-full bg-white text-slate-900 py-4.5 rounded-[1.5rem] text-[9px] font-black uppercase tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-3 italic"><Tv size={16} /> Iniciar Sessão</button>
                </div>
                <Tv size={200} className="absolute -bottom-16 -right-16 text-white/5 transform group-hover:scale-110 transition-transform duration-1000" />
             </div>

             <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-8">
                <div className="flex items-center gap-3"><div className="p-2.5 bg-slate-900 text-white rounded-xl shadow-lg"><TrendingUp size={16}/></div><h3 className="text-[10px] font-black text-slate-800 uppercase tracking-widest italic">Ferramentas de Gestão</h3></div>
                <div className="space-y-3">
                   <button onClick={() => setSubView('certificates')} className="w-full flex items-center justify-between px-8 py-5 rounded-[1.5rem] bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[9px] font-black uppercase italic tracking-widest group">Repositório de Diplomas <ChevronRight size={14} className="group-hover:translate-x-1 transition-transform"/></button>
                   <button onClick={() => onNavigate('professor', 'frequencia')} className="w-full flex items-center justify-between px-8 py-5 rounded-[1.5rem] bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[9px] font-black uppercase italic tracking-widest group">Frequência Acadêmica <ChevronRight size={14} className="group-hover:translate-x-1 transition-transform"/></button>
                   <button onClick={() => onNavigate('professor', 'feedback')} className="w-full flex items-center justify-between px-8 py-5 rounded-[1.5rem] bg-slate-50 hover:bg-indigo-600 hover:text-white transition-all text-[9px] font-black uppercase italic tracking-widest group">Avaliação do Discente <ChevronRight size={14} className="group-hover:translate-x-1 transition-transform"/></button>
