import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, query, where, onSnapshot, orderBy, 
  addDoc, updateDoc, deleteDoc, serverTimestamp, 
  doc, writeBatch, increment 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, Mail, Filter, FileSpreadsheet, 
  ShieldCheck, GraduationCap, BookOpen, Activity, 
  UserX, Users, Eye, X, MapPin, Hash, Lock, Save,
  UserCog, Trash2
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCourseFilter, setSelectedCourseFilter] = useState('');

  // Modal State
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [selectedStudentId, setSelectedStudentId] = useState<string | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    nome: '',
    email: '',
    telefone: '',
    dataNascimento: '',
    documento: '',
    endereco: {
      rua: '',
      numero: '',
      bairro: '',
      cidade: '',
      uf: ''
    },
    cursoId: '',
    usuario: '',
    senha: '',
    status: 'ativo'
  });

  useEffect(() => {
    setLoading(true);
    const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const unsubStudents = onSnapshot(qStudents, (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() } as User)));
      setLoading(false);
    });

    const qCourses = query(collection(db, 'cursos'), orderBy('nome', 'asc'));
    const unsubCourses = onSnapshot(qCourses, (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });

    return () => {
      unsubStudents();
      unsubCourses();
    };
  }, []);

  const filteredStudents = useMemo(() => {
    return students.filter(s => {
      const name = s.displayName?.toLowerCase() || '';
      const email = s.email?.toLowerCase() || '';
      const academicId = (s as any).academicId?.toLowerCase() || '';
      const matchSearch = name.includes(searchTerm.toLowerCase()) || 
                          email.includes(searchTerm.toLowerCase()) || 
                          academicId.includes(searchTerm.toLowerCase());

      const matchCourse = !selectedCourseFilter || (s as any).cursoInicial === selectedCourseFilter;
      return matchSearch && matchCourse;
    });
  }, [students, searchTerm, selectedCourseFilter]);

  const resetForm = () => {
    setFormData({
      nome: '', email: '', telefone: '', dataNascimento: '', documento: '',
      endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
      cursoId: '', usuario: '', senha: '', status: 'ativo'
    });
    setSelectedStudentId(null);
  };

  const handleOpenEdit = (student: User) => {
    setSelectedStudentId(student.uid);
    setFormData({
      nome: student.displayName || '',
      email: student.email || '',
      telefone: (student as any).telefone || '',
      dataNascimento: (student as any).dataNascimento || '',
      documento: (student as any).documento || '',
      endereco: {
        rua: (student as any).endereco?.rua || '',
        numero: (student as any).endereco?.numero || '',
        bairro: (student as any).endereco?.bairro || '',
        cidade: (student as any).endereco?.cidade || '',
        uf: (student as any).endereco?.uf || ''
      },
      cursoId: (student as any).cursoInicial || '',
      usuario: (student as any).username || '',
      senha: (student as any).password || '',
      status: (student as any).status || 'ativo'
    });
    setIsEditModalOpen(true);
  };

  const handleSaveStudent = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    const batch = writeBatch(db);

    try {
      const studentData = {
        displayName: formData.nome,
        email: formData.email,
        telefone: formData.telefone,
        dataNascimento: formData.dataNascimento,
        documento: formData.documento,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        username: formData.usuario,
        password: formData.senha,
        status: formData.status,
        updatedAt: serverTimestamp()
      };

      if (selectedStudentId) {
        // MODO EDIÇÃO: Verificar se mudou de curso para ajustar contadores
        const oldStudent = students.find(s => s.uid === selectedStudentId);
        const oldCourseId = (oldStudent as any)?.cursoInicial;

        const studentRef = doc(db, 'users', selectedStudentId);
        batch.update(studentRef, studentData);

        if (oldCourseId !== formData.cursoId) {
           if (oldCourseId) batch.update(doc(db, 'cursos', oldCourseId), { inscritos: increment(-1) });
           if (formData.cursoId) batch.update(doc(db, 'cursos', formData.cursoId), { inscritos: increment(1) });
        }

        await batch.commit();
        alert("Prontuário atualizado!");
      } else {
        // MODO NOVA MATRÍCULA
        const year = new Date().getFullYear();
        const random = Math.random().toString(36).substring(2, 8).toUpperCase();
        const academicId = `MAT-${year}-${random}`;

        const newStudentRef = doc(collection(db, 'users'));
        batch.set(newStudentRef, {
          ...studentData,
          academicId,
          role: 'aluno',
          createdAt: serverTimestamp()
        });

        if (formData.cursoId) {
          batch.update(doc(db, 'cursos', formData.cursoId), { inscritos: increment(1) });
        }

        await batch.commit();
        alert(`Matrícula realizada!\nID Acadêmico: ${academicId}`);
      }

      setIsRegisterModalOpen(false);
      setIsEditModalOpen(false);
      resetForm();
    } catch (error) {
      console.error(error);
      alert("Erro ao salvar.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleDeleteStudent = async (id: string) => {
    if (!confirm("⚠️ Remover permanentemente da base acadêmica?")) return;
    setActionLoading(true);
    try {
      const student = students.find(s => s.uid === id);
      const batch = writeBatch(db);

      if (student && (student as any).cursoInicial) {
        batch.update(doc(db, 'cursos', (student as any).cursoInicial), { inscritos: increment(-1) });
      }

      batch.delete(doc(db, 'users', id));
      await batch.commit();

      setIsEditModalOpen(false);
      resetForm();
      alert("Removido.");
    } catch (error) {
      alert("Erro ao remover.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Gestão de Alunos</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Prontuários acadêmicos e controle de matrículas.</p>
        </div>
        <button onClick={() => { resetForm(); setIsRegisterModalOpen(true); }} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-2xl transition-all italic">
          <UserPlus size={18} /> Nova Matrícula
        </button>
      </header>

      {/* Tabela de Alunos */}
      <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex flex-col xl:flex-row gap-6">
          <div className="relative flex-1">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="Pesquisar por nome ou ID..." 
              className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            />
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] border-b italic">
              <tr>
                <th className="px-10 py-6">Aluno</th>
                <th className="px-10 py-6">ID Acadêmico</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-center">Gestão</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredStudents.map(student => (
                <tr key={student.uid} className="hover:bg-indigo-50/10 transition-colors group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-sm italic shadow-lg">
                        {(student.displayName || 'U').charAt(0)}
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-slate-900 text-xs uppercase italic tracking-tight leading-tight">{student.displayName}</span>
                        <span className="text-[10px] text-slate-400 font-bold italic mt-0.5">{student.email}</span>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <span className="text-[10px] font-mono text-indigo-600 font-bold">{(student as any).academicId || 'S/ID'}</span>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic border ${
                      (student as any).status === 'inativo' ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'
                    }`}>
                      {(student as any).status || 'Ativo'}
                    </span>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex items-center justify-center gap-2">
                       <button onClick={() => handleOpenEdit(student)} className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 transition-all shadow-sm">
                          <UserCog size={18} />
                       </button>
                       <button onClick={() => handleDeleteStudent(student.uid)} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm">
                          <Trash2 size={18} />
                       </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* AMBIENTE IMERSIVO: TELA CHEIA */}
      {(isRegisterModalOpen || isEditModalOpen) && (
        <div className="fixed inset-0 z-[2000] bg-slate-950 flex flex-col animate-in fade-in duration-300">
          <header className="bg-slate-900 p-8 lg:px-12 flex justify-between items-center shrink-0 border-b border-white/5">
             <div className="flex items-center gap-6">
                <div className={`p-5 rounded-[2rem] text-white ${isEditModalOpen ? 'bg-emerald-600' : 'bg-indigo-600'}`}>
                  {isEditModalOpen ? <UserCog size={40} /> : <UserPlus size={40} />}
                </div>
                <div>
                  <h2 className="text-3xl lg:text-4xl font-black text-white uppercase italic tracking-tighter leading-none">
                    {isEditModalOpen ? 'Gestão Discente' : 'Matrícula Acadêmica'}
                  </h2>
                </div>
             </div>
             <button onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="p-5 bg-white/5 text-white rounded-full hover:bg-rose-600 transition-all">
                <X size={32}/>
             </button>
          </header>

          <form onSubmit={handleSaveStudent} className="flex-1 overflow-y-auto bg-white flex flex-col items-center custom-scrollbar">
            <div className="w-full max-w-6xl p-12 lg:p-20 space-y-24">

              <div className="space-y-12">
                <div className="flex items-center gap-6">
                  <span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">01</span>
                  <h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Identidade Discente</h3>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nome Completo</label>
                    <input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">CPF/RG</label>
