                      <div className="flex flex-col"><span className="font-black text-slate-900 text-xs uppercase italic">{student.displayName}</span><span className="text-[10px] text-slate-400 font-bold italic">{student.email}</span></div>
                    </div>
                  </td>
                  <td className="px-10 py-6 font-mono text-[10px] text-indigo-600 font-bold">{(student as any).academicId || 'S/ID'}</td>
                  <td className="px-10 py-6">
                    <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic border ${(student as any).status === 'inativo' ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{(student as any).status || 'Ativo'}</span>
                  </td>
                  <td className="px-10 py-6">
                    <div className="flex items-center justify-center gap-2">
                       <button onClick={() => handleOpenEdit(student)} className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm"><UserCog size={18} /></button>
                       <button onClick={() => handleDelete(student.uid)} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm"><Trash2 size={18} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* AMBIENTE IMERSIVO EM TELA CHEIA */}
      {(isRegisterModalOpen || isEditModalOpen) && (
        <div className="fixed inset-0 z-[2000] bg-slate-950 flex flex-col animate-in fade-in duration-300">
          <header className="bg-slate-900 p-8 lg:px-12 flex justify-between items-center shrink-0 border-b border-white/5">
             <div className="flex items-center gap-6">
                <div className={`p-5 rounded-[2rem] text-white ${isEditModalOpen ? 'bg-emerald-600' : 'bg-indigo-600'}`}>
                  {isEditModalOpen ? <UserCog size={40} /> : <UserPlus size={40} />}
                </div>
                <div>
                  <h2 className="text-3xl lg:text-4xl font-black text-white uppercase italic tracking-tighter leading-none">{isEditModalOpen ? 'Gestão Discente' : 'Matrícula Acadêmica'}</h2>
                </div>
             </div>
             <button onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="p-5 bg-white/5 text-white rounded-full hover:bg-rose-600 transition-all"><X size={32}/></button>
          </header>

          <form onSubmit={handleSaveStudent} className="flex-1 overflow-y-auto bg-white flex flex-col items-center custom-scrollbar">
            <div className="w-full max-w-6xl p-12 lg:p-20 space-y-24">
              <div className="space-y-12">
                <div className="flex items-center gap-6">
                  <span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">01</span>
                  <h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Identidade Discente</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nome Completo</label>
                    <input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner outline-none focus:ring-2 focus:ring-indigo-500" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">CPF/RG</label>
                    <input required value={formData.documento} onChange={e => setFormData({...formData, documento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Data de Nascimento</label>
                    <input type="date" required value={formData.dataNascimento} onChange={e => setFormData({...formData, dataNascimento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">E-mail</label>
                    <input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" />
                  </div>
                  <div className="md:col-span-4 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Telefone</label>
                    <input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" />
                  </div>
                </div>
              </div>

              <div className="space-y-12">
                <div className="flex items-center gap-6">
                  <span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">02</span>
                  <h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Vínculo Acadêmico</h3>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-6 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Disciplina Principal</label>
                    <select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-[11px] uppercase shadow-inner outline-none focus:ring-2 focus:ring-indigo-500">
                       <option value="">Vincular Curso...</option>
                       {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                    </select>
                  </div>
                  <div className="md:col-span-3 space-y-2">
                    <label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Status da Matrícula</label>
                    <select value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-[11px] uppercase shadow-inner">
                       <option value="ativo">Ativo</option>
                       <option value="inativo">Inativo</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="pt-20 flex gap-6 pb-20">
                 <button type="button" onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="px-12 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[11px] font-black uppercase italic">Descartar</button>
                 {isEditModalOpen && selectedStudentId && (
                    <button type="button" onClick={() => handleDelete(selectedStudentId)} className="px-12 py-6 bg-rose-50 text-rose-500 rounded-[1.5rem] text-[11px] font-black uppercase italic hover:bg-rose-600 hover:text-white transition-all">Excluir Aluno</button>
                 )}
                 <button disabled={actionLoading} type="submit" className={`flex-1 py-6 text-white rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.3em] italic shadow-2xl ${isEditModalOpen ? 'bg-emerald-600' : 'bg-indigo-600'}`}>
                    {actionLoading ? 'Processando...' : <Save size={20} className="inline mr-2" />}{isEditModalOpen ? 'Atualizar Prontuário' : 'Concluir Matrícula'}
                 </button>
              </div>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, where, onSnapshot, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { Course, MainView, ProfessorSubView, Feedback, User } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Filter, BookOpen, ChevronRight, Eye, X, Layers, Star, 
  FileSpreadsheet, Award, CheckCircle2, Clock, ClipboardCheck, 
  Printer, FileDown, Calendar
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'certificates';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [students, setStudents] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');

  // Filtros
  const [searchTerm, setSearchTerm] = useState('');
  const [certSearch, setCertSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  const [realCertificates, setRealCertificates] = useState<any[]>([]);
  const [realFeedbacks, setRealFeedbacks] = useState<Feedback[]>([]);

  useEffect(() => {
    setLoading(true);

    // 1. Escuta CURSOS em tempo real
    const qCourses = query(collection(db, 'cursos'), orderBy('createdAt', 'desc'));
    const unsubCourses = onSnapshot(qCourses, (snap) => {
      setCourses(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));
    });

    // 2. Escuta ALUNOS em tempo real (Contagem dinâmica)
    const qStudents = query(collection(db, 'users'), where('role', '==', 'aluno'));
    const unsubStudents = onSnapshot(qStudents, (snap) => {
      setStudents(snap.docs.map(doc => ({ uid: doc.id, ...doc.data() } as User)));
      setLoading(false);
    });

    // 3. Escuta FEEDBACKS
    const unsubFeedbacks = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setRealFeedbacks(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Feedback)));
    });

    // 4. Escuta CERTIFICADOS
    const unsubCerts = onSnapshot(collection(db, 'certificates'), (snap) => {
      setRealCertificates(snap.docs.map(d => ({ 
        id: d.id, 
        ...d.data(), 
        issuedAt: d.data().issuedAt?.toDate ? d.data().issuedAt.toDate() : new Date() 
      })));
    });

    return () => {
      unsubCourses();
      unsubStudents();
      unsubFeedbacks();
      unsubCerts();
    };
  }, []);

  // Mapeamento dinâmico de alunos por curso
  const enrollmentMap = useMemo(() => {
    const map: Record<string, number> = {};
    students.forEach((s: any) => {
      const courseId = s.cursoInicial;
      if (courseId) {
        map[courseId] = (map[courseId] || 0) + 1;
      }
    });
    return map;
  }, [students]);

  const engagementRate = useMemo(() => {
    if (realFeedbacks.length === 0) return "0.0%";
    const sum = realFeedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0);
    const avg = (sum / (realFeedbacks.length * 5)) * 100;
    return `${avg.toFixed(1)}%`;
  }, [realFeedbacks]);

  if (loading) {
    return (
      <div className="flex h-full items-center justify-center p-20">
        <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
      </div>
    );
  }

  const stats = [
    { label: 'Alunos Ativos', value: students.length.toString(), icon: <Users size={20} />, trend: '+12.5%', action: () => onNavigate('alunos') },
    { label: 'Certificados', value: realCertificates.length.toString(), icon: <FileBadge size={20} />, trend: '+4.1%', action: () => setSubView('certificates') },
    { label: 'Engajamento NPS', value: engagementRate, icon: <Activity size={20} />, trend: '+2.0%', action: () => onNavigate('professor', 'feedback') },
  ];

  // VIEW PRINCIPAL
  if (subView === 'main') {
    return (
      <div className="space-y-6 animate-in fade-in duration-700">
        <header>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase italic leading-none">Painel de Controle</h1>
          <p className="text-slate-500 text-sm font-medium mt-2 italic">Gerenciamento operacional e acadêmico centralizado.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {stats.map((stat, i) => (
            <div key={i} onClick={stat.action} className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex items-start justify-between group hover:border-indigo-400 hover:shadow-xl transition-all cursor-pointer">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 italic">{stat.label}</p>
                <div className="flex items-baseline gap-3">
                  <h3 className="text-4xl font-black text-slate-900 tracking-tighter tabular-nums">{stat.value}</h3>
                  <span className="text-[10px] font-black text-emerald-600 flex items-center bg-emerald-50 px-3 py-1 rounded-full italic"><TrendingUp size={10} className="mr-1" /> {stat.trend}</span>
                </div>
              </div>
              <div className="p-5 bg-slate-50 text-slate-400 group-hover:bg-indigo-600 group-hover:text-white rounded-[1.5rem] transition-all transform group-hover:scale-110">{stat.icon}</div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col min-h-[500px]">
            <div className="px-10 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><BookOpen size={20}/></div>
                <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Disciplinas Recentes</h2>
              </div>
              <button onClick={() => setSubView('all_courses')} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white border border-indigo-200 px-6 py-3 rounded-2xl transition-all italic tracking-widest">Ver Matriz Completa</button>
            </div>
            <div className="flex-1 overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                  <tr><th className="px-10 py-5">Disciplina</th><th className="px-10 py-5">Matrículas</th><th className="px-10 py-5">Professor</th><th className="px-10 py-5"></th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {courses.slice(0, 6).map(c => (
                    <tr key={c.id} className="hover:bg-indigo-50/10 transition-colors group">
                      <td className="px-10 py-6"><span className="font-black text-slate-900 text-xs uppercase italic tracking-tight">{c.nome}</span></td>
                      <td className="px-10 py-6 font-black text-slate-600 text-xs tabular-nums italic">
                        {enrollmentMap[c.id] || 0} Alunos
                      </td>
                      <td className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase italic">{c.professorResponsavel}</td>
                      <td className="px-10 py-6 text-right">
                        <button className="p-3 text-slate-300 hover:text-indigo-600 hover:scale-110 transition-all"><ArrowUpRight size={18} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="space-y-6">
             <div className="bg-slate-900 text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden group border border-slate-800">
                <div className="relative z-10">
                  <div className="flex items-center gap-2 mb-6"><div className="w-2 h-2 bg-rose-500 rounded-full animate-ping"></div><h3 className="text-[9px] font-black uppercase tracking-[0.3em] text-indigo-400 italic">Transmissão Live Master</h3></div>
                  <h3 className="text-2xl font-black mb-3 uppercase tracking-tighter italic leading-none">Aula em Tempo Real</h3>
                  <p className="text-slate-400 text-[10px] font-medium mb-12 leading-relaxed italic max-w-[200px]">Ambiente para interação docente-discente.</p>
                  <button onClick={() => onNavigate('professor', 'live')} className="w-full bg-white text-slate-900 py-4.5 rounded-[1.5rem] text-[9px] font-black uppercase tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-3 italic"><Tv size={16} /> Iniciar Sessão</button>
                </div>
                <Tv size={200} className="absolute -bottom-16 -right-16 text-white/5 transform group-hover:scale-110 transition-transform duration-1000" />
             </div>
          </div>
        </div>
      </div>
    );
  }

  // VIEW: MATRIZ COMPLETA (RESTAURADA)
  if (subView === 'all_courses') {
    const filteredCourses = courses.filter(c => {
      const matchSearch = c.nome.toLowerCase().includes(searchTerm.toLowerCase()) || c.professorResponsavel.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCat = !filterCategory || c.categoria === filterCategory;
      const matchStatus = !filterStatus || c.status === filterStatus;
      return matchSearch && matchCat && matchStatus;
    });

    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500 pb-20">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-3 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm"><ArrowLeft size={20}/></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Matriz Acadêmica Global</h1>
            <p className="text-slate-500 text-xs font-medium italic mt-1">Monitoramento e controle consolidado de disciplinas.</p>
          </div>
        </header>

        <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex flex-col xl:flex-row gap-6">
             <div className="relative flex-1">
                <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input 
                  type="text" 
                  value={searchTerm} 
                  onChange={(e) => setSearchTerm(e.target.value)} 
                  placeholder="Pesquisar disciplina ou titular..." 
                  className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-black outline-none shadow-inner" 
                />
             </div>
             <div className="flex gap-4">
                <select value={filterCategory} onChange={e => setFilterCategory(e.target.value)} className="bg-white border border-slate-200 rounded-2xl px-6 py-4 text-[9px] font-black uppercase outline-none shadow-sm">
                  <option value="">Todas Categorias</option>
                  <option value="Básico">Básico</option>
                  <option value="Doutrina">Doutrina</option>
                  <option value="História">História</option>
                </select>
                <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)} className="bg-white border border-slate-200 rounded-2xl px-6 py-4 text-[9px] font-black uppercase outline-none shadow-sm">
                  <option value="">Todos Status</option>
                  <option value="ativo">Ativo</option>
                  <option value="rascunho">Rascunho</option>
                </select>
             </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                <tr>
                  <th className="px-10 py-6">Disciplina</th>
                  <th className="px-10 py-6">Titular da Cadeira</th>
                  <th className="px-10 py-6">Categoria</th>
                  <th className="px-10 py-6">Status</th>
                  <th className="px-10 py-6">Alunos Ativos</th>
                  <th className="px-10 py-6 text-center">Gestão</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredCourses.map(c => (
                  <tr key={c.id} className="hover:bg-indigo-50/10 transition-colors">
                    <td className="px-10 py-6"><span className="font-black text-slate-900 text-xs uppercase italic">{c.nome}</span></td>
                    <td className="px-10 py-6 font-bold text-slate-400 text-[10px] uppercase italic">{c.professorResponsavel}</td>
                    <td className="px-10 py-6 font-black text-indigo-500 text-[9px] uppercase italic">{c.categoria}</td>
                    <td className="px-10 py-6">
                      <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic ${c.status === 'ativo' ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-500'}`}>
                        {c.status}
                      </span>
                    </td>
                    <td className="px-10 py-6 font-black text-slate-700 text-xs tabular-nums italic">
                      {enrollmentMap[c.id] || 0} Alunos
                    </td>
                    <td className="px-10 py-6 text-center">
                      <button className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><ArrowUpRight size={18}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  // VIEW: CERTIFICADOS (RESTAURADA)
  if (subView === 'certificates') {
    const filteredCerts = realCertificates.filter(cert => {
      const match = cert.studentName?.toLowerCase().includes(certSearch.toLowerCase()) || cert.id.toLowerCase().includes(certSearch.toLowerCase());
      return match;
    });

    return (
      <div className="space-y-6 animate-in slide-in-from-right duration-500 pb-20">
        <header className="flex items-center gap-4">
          <button onClick={() => setSubView('main')} className="p-3 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm"><ArrowLeft size={20}/></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Repositório de Diplomas</h1>
            <p className="text-slate-500 text-xs font-medium italic mt-1">Controle de emissão e autenticidade.</p>
          </div>
        </header>

        <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="p-8 border-b border-slate-100 bg-slate-50/50">
             <div className="relative flex-1">
                <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input 
                  type="text" 
                  value={certSearch} 
                  onChange={(e) => setCertSearch(e.target.value)} 
                  placeholder="Pesquisar por nome do aluno ou ID de validação..." 
                  className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-black outline-none shadow-inner" 
                />
             </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                <tr>
                  <th className="px-10 py-6">ID Validação</th>
                  <th className="px-10 py-6">Aluno</th>
