        </div>
        <div className="overflow-x-auto"><table className="w-full text-left"><thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic"><tr><th className="px-10 py-6">Aluno</th><th className="px-10 py-6">Matrícula</th><th className="px-10 py-6">Status</th><th className="px-10 py-6 text-center">Gestão</th></tr></thead><tbody className="divide-y divide-slate-100">{filtered.map(student => (<tr key={student.uid} className="hover:bg-indigo-50/10 group"><td className="px-10 py-6 flex items-center gap-4"><div className="w-12 h-12 rounded-2xl bg-indigo-600 text-white flex items-center justify-center font-black text-sm italic shadow-lg">{(student.displayName || 'U').charAt(0)}</div><div className="flex flex-col"><span className="font-black text-slate-900 text-xs uppercase italic">{student.displayName}</span><span className="text-[10px] text-slate-400 font-bold italic">{student.email}</span></div></td><td className="px-10 py-6 font-mono text-[10px] text-indigo-600 font-bold">{(student as any).academicId}</td><td className="px-10 py-6"><span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic ${(student as any).status === 'inativo' ? 'bg-rose-50 text-rose-600' : 'bg-emerald-50 text-emerald-600'}`}>{(student as any).status}</span></td><td className="px-10 py-6 flex justify-center gap-2"><button onClick={() => handleOpenEdit(student)} className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all"><UserCog size={18} /></button><button onClick={() => handleDelete(student.uid)} className="p-3 bg-rose-50 text-rose-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={18} /></button></td></tr>))}</tbody></table></div>
      </div>

      {(isRegisterModalOpen || isEditModalOpen) && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/95 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
          <header className="bg-slate-900 p-8 lg:px-12 flex justify-between items-center border-b border-white/5">
             <div className="flex items-center gap-6"><div className={`p-5 rounded-[2rem] text-white ${isEditModalOpen ? 'bg-emerald-600' : 'bg-indigo-600'}`}>{isEditModalOpen ? <UserCog size={40} /> : <UserPlus size={40} />}</div><h2 className="text-3xl lg:text-4xl font-black text-white uppercase italic tracking-tighter leading-none">{isEditModalOpen ? 'Gestão Discente' : 'Nova Matrícula'}</h2></div>
             <button onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="p-5 bg-white/5 text-white rounded-full hover:bg-rose-600 transition-all"><X size={32}/></button>
          </header>

          <form onSubmit={handleSave} className="flex-1 overflow-y-auto bg-white flex flex-col items-center custom-scrollbar">
            <div className="w-full max-w-6xl p-12 lg:p-20 space-y-24">
              <div className="space-y-12">
                <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">01</span><h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Identidade Discente</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Documento</label><input required value={formData.documento} onChange={e => setFormData({...formData, documento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">E-mail</label><input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Telefone</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nascimento</label><input type="date" required value={formData.dataNascimento} onChange={e => setFormData({...formData, dataNascimento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                </div>
              </div>

              <div className="space-y-12">
                <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">02</span><h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Endereço Residencial</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Rua / Logradouro</label><input value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Número</label><input value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Bairro</label><input value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Cidade</label><input value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-2 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">UF</label><input value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm uppercase" maxLength={2} /></div>
                </div>
              </div>

              <div className="space-y-12">
                <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">03</span><h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Segurança e Acesso</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Curso Matriz</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-[10px] uppercase">{<option value="">Vincular Curso...</option>}{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                  <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Usuário (Login)</label><input required value={formData.usuario} onChange={e => setFormData({...formData, usuario: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Senha Provisória</label><input type="password" required value={formData.senha} onChange={e => setFormData({...formData, senha: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                </div>
              </div>

              <div className="pt-20 flex gap-6 pb-20">
                 <button type="button" onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="px-12 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[11px] font-black uppercase italic">Descartar</button>
                 {isEditModalOpen && <button type="button" onClick={() => handleDelete(selectedStudentId!)} className="px-12 py-6 bg-rose-50 text-rose-500 rounded-[1.5rem] text-[11px] font-black uppercase italic hover:bg-rose-600 hover:text-white transition-all">Excluir Prontuário</button>}
                 <button disabled={actionLoading} type="submit" className={`flex-1 py-6 text-white rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.3em] italic shadow-2xl ${isEditModalOpen ? 'bg-emerald-600 shadow-emerald-200' : 'bg-indigo-600 shadow-indigo-200'}`}>{actionLoading ? 'Processando...' : <><Save size={20} className="inline mr-2"/> {isEditModalOpen ? 'Atualizar Dados' : 'Concluir Matrícula'}</>}</button>
              </div>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo } from 'react';
import { collection, query, where, onSnapshot, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { Course, MainView, ProfessorSubView, Feedback, User } from '../types';
import { 
  Users, FileBadge, Activity, ArrowUpRight, TrendingUp, Tv, ArrowLeft, 
  Search, Filter, BookOpen, ChevronRight, Eye, X, Layers, Star, 
  FileSpreadsheet, Award, CheckCircle2, Clock, ClipboardCheck, 
  Printer, FileDown, Calendar, Download, ImageIcon, FileText, MoreVertical, Edit
} from 'lucide-react';

interface DashboardViewProps {
  onNavigate: (main: MainView, sub?: ProfessorSubView) => void;
}

type DashboardSubView = 'main' | 'all_courses' | 'certificates' | 'course_details';

const DashboardView: React.FC<DashboardViewProps> = ({ onNavigate }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [students, setStudents] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [subView, setSubView] = useState<DashboardSubView>('main');
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [certSearch, setCertSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState('');
  const [filterStatus, setFilterStatus] = useState('');

  const [realCertificates, setRealCertificates] = useState<any[]>([]);
  const [realFeedbacks, setRealFeedbacks] = useState<Feedback[]>([]);

  useEffect(() => {
    setLoading(true);
    const unsubCourses = onSnapshot(query(collection(db, 'cursos'), orderBy('createdAt', 'desc')), (snap) => {
      setCourses(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Course)));
    });

    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(doc => ({ uid: doc.id, ...doc.data() } as User)));
      setLoading(false);
    });

    const unsubFeedbacks = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      setRealFeedbacks(snap.docs.map(doc => ({ id: doc.id, ...doc.data() } as Feedback)));
    });

    const unsubCerts = onSnapshot(collection(db, 'certificates'), (snap) => {
      setRealCertificates(snap.docs.map(d => ({ 
        id: d.id, 
        ...d.data(), 
        issuedAt: d.data().issuedAt?.toDate ? d.data().issuedAt.toDate() : new Date() 
      })));
    });

    return () => {
      unsubCourses();
      unsubStudents();
      unsubFeedbacks();
      unsubCerts();
    };
  }, []);

  const enrollmentMap = useMemo(() => {
    const map: Record<string, number> = {};
    students.forEach((s: any) => {
      const courseId = s.cursoInicial;
      if (courseId) map[courseId] = (map[courseId] || 0) + 1;
    });
    return map;
  }, [students]);

  const engagementRate = useMemo(() => {
    if (realFeedbacks.length === 0) return "0.0%";
    const sum = realFeedbacks.reduce((acc, curr) => acc + (curr.rating || 0), 0);
    const avg = (sum / (realFeedbacks.length * 5)) * 100;
    return `${avg.toFixed(1)}%`;
  }, [realFeedbacks]);

  const handleExportMatrix = () => {
    const csvContent = "Disciplina,Titular,Categoria,Status,Inscritos\n" + 
      courses.map(c => `${c.nome},${c.professorResponsavel},${c.categoria},${c.status},${enrollmentMap[c.id] || 0}`).join("\n");
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `matriz_academica_${new Date().getTime()}.csv`;
    link.click();
  };

  const handleDownloadFactSheet = (course: Course) => {
    const content = `FICHA TÉCNICA - ${course.nome}\nProfessor: ${course.professorResponsavel}\nCategoria: ${course.categoria}\nStatus: ${course.status}\nInscritos: ${enrollmentMap[course.id] || 0}\n\nDescrição: ${course.descricao}`;
    const blob = new Blob([content], { type: 'text/plain' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `ficha_${course.nome.replace(/\s/g, '_')}.txt`;
    link.click();
  };

  if (loading) return (
    <div className="flex h-screen items-center justify-center p-20 bg-slate-50">
      <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
    </div>
  );

  if (subView === 'main') {
    return (
      <div className="space-y-6 animate-in fade-in duration-700">
        <header>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight uppercase italic leading-none">Painel de Controle</h1>
          <p className="text-slate-500 text-sm font-medium mt-2 italic">Gerenciamento operacional e acadêmico centralizado.</p>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {[{ label: 'Alunos Ativos', value: students.length.toString(), icon: <Users size={20} />, action: () => onNavigate('alunos') },
            { label: 'Certificados', value: realCertificates.length.toString(), icon: <FileBadge size={20} />, action: () => setSubView('certificates') },
            { label: 'Engajamento NPS', value: engagementRate, icon: <Activity size={20} />, action: () => onNavigate('professor', 'feedback') }].map((stat, i) => (
            <div key={i} onClick={stat.action} className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex items-start justify-between group hover:border-indigo-400 hover:shadow-xl transition-all cursor-pointer">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 italic">{stat.label}</p>
                <h3 className="text-4xl font-black text-slate-900 tracking-tighter tabular-nums">{stat.value}</h3>
              </div>
              <div className="p-5 bg-slate-50 text-slate-400 group-hover:bg-indigo-600 group-hover:text-white rounded-[1.5rem] transition-all transform group-hover:scale-110">{stat.icon}</div>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col min-h-[500px]">
            <div className="px-10 py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg"><BookOpen size={20}/></div>
                <h2 className="text-xs font-black text-slate-800 uppercase tracking-widest italic">Disciplinas Recentes</h2>
              </div>
              <button onClick={() => setSubView('all_courses')} className="text-[10px] font-black uppercase text-indigo-600 hover:bg-indigo-600 hover:text-white border border-indigo-200 px-6 py-3 rounded-2xl transition-all italic tracking-widest">Ver Matriz Completa</button>
            </div>
            <div className="flex-1 overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                  <tr><th className="px-10 py-5">Disciplina</th><th className="px-10 py-5">Matrículas</th><th className="px-10 py-5">Professor</th><th className="px-10 py-5"></th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {courses.slice(0, 6).map(c => (
                    <tr key={c.id} className="hover:bg-indigo-50/10 transition-colors group">
                      <td className="px-10 py-6 font-black text-slate-900 text-xs uppercase italic tracking-tight">{c.nome}</td>
                      <td className="px-10 py-6 font-black text-slate-600 text-xs tabular-nums italic">{enrollmentMap[c.id] || 0} Alunos</td>
                      <td className="px-10 py-6 text-[10px] font-black text-slate-400 uppercase italic">{c.professorResponsavel}</td>
                      <td className="px-10 py-6 text-right">
                        <button onClick={() => { setSelectedCourse(c); setSubView('course_details'); }} className="p-3 text-slate-300 hover:text-indigo-600 hover:scale-110 transition-all"><ArrowUpRight size={18} /></button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="space-y-6">
             <div className="bg-slate-900 text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden group border border-slate-800">
                <div className="relative z-10">
