import { User, Course } from '../types';
import { 
  Search, UserPlus, Filter, X, Save, UserCog, Trash2, Download, BookOpen, MapPin, Hash, Lock, ShieldCheck, Calendar, Eye, Edit3
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);

  // Filtros
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  // Modais
  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any | null>(null);

  const [formData, setFormData] = useState({
    nome: '', email: '', telefone: '', dataNascimento: '', documento: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    cursoId: '', usuario: '', senha: '', status: 'ativo'
  });

  useEffect(() => {
    setLoading(true);
    // REMOVIDO: orderBy('createdAt', 'desc') para evitar erro de índice composto sem intervenção no console
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      const data = snap.docs.map(d => ({ uid: d.id, ...d.data() } as User));
      // Ordenação manual client-side para garantir o funcionamento imediato
      const sortedData = data.sort((a: any, b: any) => {
        const dateA = a.createdAt?.seconds || 0;
        const dateB = b.createdAt?.seconds || 0;
        return dateB - dateA;
      });
      setStudents(sortedData);
      setLoading(false);
    });

    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });
    return () => { unsubStudents(); unsubCourses(); };
  }, []);

  const filtered = useMemo(() => {
    return students.filter(s => {
      const sData = s as any;
      const matchSearch = s.displayName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          s.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          sData.academicId?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCourse = !courseFilter || sData.cursoInicial === courseFilter;

      let matchDate = true;
      if (dateStart || dateEnd) {
        const created = sData.createdAt?.seconds ? new Date(sData.createdAt.seconds * 1000) : new Date();
        if (dateStart) matchDate = matchDate && created >= new Date(dateStart + "T00:00:00");
        if (dateEnd) matchDate = matchDate && created <= new Date(dateEnd + "T23:59:59");
      }

      return matchSearch && matchCourse && matchDate;
    });
  }, [students, searchTerm, courseFilter, dateStart, dateEnd]);

  const handleExport = () => {
    const csvContent = "AcademicID,Nome,Email,Telefone,DataCadastro,Curso,Status\n" + 
      filtered.map(s => {
        const d = s as any;
        const curso = courses.find(c => c.id === d.cursoInicial)?.nome || '---';
        const data = d.createdAt?.seconds ? new Date(d.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : '---';
        return `${d.academicId},${s.displayName},${s.email},${d.telefone || ''},${data},${curso},${d.status}`;
      }).join("\n");
    const blob = new Blob(["\uFEFF" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `relatorio_alunos_EB_${new Date().getTime()}.csv`;
    link.click();
  };

  const resetForm = () => {
    setFormData({
      nome: '', email: '', telefone: '', dataNascimento: '', documento: '',
      endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
      cursoId: '', usuario: '', senha: '', status: 'ativo'
    });
    setSelectedStudent(null);
  };

  const handleOpenEdit = (student: User) => {
    const s = student as any;
    setSelectedStudent(s);
    setFormData({
      nome: student.displayName || '', email: student.email || '', telefone: s.telefone || '',
      dataNascimento: s.dataNascimento || '', documento: s.documento || '',
      endereco: { rua: s.endereco?.rua || '', numero: s.endereco?.numero || '', bairro: s.endereco?.bairro || '', cidade: s.endereco?.cidade || '', uf: s.endereco?.uf || '' },
      cursoId: s.cursoInicial || '', usuario: s.username || '', senha: s.password || '', status: s.status || 'ativo'
    });
    setIsEditModalOpen(true);
    setIsDetailModalOpen(false);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    const batch = writeBatch(db);
    try {
      const payload = {
        displayName: formData.nome, email: formData.email, telefone: formData.telefone,
        dataNascimento: formData.dataNascimento, documento: formData.documento,
        endereco: formData.endereco, cursoInicial: formData.cursoId, 
        username: formData.usuario, password: formData.senha, status: formData.status,
        updatedAt: serverTimestamp()
      };
      if (selectedStudent?.uid) {
        batch.update(doc(db, 'users', selectedStudent.uid), payload);
      } else {
        const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 8).toUpperCase()}`;
        batch.set(doc(collection(db, 'users')), { ...payload, academicId, role: 'aluno', createdAt: serverTimestamp() });
      }
      await batch.commit();
      setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm();
    } catch (err) { alert("Erro ao salvar."); } finally { setActionLoading(false); }
  };

  const handleDelete = async (id: string) => {
    if (confirm("Remover este aluno permanentemente?")) {
      await deleteDoc(doc(db, 'users', id));
      setIsDetailModalOpen(false);
      setIsEditModalOpen(false);
    }
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Gestão de Alunos</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Controle acadêmico e prontuários completos.</p>
        </div>
        <div className="flex gap-4">
          <button onClick={handleExport} className="flex items-center gap-3 bg-white border border-slate-200 text-slate-600 px-6 py-3.5 rounded-2xl text-[9px] font-black uppercase italic hover:bg-slate-50 transition-all shadow-sm"><Download size={18}/> Exportar Excel Completo</button>
          <button onClick={() => { resetForm(); setIsRegisterModalOpen(true); }} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-2xl transition-all italic"><UserPlus size={18} /> Nova Matrícula</button>
        </div>
      </header>

      <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-10 border-b border-slate-100 bg-slate-50/50 space-y-6">
          <div className="flex flex-col lg:flex-row gap-6">
            <div className="relative flex-[2]">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por nome, matrícula ou e-mail..." className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-bold outline-none shadow-inner" />
            </div>
            <div className="flex flex-1 gap-4">
               <div className="relative flex-1">
                  <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                  <input type="date" value={dateStart} onChange={e => setDateStart(e.target.value)} className="w-full pl-10 pr-4 py-4 bg-white border border-slate-200 rounded-2xl text-[9px] font-black uppercase outline-none shadow-sm" />
               </div>
               <div className="relative flex-1">
                  <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                  <input type="date" value={dateEnd} onChange={e => setDateEnd(e.target.value)} className="w-full pl-10 pr-4 py-4 bg-white border border-slate-200 rounded-2xl text-[9px] font-black uppercase outline-none shadow-sm" />
               </div>
            </div>
            <select value={courseFilter} onChange={e => setCourseFilter(e.target.value)} className="bg-white border border-slate-200 rounded-2xl px-6 py-4 text-[9px] font-black uppercase outline-none shadow-sm flex-1"><option value="">Todas Disciplinas</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
              <tr>
                <th className="px-10 py-6">ID Aluno</th>
                <th className="px-10 py-6">Nome Completo</th>
                <th className="px-10 py-6">E-mail Acadêmico</th>
                <th className="px-10 py-6">Telefone</th>
                <th className="px-10 py-6">Disciplina Atual</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-center">Gestão</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-[10px]">
              {filtered.map(student => {
                const s = student as any;
                const curso = courses.find(c => c.id === s.cursoInicial)?.nome || 'S/Vínculo';
                return (
                  <tr key={student.uid} className="hover:bg-indigo-50/10 group transition-all">
                    <td className="px-10 py-6 font-mono font-black text-indigo-600">{s.academicId}</td>
                    <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{student.displayName}</td>
                    <td className="px-10 py-6 font-bold text-slate-400">{student.email}</td>
                    <td className="px-10 py-6 font-bold text-slate-500 tabular-nums">{s.telefone || '---'}</td>
                    <td className="px-10 py-6 font-black text-indigo-500 italic uppercase">{curso}</td>
                    <td className="px-10 py-6">
                      <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic border ${s.status === 'inativo' ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{s.status}</span>
                    </td>
                    <td className="px-10 py-6">
                      <div className="flex items-center justify-center gap-2">
                        <button onClick={() => { setSelectedStudent(s); setIsDetailModalOpen(true); }} className="p-3 bg-white border border-slate-100 text-slate-400 hover:text-indigo-600 rounded-xl hover:bg-indigo-50 transition-all shadow-sm" title="Ver Ficha"><Eye size={18} /></button>
                        <button onClick={() => handleOpenEdit(student)} className="p-3 bg-white border border-slate-100 text-slate-400 hover:text-amber-600 rounded-xl hover:bg-amber-50 transition-all shadow-sm" title="Editar"><UserCog size={18} /></button>
                        <button onClick={() => handleDelete(student.uid)} className="p-3 bg-white border border-slate-100 text-slate-400 hover:text-rose-600 rounded-xl hover:bg-rose-50 transition-all shadow-sm" title="Remover"><Trash2 size={18} /></button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {isDetailModalOpen && selectedStudent && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-4xl rounded-[4rem] overflow-hidden flex flex-col shadow-2xl border-4 border-white/5 relative">
              <button onClick={() => setIsDetailModalOpen(false)} className="absolute top-10 right-10 p-4 bg-slate-100 rounded-full hover:bg-rose-600 hover:text-white transition-all z-10"><X size={24}/></button>
              <div className="p-16 space-y-12">
                 <header className="flex items-center gap-8">
                    <div className="w-24 h-24 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center text-3xl font-black italic shadow-2xl">{(selectedStudent.displayName||'U').charAt(0)}</div>
                    <div>
                      <h2 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{selectedStudent.displayName}</h2>
                      <p className="text-[11px] font-black text-indigo-600 uppercase italic mt-3 tracking-widest">Matrícula Acadêmica: {selectedStudent.academicId}</p>
                    </div>
                 </header>
                 <div className="grid grid-cols-2 lg:grid-cols-3 gap-8 text-slate-900">
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">E-mail de Contato</p><p className="text-sm font-bold">{selectedStudent.email}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Telefone Celular</p><p className="text-sm font-bold">{selectedStudent.telefone || '---'}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Documento (CPF/RG)</p><p className="text-sm font-bold">{selectedStudent.documento || '---'}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Endereço</p><p className="text-sm font-bold leading-tight">{selectedStudent.endereco?.rua}, {selectedStudent.endereco?.numero}<br/>{selectedStudent.endereco?.bairro} - {selectedStudent.endereco?.cidade}/{selectedStudent.endereco?.uf}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Login de Acesso</p><p className="text-sm font-bold text-indigo-600">{selectedStudent.username || '---'}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Cadastro em</p><p className="text-sm font-bold">{selectedStudent.createdAt?.seconds ? new Date(selectedStudent.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : '---'}</p></div>
                 </div>
                 <div className="pt-12 border-t border-slate-100 flex gap-4">
                    <button onClick={() => handleOpenEdit(selectedStudent)} className="flex-1 py-5 bg-slate-900 text-white rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all flex items-center justify-center gap-3"><Edit3 size={18}/> Editar Prontuário</button>
                    <button onClick={() => handleDelete(selectedStudent.uid)} className="px-10 py-5 bg-rose-50 text-rose-500 rounded-[1.5rem] text-[10px] font-black uppercase italic hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={18}/></button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {(isRegisterModalOpen || isEditModalOpen) && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/95 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
          <header className="bg-slate-900 p-8 lg:px-12 flex justify-between items-center border-b border-white/5">
             <div className="flex items-center gap-6"><div className={`p-5 rounded-[2rem] text-white ${isEditModalOpen ? 'bg-emerald-600' : 'bg-indigo-600'}`}>{isEditModalOpen ? <UserCog size={40} /> : <UserPlus size={40} />}</div><h2 className="text-3xl lg:text-4xl font-black text-white uppercase italic tracking-tighter leading-none">{isEditModalOpen ? 'Gestão Discente' : 'Nova Matrícula'}</h2></div>
             <button onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="p-5 bg-white/5 text-white rounded-full hover:bg-rose-600 transition-all"><X size={32}/></button>
          </header>
          <form onSubmit={handleSave} className="flex-1 overflow-y-auto bg-white flex flex-col items-center custom-scrollbar">
            <div className="w-full max-w-6xl p-12 lg:p-20 space-y-24 text-slate-900">
              <div className="space-y-12">
                <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">01</span><h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Identidade Discente</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Documento</label><input required value={formData.documento} onChange={e => setFormData({...formData, documento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">E-mail</label><input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Telefone</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Nascimento</label><input type="date" required value={formData.dataNascimento} onChange={e => setFormData({...formData, dataNascimento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                </div>
              </div>
              <div className="space-y-12">
                <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">02</span><h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Endereço Residencial</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                  <div className="md:col-span-8 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Rua / Logradouro</label><input value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Número</label><input value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Bairro</label><input value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Cidade</label><input value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm" /></div>
                  <div className="md:col-span-2 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">UF</label><input value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm uppercase" maxLength={2} /></div>
                </div>
              </div>
              <div className="space-y-12">
                <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">03</span><h3 className="text-xl font-black uppercase tracking-tight text-slate-900 italic">Segurança e Acesso</h3></div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                  <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Curso Matriz</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-[10px] uppercase shadow-inner"><option value="">Vincular Curso...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                  <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Usuário (Login)</label><input required value={formData.usuario} onChange={e => setFormData({...formData, usuario: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" /></div>
                  <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic">Senha Provisória</label><input type="password" required value={formData.senha} onChange={e => setFormData({...formData, senha: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-[1.5rem] font-black text-sm shadow-inner" /></div>
                </div>
              </div>
              <div className="pt-20 flex gap-6 pb-20">
                 <button type="button" onClick={() => { setIsRegisterModalOpen(false); setIsEditModalOpen(false); resetForm(); }} className="px-12 py-6 bg-slate-100 text-slate-400 rounded-[1.5rem] text-[11px] font-black uppercase italic">Descartar</button>
                 {isEditModalOpen && <button type="button" onClick={() => handleDelete(selectedStudent?.uid)} className="px-12 py-6 bg-rose-50 text-rose-500 rounded-[1.5rem] text-[11px] font-black uppercase italic hover:bg-rose-600 hover:text-white transition-all">Excluir Prontuário</button>}
                 <button disabled={actionLoading} type="submit" className={`flex-1 py-6 text-white rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.3em] italic shadow-2xl ${isEditModalOpen ? 'bg-emerald-600 shadow-emerald-200' : 'bg-indigo-600 shadow-indigo-200'}`}>{actionLoading ? 'Processando...' : <><Save size={20} className="inline mr-2"/> {isEditModalOpen ? 'Atualizar Dados' : 'Concluir Matrícula'}</>}</button>
              </div>
            </div>
          </form>
        </div>
      )}
    </div>
