                      </div>
                   </div>
                   <button className="w-full py-5 bg-white text-slate-900 rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl">Acessar Console de TI</button>
                </div>
                <FolderOpen size={300} className="absolute -bottom-24 -right-24 text-white/5 group-hover:scale-110 transition-transform duration-1000" />
             </div>
          </div>
        )}
      </main>

      {/* MODAL: NOVO PROTOCOLO INTERNO */}
      {isNewProtocolModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic">Novo Protocolo</h3>
                 <button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleOpenProtocol} className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Aluno / Solicitante</label><input required value={newProtocol.user} onChange={e => setNewProtocol({...newProtocol, user: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" placeholder="Nome completo do aluno..."/></div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Assunto</label><select value={newProtocol.subject} onChange={e => setNewProtocol({...newProtocol, subject: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase italic"><option>Acadêmico</option><option>Financeiro</option><option>Suporte Técnico</option></select></div>
                    <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Prioridade</label><select value={newProtocol.priority} onChange={e => setNewProtocol({...newProtocol, priority: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase italic"><option>Baixa</option><option>Média</option><option>Alta</option></select></div>
                 </div>
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Descrição da Demanda</label><textarea required value={newProtocol.description} onChange={e => setNewProtocol({...newProtocol, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-medium text-[11px] h-32 italic" placeholder="Explique o problema ou solicitação..."/></div>
                 <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-xl transition-all">Registrar Protocolo</button>
              </form>
           </div>
        </div>
      )}

      {/* MODAL: NOVO UPLOAD GED */}
      {isUploadModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic">Subir Arquivo</h3>
                 <button onClick={() => setIsUploadModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleFileUpload} className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Nome do Arquivo</label><input required value={uploadData.title} onChange={e => setUploadData({...uploadData, title: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" placeholder="Ex: Contrato_Aluno_2024.pdf"/></div>
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Categoria / Pasta</label><select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase italic"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select></div>
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">URL do Documento (Simulado)</label><input required value={uploadData.url} onChange={e => setUploadData({...uploadData, url: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" placeholder="Link do Drive ou Servidor..."/></div>
                 <button type="submit" className="w-full py-5 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-emerald-700 shadow-xl transition-all">Processar Upload</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type ChatFilter = 'abertos' | 'resolvidos' | 'arquivados';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicket, setSelectedTicket] = useState<any | null>(null);

  // Chat & Support States
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [chatMessage, setChatMessage] = useState('');
  const [activeChat, setActiveChat] = useState<any | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);

  // GED States
  const [selectedFolder, setSelectedFolder] = useState<string | null>(null);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas', url: '' });

  // Modais de Ação
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Escuta Real de Tickets
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Escuta Real de Arquivos (GED)
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    return () => { unsubTickets(); unsubFiles(); };
  }, []);

  // Escuta de mensagens do chat ativo
  useEffect(() => {
    if (!activeChat) return;
    const unsubChat = onSnapshot(
      query(collection(db, `tickets/${activeChat.id}/messages`), orderBy('timestamp', 'asc')),
      (snap) => {
        setChatHistory(snap.docs.map(d => d.data()));
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
      }
    );
    return () => unsubChat();
  }, [activeChat]);

  const stats = useMemo(() => ({
    pendentes: tickets.filter(t => t.status === 'Pendente').length,
    emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
    concluidos: tickets.filter(t => t.status === 'Fechado').length,
    documentos: files.length
  }), [tickets, files]);

  // Handlers Operacionais
  const handleOpenProtocol = async (e: React.FormEvent) => {
    e.preventDefault();
    const docRef = await addDoc(collection(db, 'tickets'), {
      ...newProtocol,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      protocolo: `PRT-${Date.now().toString().slice(-6)}`
    });
    setIsNewProtocolModalOpen(false);
    setNewProtocol({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !activeChat) return;
    const msg = chatMessage;
    setChatMessage('');
    await addDoc(collection(db, `tickets/${activeChat.id}/messages`), {
      text: msg,
      sender: 'Secretaria',
      timestamp: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', activeChat.id), {
      lastMessage: msg,
      lastUpdate: serverTimestamp()
    });
  };

  const handleArchiveTicket = async (id: string) => {
    if (confirm("Deseja arquivar este protocolo? Ele sairá da fila principal.")) {
      await updateDoc(doc(db, 'tickets', id), { archived: true, status: 'Arquivado' });
      setActiveChat(null);
    }
  };

  const handleDeleteTicket = async (id: string) => {
    if (confirm("AVISO: Excluir permanentemente este protocolo e todo o histórico de chat?")) {
      await deleteDoc(doc(db, 'tickets', id));
      setActiveChat(null);
    }
  };

  const handleFileUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    await addDoc(collection(db, 'secretaria_arquivos'), {
      ...uploadData,
      createdAt: serverTimestamp(),
      uploader: 'Secretaria'
    });
    setIsUploadModalOpen(false);
  };

  const filteredTickets = useMemo(() => {
    return tickets.filter(t => {
      const matchSearch = t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase());
      if (chatFilter === 'abertos') return matchSearch && !t.archived && t.status !== 'Fechado';
      if (chatFilter === 'resolvidos') return matchSearch && t.status === 'Fechado';
      if (chatFilter === 'arquivados') return matchSearch && t.archived;
      return matchSearch;
    });
  }, [tickets, searchTerm, chatFilter]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Secretaria Digital</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Centro de Operações Acadêmicas e Suporte Discente.</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-[1.5rem] border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button
              key={tab}
              onClick={() => { setActiveTab(tab); setSelectedFolder(null); }}
              className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${
                activeTab === tab ? 'bg-slate-900 text-white shadow-lg shadow-slate-200' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </header>

      {/* DASHBOARD RÁPIDO OPERACIONAL */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: 'Fila de Espera', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={20}/> },
          { label: 'Em Atendimento', value: stats.emAtendimento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <AlertCircle size={20}/> },
          { label: 'Resolvidos', value: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <CheckCircle2 size={20}/> },
          { label: 'Arquivos GED', value: stats.documentos, color: 'text-slate-600', bg: 'bg-slate-100', icon: <FolderOpen size={20}/> }
        ].map((s, i) => (
          <div key={i} className={`${s.bg} p-6 rounded-[2rem] border border-slate-200/50 flex items-center gap-5 shadow-sm`}>
            <div className={`p-4 bg-white rounded-2xl ${s.color} shadow-sm`}>{s.icon}</div>
            <div>
              <p className={`text-[8px] font-black uppercase tracking-widest ${s.color} italic mb-1`}>{s.label}</p>
              <p className="text-3xl font-black text-slate-900 tabular-nums leading-none tracking-tighter">{s.value}</p>
            </div>
          </div>
        ))}
      </div>

      <main className="min-h-[600px]">
        {/* ABA: ATENDIMENTO / PROTOCOLOS */}
        {activeTab === 'atendimento' && (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-bottom-4">
            <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between gap-4">
              <div className="relative flex-1 max-w-md">
                <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="Pesquisar protocolo, nome ou assunto..." 
                  className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-black outline-none shadow-inner"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
              <button onClick={() => setIsNewProtocolModalOpen(true)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all flex items-center gap-3">
                <Plus size={18}/> Abrir Protocolo Interno
              </button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                  <tr>
                    <th className="px-10 py-6">ID Protocolo</th>
                    <th className="px-10 py-6">Requerente</th>
                    <th className="px-10 py-6">Assunto Acadêmico</th>
                    <th className="px-10 py-6">Prioridade</th>
                    <th className="px-10 py-6">Status</th>
                    <th className="px-10 py-6">Ação</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px]">
                  {filteredTickets.length === 0 ? (
                    <tr><td colSpan={6} className="p-20 text-center text-slate-300 italic uppercase font-black text-xs tracking-widest">Nenhum registro localizado no banco.</td></tr>
                  ) : filteredTickets.map(t => (
                    <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors group">
                      <td className="px-10 py-6 font-mono font-bold text-indigo-600">{t.protocolo || `#${t.id.slice(0,5)}`}</td>
                      <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{t.user || 'Aluno da Escola'}</td>
                      <td className="px-10 py-6 font-bold text-slate-500 uppercase italic">{t.subject}</td>
                      <td className="px-10 py-6">
                        <span className={`px-3 py-1 rounded-full font-black uppercase italic ${
                          t.priority === 'Alta' ? 'bg-rose-50 text-rose-600' : 'bg-slate-100 text-slate-400'
                        }`}>{t.priority}</span>
                      </td>
                      <td className="px-10 py-6">
                        <span className={`px-3 py-1 rounded-full font-black uppercase italic border ${
                          t.status === 'Fechado' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'
                        }`}>{t.status}</span>
                      </td>
                      <td className="px-10 py-6">
                        <button onClick={() => { setSelectedTicket(t); setActiveTab('chat'); setActiveChat(t); }} className="p-3 bg-white border border-slate-100 rounded-xl text-slate-400 hover:text-indigo-600 shadow-sm transition-all flex items-center gap-2"><MessageSquare size={14}/> Responder</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ABA: CHAT DE SUPORTE REAL */}
        {activeTab === 'chat' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[700px] animate-in slide-in-from-right-4 duration-500">
            {/* Lista de Conversas / Filtros */}
            <div className="lg:col-span-4 bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
              <div className="p-6 border-b border-slate-100 bg-slate-50/50 flex gap-2">
                {(['abertos', 'resolvidos', 'arquivados'] as ChatFilter[]).map(f => (
                  <button 
                    key={f}
                    onClick={() => setChatFilter(f)}
                    className={`flex-1 py-3 rounded-xl text-[8px] font-black uppercase tracking-widest transition-all ${
                      chatFilter === f ? 'bg-slate-900 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-200'
                    }`}
                  >
                    {f}
                  </button>
                ))}
              </div>
              <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                {filteredTickets.map(t => (
                  <div 
                    key={t.id} 
                    onClick={() => setActiveChat(t)}
                    className={`p-6 rounded-[2rem] border transition-all cursor-pointer flex items-center gap-4 ${
                      activeChat?.id === t.id ? 'bg-indigo-600 border-indigo-500 text-white shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white hover:border-indigo-100'
                    }`}
                  >
                    <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center font-black italic">{(t.user||'A').charAt(0)}</div>
                    <div className="flex-1 overflow-hidden">
                      <p className="text-xs font-black uppercase italic tracking-tight truncate">{t.user || 'Sem Nome'}</p>
                      <p className={`text-[8px] font-bold uppercase mt-1 truncate ${activeChat?.id === t.id ? 'text-indigo-200' : 'text-slate-400'}`}>{t.lastMessage || t.subject}</p>
                    </div>
                    <div className="text-right">
                       <p className={`text-[7px] font-black uppercase ${activeChat?.id === t.id ? 'text-indigo-200' : 'text-slate-300'}`}>{t.protocolo}</p>
                    </div>
                  </div>
                ))}
                {filteredTickets.length === 0 && <p className="p-10 text-center text-[9px] font-black uppercase text-slate-300 italic">Vazio.</p>}
              </div>
            </div>

            {/* Janela de Mensagens */}
            <div className="lg:col-span-8 bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col relative">
              {activeChat ? (
                <>
                  <div className="p-8 border-b border-slate-100 flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 font-black italic shadow-inner">{activeChat.user.charAt(0)}</div>
                      <div>
                        <h4 className="text-sm font-black text-slate-900 uppercase italic tracking-tighter">{activeChat.user}</h4>
                        <span className="text-[8px] font-black uppercase text-indigo-600 tracking-widest">{activeChat.protocolo}</span>
                      </div>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => handleArchiveTicket(activeChat.id)} className="p-3 bg-slate-50 text-slate-400 hover:text-amber-600 rounded-xl border border-slate-100 transition-all" title="Arquivar"><Archive size={18}/></button>
                      <button onClick={() => handleDeleteTicket(activeChat.id)} className="p-3 bg-slate-50 text-slate-400 hover:text-rose-600 rounded-xl border border-slate-100 transition-all" title="Excluir"><Trash2 size={18}/></button>
                      <button onClick={() => setActiveChat(null)} className="p-3 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-xl border border-slate-100 transition-all"><X size={18}/></button>
                    </div>
                  </div>
                  <div className="flex-1 overflow-y-auto p-10 space-y-6 bg-slate-50/30 custom-scrollbar">
                    {chatHistory.map((m, i) => (
                      <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                         <div className={`max-w-[80%] p-6 rounded-[2rem] shadow-sm ${
                           m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-600 rounded-tl-none'
                         }`}>
                           <p className="text-xs font-medium italic leading-relaxed">{m.text}</p>
                         </div>
                         <span className="text-[7px] font-bold text-slate-300 uppercase mt-2 px-2">{m.timestamp?.seconds ? new Date(m.timestamp.seconds * 1000).toLocaleTimeString() : 'Enviando...'}</span>
                      </div>
                    ))}
                    <div ref={chatEndRef} />
                  </div>
                  <div className="p-8 border-t border-slate-100">
                    <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-[2rem] border border-slate-100 shadow-inner">
                      <button className="p-4 text-slate-400 hover:text-indigo-600 transition-all"><Paperclip size={22}/></button>
                      <input 
                        type="text" 
                        placeholder="Escreva sua resposta para o aluno..." 
                        className="flex-1 bg-transparent border-none outline-none text-xs font-bold italic py-4"
                        value={chatMessage}
                        onChange={e => setChatMessage(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleSendMessage()}
                      />
                      <button onClick={handleSendMessage} className="p-4 bg-slate-900 text-white rounded-full hover:bg-indigo-600 transition-all shadow-xl"><Send size={22}/></button>
                    </div>
                  </div>
                </>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center p-20 text-center space-y-6 opacity-20 italic">
                  <MessageSquare size={80} className="text-slate-300" />
                  <p className="text-[10px] font-black uppercase tracking-[0.5em]">Selecione um atendimento para carregar o histórico</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* ABA: ARQUIVOS GED CATEGORIZADO */}
        {activeTab === 'arquivos' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            {selectedFolder ? (
              <div className="space-y-6 animate-in slide-in-from-right-4">
                 <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex justify-between items-center">
                    <div className="flex items-center gap-4">
                       <button onClick={() => setSelectedFolder(null)} className="p-3 bg-slate-50 rounded-xl hover:bg-indigo-50 text-indigo-600 transition-all"><X size={20}/></button>
                       <h3 className="text-xl font-black text-slate-900 uppercase italic">Diretório: {selectedFolder}</h3>
                    </div>
                    <button onClick={() => { setUploadData({...uploadData, category: selectedFolder}); setIsUploadModalOpen(true); }} className="px-8 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic hover:bg-emerald-600 transition-all flex items-center gap-3"><Upload size={18}/> Novo Item</button>
                 </div>
                 <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
                    <table className="w-full text-left">
                       <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase border-b">
