                          <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-2">{count} Arquivos Reais</p>
                       </div>
                     );
                   })}
                </div>
              </>
            )}
          </div>
        )}

        {/* ABA: OPERACIONAL (WORKFLOW) */}
        {activeTab === 'operacional' && (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in zoom-in-95 duration-500">
             <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-10">
                <div className="flex items-center justify-between border-b border-slate-50 pb-8">
                   <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Ações Acadêmicas Rápidas</h3>
                </div>
                <div className="space-y-4">
                   {[
                     { label: 'Emitir Declaração de Matrícula', icon: <Printer size={18}/>, action: () => alert("Módulo de Impressão de Declaração Carregado.") },
                     { label: 'Validar Documentos Pendentes', icon: <Check size={18}/>, badge: '5' },
                     { label: 'Transferência Interna de Aluno', icon: <Send size={18}/> },
                     { label: 'Gerar Relatório de Inadimplência', icon: <AlertCircle size={18}/> }
                   ].map((action, i) => (
                     <button key={i} onClick={action.action} className="w-full flex items-center justify-between p-6 bg-slate-50 hover:bg-slate-900 hover:text-white rounded-[1.5rem] transition-all group border border-slate-100">
                        <div className="flex items-center gap-4 text-[10px] font-black uppercase italic tracking-widest">
                           <span className="p-2.5 bg-white text-slate-400 rounded-lg shadow-sm group-hover:text-indigo-600 transition-colors">{action.icon}</span>
                           {action.label}
