             </div>

             <div className="bg-slate-900 p-10 rounded-[3rem] shadow-2xl text-white relative overflow-hidden group">
                <div className="relative z-10 space-y-12">
                   <div className="flex items-center justify-between">
                     <h3 className="text-xl font-black uppercase italic tracking-tighter text-indigo-400">Status do Sistema ERP</h3>
                     <span className="px-4 py-1.5 bg-emerald-600/20 text-emerald-400 rounded-full text-[8px] font-black uppercase italic border border-emerald-500/30 flex items-center gap-2 shadow-xl"><div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></div> Servidores Ativos</span>
                   </div>
                   <div className="space-y-6 pt-10">
                      <div className="flex items-center justify-between border-b border-white/5 pb-5">
                         <span className="text-[10px] font-black uppercase text-white/40 italic">Uptime Mensal</span>
                         <span className="text-2xl font-black tracking-tighter italic">99.98%</span>
                      </div>
                      <div className="flex items-center justify-between border-b border-white/5 pb-5">
                         <span className="text-[10px] font-black uppercase text-white/40 italic">Backups em Nuvem</span>
                         <span className="text-2xl font-black tracking-tighter italic">Sincronizado</span>
                      </div>
                      <div className="flex items-center justify-between">
                         <span className="text-[10px] font-black uppercase text-white/40 italic">Carga de Trabalho</span>
                         <span className="text-2xl font-black tracking-tighter italic">Normal</span>
                      </div>
                   </div>
                   <button className="w-full py-5 bg-white text-slate-900 rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-[0.2em] hover:bg-indigo-600 hover:text-white transition-all shadow-2xl">Acessar Console de TI</button>
                </div>
                <FolderOpen size={300} className="absolute -bottom-24 -right-24 text-white/5 group-hover:scale-110 transition-transform duration-1000" />
             </div>
          </div>
        )}
      </main>

      {/* MODAL: NOVO PROTOCOLO INTERNO */}
      {isNewProtocolModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic">Novo Protocolo</h3>
                 <button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleOpenProtocol} className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Aluno / Solicitante</label><input required value={newProtocol.user} onChange={e => setNewProtocol({...newProtocol, user: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" placeholder="Nome completo do aluno..."/></div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Assunto</label><select value={newProtocol.subject} onChange={e => setNewProtocol({...newProtocol, subject: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase italic"><option>Acadêmico</option><option>Financeiro</option><option>Suporte Técnico</option></select></div>
                    <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Prioridade</label><select value={newProtocol.priority} onChange={e => setNewProtocol({...newProtocol, priority: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase italic"><option>Baixa</option><option>Média</option><option>Alta</option></select></div>
                 </div>
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Descrição da Demanda</label><textarea required value={newProtocol.description} onChange={e => setNewProtocol({...newProtocol, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-medium text-[11px] h-32 italic" placeholder="Explique o problema ou solicitação..."/></div>
                 <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-xl transition-all">Registrar Protocolo</button>
              </form>
           </div>
        </div>
      )}

      {/* MODAL: NOVO UPLOAD GED */}
      {isUploadModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic">Subir Arquivo</h3>
                 <button onClick={() => setIsUploadModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleFileUpload} className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Nome do Arquivo</label><input required value={uploadData.title} onChange={e => setUploadData({...uploadData, title: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" placeholder="Ex: Contrato_Aluno_2024.pdf"/></div>
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Categoria / Pasta</label><select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase italic"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select></div>
                 <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">URL do Documento (Simulado)</label><input required value={uploadData.url} onChange={e => setUploadData({...uploadData, url: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" placeholder="Link do Drive ou Servidor..."/></div>
                 <button type="submit" className="w-full py-5 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-emerald-700 shadow-xl transition-all">Processar Upload</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicket, setSelectedTicket] = useState<any | null>(null);
  const [dirSignature, setDirSignature] = useState<string | null>(null);

  // Operational States
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos para os devidos fins que o aluno(a) acima citado encontra-se devidamente matriculado nesta instituição de ensino teológico.');

  // GED States
  const [selectedFolder, setSelectedFolder] = useState<string | null>(null);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas', content: '' });

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });

    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const fetchSignature = async () => {
      // Busca assinatura do diretor nas configurações (assumindo que o primeiro admin é o diretor)
      const q = query(collection(db, 'users'), where('role', '==', 'diretor'));
      const snap = await getDocs(q);
      if (!snap.empty) setDirSignature(snap.docs[0].data().signatureUrl);
    };

    fetchSignature();
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  // Handlers
  const handleValidateStudent = async (studentId: string) => {
    await updateDoc(doc(db, 'users', studentId), { status: 'ativo', validatedAt: serverTimestamp() });
    // Gera arquivo automático de matrícula validada
    const student = students.find(s => s.uid === studentId);
    await addDoc(collection(db, 'secretaria_arquivos'), {
      title: `Ficha_Validada_${student.displayName}.pdf`,
      category: 'Matrículas',
      uploader: 'Sistema Automação',
      createdAt: serverTimestamp(),
      studentId: studentId
    });
  };

  const handleTransferStudent = async (studentId: string, newCourseId: string) => {
    const oldCourse = students.find(s => s.uid === studentId)?.cursoInicial;
    await updateDoc(doc(db, 'users', studentId), { cursoInicial: newCourseId });
    await addDoc(collection(db, 'secretaria_arquivos'), {
      title: `Termo_Transferencia_${studentId}.pdf`,
      category: 'Históricos',
      uploader: 'Sistema Automação',
      description: `Transferido do curso ${oldCourse} para ${newCourseId}`,
      createdAt: serverTimestamp()
    });
    alert("Transferência realizada e registrada no Histórico.");
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: file.name,
        category: uploadData.category,
        content: event.target?.result, // Base64 do documento real
        uploader: 'Secretaria',
        createdAt: serverTimestamp()
      });
      setIsUploadModalOpen(false);
    };
    reader.readAsDataURL(file);
  };

  // Views Operacionais
  const renderOperationalView = () => {
    switch(opSubView) {
      case 'declaracao':
        return (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-xl max-w-4xl mx-auto">
              <header className="flex justify-between items-start border-b-2 border-slate-900 pb-10 mb-10">
                <div className="flex items-center gap-4">
                   <div className="bg-slate-900 p-3 rounded-xl text-white"><FileBadge size={32}/></div>
                   <div className="font-black italic text-slate-900 leading-none">
                      <p className="text-xl">ESCOLA BÍBLICA EAD</p>
                      <p className="text-[10px] uppercase tracking-widest mt-1">Secretaria Acadêmica Master</p>
                   </div>
                </div>
                <div className="text-right">
                  <p className="text-[9px] font-black uppercase text-slate-400 italic">Documento Oficial</p>
                  <p className="text-xs font-mono font-bold">DEC-{Date.now().toString().slice(-6)}</p>
                </div>
              </header>

              <div className="space-y-10">
                <h2 className="text-2xl font-black text-center uppercase italic tracking-tighter">Declaração de Matrícula</h2>
                <div className="space-y-6">
                   <div className="space-y-1.5">
                      <label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Selecionar Aluno</label>
                      <select 
                        onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))}
                        className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner appearance-none"
                      >
                        <option value="">Escolha o aluno para preenchimento...</option>
                        {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                      </select>
                   </div>

                   <div className="p-10 bg-slate-50 rounded-[2rem] border-2 border-dashed border-slate-200">
                      <textarea 
                        value={declContent}
                        onChange={(e) => setDeclContent(e.target.value)}
                        className="w-full bg-transparent border-none outline-none text-sm font-medium italic leading-relaxed h-40 resize-none"
                      />
                      {selectedStudentForDecl && (
                        <div className="mt-6 pt-6 border-t border-slate-200 space-y-2">
                          <p className="text-xs font-black uppercase italic">Aluno: {selectedStudentForDecl.displayName}</p>
                          <p className="text-xs font-black uppercase italic text-indigo-600">Curso: {courses.find(c => c.id === selectedStudentForDecl.cursoInicial)?.nome}</p>
                        </div>
                      )}
                   </div>
                </div>

                <footer className="pt-20 flex flex-col items-center">
                   {dirSignature ? (
                     <img src={dirSignature} alt="Assinatura Diretor" className="h-20 grayscale mb-2" />
                   ) : (
                     <div className="h-20 w-48 border-b border-slate-300 mb-2"></div>
                   )}
                   <p className="text-[10px] font-black uppercase tracking-widest">Direção Acadêmica</p>
                </footer>
              </div>

              <div className="mt-12 flex gap-4 no-print">
                <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Cancelar</button>
                <button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-2xl flex items-center justify-center gap-3"><Printer size={18}/> Imprimir e Gerar PDF</button>
              </div>
            </div>
          </div>
        );

      case 'validacao':
        const pending = students.filter(s => s.status === 'pendente' || !s.status);
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-4">
             <div className="p-8 border-b border-slate-100 bg-slate-50/50 flex items-center justify-between">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Validação de Novos Alunos</h3>
                <button onClick={() => setOpSubView('main')} className="p-3 bg-white border border-slate-100 rounded-xl"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                      <tr><th className="px-10 py-6">Inscrito</th><th className="px-10 py-6">Data Cadastro</th><th className="px-10 py-6">Curso Pretendido</th><th className="px-10 py-6 text-center">Ação</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pending.length === 0 ? (
                        <tr><td colSpan={4} className="p-20 text-center text-slate-300 italic uppercase font-black">Nenhum aluno aguardando validação.</td></tr>
                      ) : pending.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50/10 transition-colors">
                           <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-10 py-6 font-bold text-slate-400">{new Date(s.createdAt?.seconds * 1000).toLocaleDateString()}</td>
                           <td className="px-10 py-6 font-black text-indigo-500 uppercase italic">{courses.find(c => c.id === s.cursoInicial)?.nome}</td>
                           <td className="px-10 py-6 flex justify-center gap-3">
                              <button onClick={() => handleValidateStudent(s.uid)} className="px-6 py-2.5 bg-emerald-600 text-white rounded-xl font-black uppercase italic text-[9px] hover:bg-emerald-700 shadow-lg">Validar Acesso</button>
                              <button className="px-6 py-2.5 bg-rose-50 text-rose-500 rounded-xl font-black uppercase italic text-[9px]">Recusar</button>
                           </td>
                        </tr>
