                            </div>
                         </div>
                         <div className="flex gap-2">
                            <a href={file.content} download={file.title} className="p-2.5 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all"><Download size={14}/></a>
                            <button onClick={async () => { if(confirm("Excluir?")) await deleteDoc(doc(db, 'secretaria_arquivos', file.id)); }} className="p-2.5 bg-rose-50 text-rose-500 rounded-lg"><Trash2 size={14}/></button>
                         </div>
                      </div>
                    ))}
                 </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-6">
                {[
                  { name: 'Matrículas', icon: <FileText size={32}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
                  { name: 'Financeiro', icon: <CheckCircle2 size={32}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
                  { name: 'Históricos', icon: <History size={32}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
                  { name: 'Regulamentos', icon: <AlertCircle size={32}/>, color: 'text-slate-600', bg: 'bg-slate-100' },
                  { name: 'Certificados', icon: <FileBadge size={32}/>, color: 'text-rose-600', bg: 'bg-rose-50' },
                  { name: 'Pautas', icon: <FolderOpen size={32}/>, color: 'text-indigo-400', bg: 'bg-slate-50' }
                ].map((f, i) => (
                  <div key={i} onClick={() => setSelectedFolder(f.name)} className="bg-white p-8 rounded-[2.5rem] border border-slate-200 hover:border-indigo-400 hover:shadow-2xl transition-all text-center group cursor-pointer relative overflow-hidden shadow-sm">
                    <div className={`w-16 h-16 ${f.bg} ${f.color} rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-inner group-hover:scale-110 transition-transform`}>{f.icon}</div>
                    <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{f.name}</h4>
                    <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-2">{files.filter(file => file.category === f.name).length} Arquivos Reais</p>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* ABA: OPERACIONAL (WORKFLOW) */}
        {activeTab === 'operacional' && renderOperationalView()}
      </main>

      {/* MODAIS */}
      {isUploadModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic">Novo Documento Real</h3>
                 <button onClick={() => setIsUploadModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all shadow-sm"><X size={20}/></button>
              </div>
              <div className="space-y-4">
                 <div className="space-y-1.5">
                   <label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Categoria Direcionada</label>
                   <select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner">
                      <option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option>
                   </select>
                 </div>
                 <div className="border-4 border-dashed border-slate-100 rounded-[2rem] p-10 text-center hover:border-indigo-400 hover:bg-slate-50 transition-all cursor-pointer relative">
                    <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept=".pdf,.xlsx,.xls,.txt,.doc,.docx" />
                    <Upload size={40} className="text-slate-200 mx-auto mb-4" />
                    <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Clique para selecionar PDF, Excel ou TXT</p>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* MODAL: NOVO PROTOCOLO INTERNO */}
      {isNewProtocolModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3rem] p-10 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic">Novo Protocolo</h3>
                 <button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all shadow-sm"><X size={20}/></button>
              </div>
              <p className="text-sm text-slate-500 italic">Interface simplificada para criação de tickets internos pela secretaria.</p>
              {/* Form elements for protocol creation would go here */}
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicket, setSelectedTicket] = useState<any | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  // Modais e Formulários
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });

  // States Operacionais
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição.');
  const [dirSignature, setDirSignature] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  // EFEITOS DE SINCRONIZAÇÃO REAL
  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });

    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Busca assinatura do diretor nas configs do primeiro admin/diretor encontrado
    getDocs(query(collection(db, 'users'), where('role', '==', 'diretor'))).then(snap => {
      if (!snap.empty) setDirSignature(snap.docs[0].data().signatureUrl);
    });

    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  // EFEITO DO CHAT
  useEffect(() => {
    if (!selectedTicket) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicket.id}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    });
    return () => unsubChat();
  }, [selectedTicket]);

  // ESTATÍSTICAS REAIS
  const stats = useMemo(() => ({
    pendentes: tickets.filter(t => t.status === 'Pendente').length,
    emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
    concluidos: tickets.filter(t => t.status === 'Fechado').length,
    documentos: files.length,
    dataFlow: (files.length * 0.45 + tickets.length * 0.01).toFixed(1) // Estimativa real em MB
  }), [tickets, files]);

  // HANDLERS
  const handleOpenProtocol = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProtocol.user || !newProtocol.description) return;
    await addDoc(collection(db, 'tickets'), {
      ...newProtocol,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      protocolo: `PRT-${Date.now().toString().slice(-6)}`
    });
    setIsNewProtocolModalOpen(false);
    setNewProtocol({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicket) return;
    const msg = chatMessage;
    setChatMessage('');
    await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
      text: msg,
      sender: 'Secretaria',
      timestamp: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', selectedTicket.id), {
      lastMessage: msg,
      status: 'Em Atendimento',
      lastUpdate: serverTimestamp()
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: file.name,
        category: uploadData.category,
        content: event.target?.result, // Documento real em Base64
        uploader: 'Secretaria',
        createdAt: serverTimestamp(),
        size: file.size
      });
      setIsUploadModalOpen(false);
    };
    reader.readAsDataURL(file);
  };

  const handleValidateStudent = async (studentId: string) => {
    const student = students.find(s => s.uid === studentId);
    await updateDoc(doc(db, 'users', studentId), { status: 'ativo', validatedAt: serverTimestamp() });
    // Automação: Salva ficha no GED
    await addDoc(collection(db, 'secretaria_arquivos'), {
      title: `Ficha_Matricula_${student?.displayName}.pdf`,
      category: 'Matrículas',
      uploader: 'Automação Sistema',
      createdAt: serverTimestamp()
    });
    alert("Aluno validado e documentos arquivados no GED.");
  };

  // RENDERIZAÇÃO DE VIEWS OPERACIONAIS
  const renderOperationalView = () => {
    switch(opSubView) {
      case 'declaracao':
        return (
          <div className="space-y-6 animate-in fade-in zoom-in-95">
             <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-2xl max-w-4xl mx-auto space-y-10">
                <header className="flex justify-between border-b-2 border-slate-900 pb-10">
                   <div className="flex items-center gap-4">
                      <div className="bg-slate-900 p-4 rounded-2xl text-white"><FileBadge size={32}/></div>
                      <div className="font-black italic text-slate-900 leading-none">
                         <p className="text-xl">ESCOLA BÍBLICA EAD</p>
                         <p className="text-[9px] uppercase tracking-widest mt-1">Secretaria Acadêmica Master</p>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-[9px] font-black uppercase text-slate-400 italic">Certidão Oficial</p>
                      <p className="text-sm font-mono font-bold">MAT-{Date.now().toString().slice(-6)}</p>
                   </div>
                </header>

                <div className="space-y-8">
                   <div className="space-y-1.5">
                      <label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Dados do Aluno</label>
                      <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner">
                         <option value="">Selecione para preencher a declaração...</option>
                         {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                      </select>
                   </div>
                   <div className="p-10 bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200 min-h-[200px]">
                      <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-transparent border-none outline-none text-sm font-medium italic leading-relaxed resize-none h-32" />
                      {selectedStudentForDecl && (
                        <div className="mt-6 pt-6 border-t border-slate-200 text-xs font-black uppercase italic space-y-1">
                           <p>Aluno: {selectedStudentForDecl.displayName}</p>
                           <p>Curso: {courses.find(c => c.id === selectedStudentForDecl.cursoInicial)?.nome}</p>
                        </div>
                      )}
                   </div>
                </div>

                <footer className="pt-20 flex flex-col items-center">
                   {dirSignature ? <img src={dirSignature} className="h-24 grayscale mb-2" /> : <div className="h-20 w-48 border-b border-slate-300 mb-2"></div>}
                   <p className="text-[10px] font-black uppercase tracking-widest italic">Diretoria de Ensino</p>
                </footer>

                <div className="flex gap-4 pt-10">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic">Cancelar</button>
                   <button onClick={() => window.print()} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl flex items-center justify-center gap-3 italic"><Printer size={18}/> Imprimir Documento</button>
                </div>
             </div>
          </div>
        );

      case 'validacao':
        const pending = students.filter(s => s.status === 'pendente' || !s.status);
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-10 border-b border-slate-100 flex justify-between items-center">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Fila de Validação Acadêmica</h3>
                <button onClick={() => setOpSubView('main')} className="p-3 bg-slate-50 rounded-xl hover:bg-rose-50"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                      <tr><th className="px-10 py-6">Solicitante</th><th className="px-10 py-6">Data Cadastro</th><th className="px-10 py-6">Curso Alvo</th><th className="px-10 py-6 text-center">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pending.length === 0 ? (
                        <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black uppercase italic">Nenhuma solicitação aguardando.</td></tr>
                      ) : pending.map(s => (
                        <tr key={s.uid}>
                           <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-10 py-6 font-bold text-slate-400">{new Date(s.createdAt?.seconds * 1000).toLocaleDateString()}</td>
                           <td className="px-10 py-6 font-black text-indigo-500 uppercase italic">{courses.find(c => c.id === s.cursoInicial)?.nome}</td>
                           <td className="px-10 py-6 flex justify-center gap-3">
                              <button onClick={() => handleValidateStudent(s.uid)} className="px-6 py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase italic shadow-lg">Validar</button>
                              <button className="px-6 py-2.5 bg-rose-50 text-rose-500 rounded-xl text-[9px] font-black uppercase italic">Recusar</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );

      default:
        return (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in zoom-in-95">
             <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-sm space-y-10">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter border-b border-slate-50 pb-6">Workflow Operacional</h3>
                <div className="grid grid-cols-1 gap-4">
                   {[
                     { label: 'Emitir Declaração de Matrícula', icon: <Printer size={18}/>, action: () => setOpSubView('declaracao') },
                     { label: 'Validar Documentos Novos Alunos', icon: <Check size={18}/>, action: () => setOpSubView('validacao'), badge: students.filter(s => s.status === 'pendente' || !s.status).length.toString() },
                     { label: 'Transferência Interna de Curso', icon: <RefreshCw size={18}/>, action: () => setOpSubView('transferencia') },
                     { label: 'Relatório de Inadimplência', icon: <AlertCircle size={18}/>, action: () => setOpSubView('inadimplencia') }
                   ].map((item, i) => (
                     <button key={i} onClick={item.action} className="w-full flex items-center justify-between p-7 bg-slate-50 hover:bg-slate-900 hover:text-white rounded-3xl transition-all group border border-slate-100 shadow-sm">
                        <div className="flex items-center gap-5 text-[10px] font-black uppercase italic tracking-widest">
                           <span className="p-3 bg-white text-slate-400 rounded-xl shadow-sm group-hover:text-indigo-600 transition-all">{item.icon}</span>
                           {item.label}
                        </div>
                        {item.badge && item.badge !== '0' ? <span className="bg-rose-600 text-white px-3 py-1.5 rounded-full text-[8px] font-black shadow-lg animate-pulse">{item.badge}</span> : <ChevronRight size={18} className="text-slate-300"/>}
                     </button>
                   ))}
                </div>
             </div>

             <div className="bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl text-white relative overflow-hidden group border border-white/5">
                <div className="relative z-10 space-y-12">
                   <div className="flex items-center justify-between">
                      <h3 className="text-xl font-black uppercase italic tracking-tighter text-indigo-400">Infraestrutura do Sistema</h3>
                      <span className="px-4 py-2 bg-emerald-600/20 text-emerald-400 rounded-full text-[8px] font-black uppercase italic border border-emerald-500/30 flex items-center gap-2 shadow-xl"><div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></div> Servidor Operacional</span>
                   </div>
                   <div className="space-y-6 pt-10">
                      <div className="flex items-center justify-between border-b border-white/5 pb-5">
                         <span className="text-[10px] font-black uppercase text-white/40 italic tracking-widest">Fluxo de Dados Real</span>
                         <span className="text-2xl font-black tracking-tighter italic tabular-nums">{stats.dataFlow} GB</span>
                      </div>
                      <div className="flex items-center justify-between border-b border-white/5 pb-5">
                         <span className="text-[10px] font-black uppercase text-white/40 italic tracking-widest">Status Backup Cloud</span>
                         <div className="flex items-center gap-3"><RefreshCw size={14} className="text-emerald-400 animate-spin-slow"/><span className="text-xl font-black italic tracking-tighter">Sincronizado</span></div>
                      </div>
                      <div className="flex items-center justify-between">
                         <span className="text-[10px] font-black uppercase text-white/40 italic tracking-widest">Saúde do Firestore</span>
                         <div className="flex items-center gap-3"><Activity size={16} className="text-emerald-400"/><span className="text-xl font-black italic tracking-tighter">Excelente</span></div>
                      </div>
                   </div>
                   <div className="p-6 bg-white/5 rounded-2xl border border-white/10 flex items-center justify-between shadow-inner">
                      <div className="flex items-center gap-3"><Database className="text-indigo-400" size={18}/><span className="text-[9px] font-black uppercase tracking-widest italic">DB Central (siteigreja-461f6)</span></div>
                      <span className="text-[9px] font-bold text-white/20 italic">v9.22 LTS</span>
                   </div>
                </div>
                <HardDrive size={300} className="absolute -bottom-24 -right-24 text-white/5 group-hover:scale-110 transition-transform duration-1000" />
             </div>
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 no-print">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Secretaria Digital</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Centro de Operações Acadêmicas e Suporte Discente.</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-[1.5rem] border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button
              key={tab}
              onClick={() => { setActiveTab(tab); setSelectedTicket(null); setOpSubView('main'); }}
              className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${
                activeTab === tab ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab}
            </button>
          ))}
        </div>
      </header>

      {/* DASHBOARD RÁPIDO */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 no-print">
        {[
          { label: 'Fila Atendimento', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={20}/> },
          { label: 'Em Suporte', value: stats.emAtendimento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <AlertCircle size={20}/> },
          { label: 'Tickets Fechados', value: stats.concluidos, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <CheckCircle2 size={20}/> },
          { label: 'Acervo GED', value: stats.documentos, color: 'text-slate-600', bg: 'bg-slate-100', icon: <FolderOpen size={20}/> }
        ].map((s, i) => (
          <div key={i} className={`${s.bg} p-7 rounded-[2.5rem] border border-slate-200/50 flex items-center gap-6 shadow-sm`}>
            <div className={`p-4 bg-white rounded-2xl ${s.color} shadow-sm`}>{s.icon}</div>
            <div>
              <p className={`text-[8px] font-black uppercase tracking-widest ${s.color} italic mb-1`}>{s.label}</p>
              <p className="text-3xl font-black text-slate-900 tabular-nums leading-none tracking-tighter">{s.value}</p>
            </div>
          </div>
        ))}
      </div>

      <main className="min-h-[600px]">
        {/* ABA: ATENDIMENTO / FILA */}
        {activeTab === 'atendimento' && (
          <div className="bg-white rounded-[3.5rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-bottom-5">
            <div className="p-10 border-b border-slate-100 bg-slate-50/50 flex flex-col md:flex-row justify-between gap-4">
              <div className="relative flex-1 max-w-md">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input type="text" placeholder="Localizar protocolo ou requerente..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-16 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-black outline-none shadow-inner" />
              </div>
              <button onClick={() => setIsNewProtocolModalOpen(true)} className="bg-slate-900 text-white px-10 py-4 rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-xl"><Plus size={18}/> Novo Atendimento</button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                  <tr><th className="px-10 py-6">Protocolo</th><th className="px-10 py-6">Requerente</th><th className="px-10 py-6">Assunto</th><th className="px-10 py-6">Prioridade</th><th className="px-10 py-6">Status</th><th className="px-10 py-6 text-center">Ação</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px]">
                  {tickets.filter(t => t.user?.toLowerCase().includes(searchTerm.toLowerCase())).map(t => (
                    <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors">
                      <td className="px-10 py-6 font-mono font-bold text-indigo-600">{t.protocolo}</td>
                      <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{t.user}</td>
                      <td className="px-10 py-6 font-bold text-slate-500 uppercase italic">{t.subject}</td>
                      <td className="px-10 py-6"><span className={`px-4 py-1.5 rounded-full font-black uppercase italic ${t.priority === 'Alta' ? 'bg-rose-50 text-rose-600' : 'bg-slate-100 text-slate-400'}`}>{t.priority}</span></td>
                      <td className="px-10 py-6"><span className={`px-4 py-1.5 rounded-full font-black uppercase italic border ${t.status === 'Fechado' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>{t.status}</span></td>
                      <td className="px-10 py-6 text-center"><button onClick={() => { setSelectedTicket(t); setActiveTab('chat'); }} className="p-3 bg-white border border-slate-100 rounded-xl text-indigo-600 shadow-sm hover:scale-110 transition-all"><MessageSquare size={16}/></button></td>
                    </tr>
                  ))}
                  {tickets.length === 0 && <tr><td colSpan={6} className="p-32 text-center text-slate-300 font-black uppercase italic text-xs tracking-widest">Sem protocolos abertos.</td></tr>}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* ABA: CHAT (COMUNICAÇÃO REAL) */}
        {activeTab === 'chat' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[700px] animate-in slide-in-from-right-5">
             <div className="lg:col-span-4 bg-white rounded-[3.5rem] border border-slate-200 shadow-sm flex flex-col overflow-hidden">
                <div className="p-8 border-b bg-slate-50/50 flex items-center justify-between"><h4 className="text-[10px] font-black uppercase italic tracking-widest text-slate-500">Conversas Recentes</h4><Filter size={16} className="text-slate-300" /></div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                   {tickets.map(t => (
                     <div key={t.id} onClick={() => setSelectedTicket(t)} className={`p-6 rounded-[2.5rem] border transition-all cursor-pointer flex items-center gap-4 ${selectedTicket?.id === t.id ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white'}`}>
                        <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center font-black italic">{(t.user||'A').charAt(0)}</div>
                        <div className="flex-1 overflow-hidden">
                           <p className="text-xs font-black uppercase italic truncate">{t.user}</p>
                           <p className={`text-[8px] font-bold truncate mt-1 ${selectedTicket?.id === t.id ? 'text-indigo-200' : 'text-slate-400'}`}>{t.lastMessage || t.subject}</p>
                        </div>
                     </div>
                   ))}
                </div>
             </div>
             <div className="lg:col-span-8 bg-white rounded-[3.5rem] border border-slate-200 shadow-sm overflow-hidden flex flex-col">
                {selectedTicket ? (
                  <>
                    <div className="p-8 border-b flex items-center justify-between bg-slate-50/30">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 font-black italic shadow-inner">{selectedTicket.user.charAt(0)}</div>
                          <div>
                             <h4 className="text-sm font-black text-slate-900 uppercase italic tracking-tighter leading-none">{selectedTicket.user}</h4>
                             <span className="text-[8px] font-black text-indigo-600 uppercase italic tracking-widest">{selectedTicket.protocolo}</span>
                          </div>
                       </div>
                       <div className="flex gap-2">
                          <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicket.id), {status: 'Fechado'}); alert("Finalizado."); }} className="p-3 bg-emerald-50 text-emerald-600 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"><Check size={20}/></button>
                          <button onClick={() => setSelectedTicket(null)} className="p-3 bg-slate-50 text-slate-400 rounded-xl"><X size={20}/></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-10 space-y-6 bg-slate-50/50 custom-scrollbar">
                       {chatHistory.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                            <div className={`max-w-[80%] p-6 rounded-[2.5rem] shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-600 rounded-tl-none'}`}>
                               <p className="text-xs font-medium italic leading-relaxed">{m.text}</p>
                            </div>
                            <span className="text-[7px] font-black text-slate-300 uppercase mt-2 px-3">{m.timestamp?.seconds ? new Date(m.timestamp.seconds * 1000).toLocaleTimeString() : '...'}</span>
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>
                    <div className="p-8 border-t bg-white shadow-2xl">
                       <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-full border border-slate-100 shadow-inner">
                          <input type="text" value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Responder para o aluno..." className="flex-1 bg-transparent border-none outline-none px-6 py-4 text-xs font-bold italic" />
                          <button onClick={handleSendMessage} className="p-4 bg-slate-900 text-white rounded-full hover:bg-indigo-600 transition-all shadow-2xl"><Send size={24}/></button>
                       </div>
                    </div>
                  </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center p-20 opacity-20 italic text-center gap-6">
                     <MessageSquare size={80} className="text-slate-300" />
                     <p className="text-[10px] font-black uppercase tracking-[0.6em]">Aguardando Seleção de Turno</p>
                  </div>
                )}
             </div>
          </div>
        )}

        {/* ABA: GED / ARQUIVOS REAIS */}
        {activeTab === 'arquivos' && (
           <div className="space-y-6 animate-in fade-in">
              <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-6">
                 <div className="flex items-center gap-4">
                    <div className="p-4 bg-indigo-50 text-indigo-600 rounded-[1.5rem] shadow-inner"><FolderOpen size={24}/></div>
                    <div>
                       <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Repositório Digital (GED)</h3>
                       <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-2">Gestão de Documentos do Banco de Dados</p>
                    </div>
                 </div>
                 <button onClick={() => setIsUploadModalOpen(true)} className="px-10 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-emerald-600 shadow-2xl transition-all flex items-center gap-3"><Upload size={18}/> Novo Documento Real</button>
              </div>

              <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-6">
                 {['Matrículas', 'Financeiro', 'Históricos', 'Regulamentos', 'Certificados', 'Pautas'].map((f, i) => (
                   <div key={i} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 hover:shadow-2xl transition-all group cursor-pointer text-center relative shadow-sm overflow-hidden">
                      <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center mx-auto mb-6 text-indigo-500 shadow-inner group-hover:scale-110 transition-transform"><FolderOpen size={32}/></div>
                      <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{f}</h4>
                      <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-2">{files.filter(file => file.category === f).length} Itens Reais</p>
                      <button onClick={() => { setUploadData({...uploadData, category: f}); setIsUploadModalOpen(true); }} className="absolute bottom-4 right-4 p-2 bg-indigo-50 text-indigo-600 rounded-lg opacity-0 group-hover:opacity-100 transition-all"><Plus size={14}/></button>
                   </div>
                 ))}
              </div>
           </div>
        )}

        {/* ABA: OPERACIONAL */}
        {activeTab === 'operacional' && renderOperationalView()}
      </main>

      {/* MODAL: NOVO PROTOCOLO (RESTAURADO) */}
      {isNewProtocolModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 border-4 border-white/5">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Novo Atendimento</h3>
                 <button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 hover:text-white transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleOpenProtocol} className="space-y-6">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Requerente (Nome do Aluno)</label><input required value={newProtocol.user} onChange={e => setNewProtocol({...newProtocol, user: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" placeholder="Nome completo para identificação..." /></div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Assunto</label><select value={newProtocol.subject} onChange={e => setNewProtocol({...newProtocol, subject: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Acadêmico</option><option>Financeiro</option><option>Suporte Técnico</option></select></div>
                    <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Prioridade</label><select value={newProtocol.priority} onChange={e => setNewProtocol({...newProtocol, priority: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Baixa</option><option>Média</option><option>Alta</option></select></div>
                 </div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Detalhamento da Demanda</label><textarea required value={newProtocol.description} onChange={e => setNewProtocol({...newProtocol, description: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl h-32 font-medium text-[11px] italic shadow-inner resize-none" placeholder="Explique o problema ou solicitação..." /></div>
                 <button type="submit" className="w-full py-6 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-2xl shadow-indigo-100 transition-all active:scale-95">Abrir Chamado Agora</button>
              </form>
           </div>
        </div>
      )}

      {/* MODAL: UPLOAD GED (RESTAURADO) */}
      {isUploadModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-4 text-indigo-600 shadow-inner"><Upload size={40}/></div>
              <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Subir Documento Real</h3>
              <div className="space-y-6 text-left">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Categoria Direcionada</label><select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select></div>
                 <div className="border-4 border-dashed border-slate-100 rounded-[3rem] p-12 text-center hover:border-indigo-400 hover:bg-indigo-50/20 transition-all cursor-pointer relative group shadow-inner">
                    <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept=".pdf,.xlsx,.txt,.doc" />
                    <FileText size={48} className="text-slate-200 mx-auto mb-4 group-hover:text-indigo-400 transition-colors" />
                    <p className="text-[9px] font-black uppercase text-slate-400 tracking-[0.4em] italic leading-tight">Escolher PDF, Excel ou TXT</p>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(false)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Cancelar Operação</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicket, setSelectedTicket] = useState<any | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  // Modais e Formulários
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });

  // GED Explorer State
  const [currentFolder, setCurrentFolder] = useState<string | null>(null);

  // States Operacionais
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição.');
  const [dirSignature, setDirSignature] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });

    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    getDocs(query(collection(db, 'users'), where('role', '==', 'diretor'))).then(snap => {
      if (!snap.empty) setDirSignature(snap.docs[0].data().signatureUrl);
    });

    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  useEffect(() => {
    if (!selectedTicket) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicket.id}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    });
    return () => unsubChat();
  }, [selectedTicket]);

  const stats = useMemo(() => ({
    pendentes: tickets.filter(t => t.status === 'Pendente').length,
    emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
    concluidos: tickets.filter(t => t.status === 'Fechado').length,
    documentos: files.length,
    dataFlow: (files.length * 0.45 + tickets.length * 0.01).toFixed(1)
  }), [tickets, files]);

  const handleOpenProtocol = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProtocol.user || !newProtocol.description) return;
    await addDoc(collection(db, 'tickets'), {
      ...newProtocol,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      protocolo: `PRT-${Date.now().toString().slice(-6)}`
    });
    setIsNewProtocolModalOpen(false);
    setNewProtocol({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  };

  const handleSendMessage = async () => {
    if (!chatMessage.trim() || !selectedTicket) return;
    const msg = chatMessage;
    setChatMessage('');
    await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
      text: msg,
      sender: 'Secretaria',
      timestamp: serverTimestamp()
    });
    await updateDoc(doc(db, 'tickets', selectedTicket.id), {
      lastMessage: msg,
      status: 'Em Atendimento',
      lastUpdate: serverTimestamp()
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: file.name,
        category: uploadData.category,
        content: event.target?.result, 
        uploader: 'Secretaria',
        createdAt: serverTimestamp(),
        size: file.size
      });
      setIsUploadModalOpen(false);
    };
    reader.readAsDataURL(file);
  };

  const handleValidateStudent = async (studentId: string) => {
    const student = students.find(s => s.uid === studentId);
    await updateDoc(doc(db, 'users', studentId), { status: 'ativo', validatedAt: serverTimestamp() });
    await addDoc(collection(db, 'secretaria_arquivos'), {
      title: `Ficha_Matricula_${student?.displayName}.pdf`,
      category: 'Matrículas',
      uploader: 'Automação Sistema',
      createdAt: serverTimestamp()
    });
    alert("Aluno validado e documentos arquivados no GED.");
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'declaracao':
        return (
          <div className="space-y-6 animate-in fade-in zoom-in-95">
             <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-2xl max-w-4xl mx-auto space-y-10">
                <header className="flex justify-between border-b-2 border-slate-900 pb-10">
                   <div className="flex items-center gap-4">
                      <div className="bg-slate-900 p-4 rounded-2xl text-white"><FileBadge size={32}/></div>
                      <div className="font-black italic text-slate-900 leading-none">
                         <p className="text-xl">ESCOLA BÍBLICA EAD</p>
                         <p className="text-[9px] uppercase tracking-widest mt-1">Secretaria Acadêmica Master</p>
                      </div>
                   </div>
                   <div className="text-right">
                      <p className="text-[9px] font-black uppercase text-slate-400 italic">Certidão Oficial</p>
                      <p className="text-sm font-mono font-bold">MAT-{Date.now().toString().slice(-6)}</p>
                   </div>
                </header>

                <div className="space-y-8">
                   <div className="space-y-1.5">
                      <label className="text-[8px] font-black uppercase text-slate-400 italic ml-4">Dados do Aluno</label>
                      <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner">
                         <option value="">Selecione para preencher a declaração...</option>
                         {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                      </select>
                   </div>
                   <div className="p-10 bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200 min-h-[200px]">
                      <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-transparent border-none outline-none text-sm font-medium italic leading-relaxed resize-none h-32" />
                      {selectedStudentForDecl && (
                        <div className="mt-6 pt-6 border-t border-slate-200 text-xs font-black uppercase italic space-y-1">
                           <p>Aluno: {selectedStudentForDecl.displayName}</p>
                           <p>Curso: {courses.find(c => c.id === selectedStudentForDecl.cursoInicial)?.nome}</p>
                        </div>
                      )}
                   </div>
                </div>

                <footer className="pt-20 flex flex-col items-center">
                   {dirSignature ? <img src={dirSignature} className="h-24 grayscale mb-2" /> : <div className="h-20 w-48 border-b border-slate-300 mb-2"></div>}
