                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Transferência Interna</h3>
             </div>
             <div className="space-y-6">
                <div className="space-y-1.5">
                   <label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Selecione o Aluno</label>
                   <select value={transferData.studentId} onChange={e => setTransferData({...transferData, studentId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner">
                      <option value="">Buscar aluno...</option>
                      {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} ({s.email})</option>)}
