                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                      <tr><th className="px-10 py-6">Aluno</th><th className="px-10 py-6">Vencimento</th><th className="px-10 py-6">Valor</th><th className="px-10 py-6">Status</th><th className="px-10 py-6 text-center">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.slice(0, 5).map(s => (
                        <tr key={s.uid}>
                           <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-10 py-6 font-bold text-slate-400">10/05/2024</td>
