      case 'validacao':
        const pending = students.filter(s => s.status === 'pendente' || !s.status);
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-10 border-b border-slate-100 flex justify-between items-center">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Fila de Validação Acadêmica</h3>
                <button onClick={() => setOpSubView('main')} className="p-3 bg-slate-50 rounded-xl hover:bg-rose-50"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                      <tr><th className="px-10 py-6">Solicitante</th><th className="px-10 py-6">Data Cadastro</th><th className="px-10 py-6">Curso Alvo</th><th className="px-10 py-6 text-center">Ações</th></tr>
