                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pending.length === 0 ? (
                        <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black uppercase italic">Nenhuma solicitação aguardando.</td></tr>
                      ) : pending.map(s => (
                        <tr key={s.uid}>
                           <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-10 py-6 font-bold text-slate-400">{new Date(s.createdAt?.seconds * 1000).toLocaleDateString()}</td>
                           <td className="px-10 py-6 font-black text-indigo-500 uppercase italic">{courses.find(c => c.id === s.cursoInicial)?.nome}</td>
                           <td className="px-10 py-6 flex justify-center gap-3">
                              <button onClick={() => handleValidateStudent(s.uid)} className="px-6 py-2.5 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase italic shadow-lg">Validar</button>
                              <button className="px-6 py-2.5 bg-rose-50 text-rose-500 rounded-xl text-[9px] font-black uppercase italic">Recusar</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in zoom-in-95">
             <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-sm space-y-10">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter border-b border-slate-50 pb-6">Workflow Operacional</h3>
                <div className="grid grid-cols-1 gap-4">
                   {[
                     { label: 'Emitir Declaração de Matrícula', icon: <Printer size={18}/>, action: () => setOpSubView('declaracao') },
                     { label: 'Validar Documentos Novos Alunos', icon: <Check size={18}/>, action: () => setOpSubView('validacao'), badge: students.filter(s => s.status === 'pendente' || !s.status).length.toString() },
                     { label: 'Transferência Interna de Curso', icon: <ArrowRightLeft size={18}/>, action: () => setOpSubView('transferencia') },
                     { label: 'Relatório de Inadimplência', icon: <AlertCircle size={18}/>, action: () => setOpSubView('inadimplencia') }
                   ].map((item, i) => (
                     <button key={i} onClick={item.action} className="w-full flex items-center justify-between p-7 bg-slate-50 hover:bg-slate-900 hover:text-white rounded-3xl transition-all group border border-slate-100 shadow-sm">
                        <div className="flex items-center gap-5 text-[10px] font-black uppercase italic tracking-widest">
                           <span className="p-3 bg-white text-slate-400 rounded-xl shadow-sm group-hover:text-indigo-600 transition-all">{item.icon}</span>
                           {item.label}
                        </div>
                        {item.badge && item.badge !== '0' ? <span className="bg-rose-600 text-white px-3 py-1.5 rounded-full text-[8px] font-black shadow-lg animate-pulse">{item.badge}</span> : <ChevronRight size={18} className="text-slate-300"/>}
                     </button>
                   ))}
                </div>
             </div>

             <div className="bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl text-white relative overflow-hidden group border border-white/5">
                <div className="relative z-10 space-y-12">
                   <div className="flex items-center justify-between">
                      <h3 className="text-xl font-black uppercase italic tracking-tighter text-indigo-400">Infraestrutura</h3>
                      <span className="px-4 py-2 bg-emerald-600/20 text-emerald-400 rounded-full text-[8px] font-black uppercase italic border border-emerald-500/30 flex items-center gap-2 shadow-xl"><div className="w-1.5 h-1.5 bg-emerald-400 rounded-full animate-pulse"></div> Servidor Ativo</span>
                   </div>
                   <div className="space-y-6 pt-10">
                      <div className="flex items-center justify-between border-b border-white/5 pb-5">
                         <span className="text-[10px] font-black uppercase text-white/40 italic tracking-widest">Fluxo de Dados</span>
                         <span className="text-2xl font-black tracking-tighter italic tabular-nums">{stats.dataFlow} GB</span>
                      </div>
                      <div className="flex items-center justify-between border-b border-white/5 pb-5">
                         <span className="text-[10px] font-black uppercase text-white/40 italic tracking-widest">Backup Cloud</span>
                         <div className="flex items-center gap-3"><RefreshCw size={14} className="text-emerald-400 animate-spin-slow"/><span className="text-xl font-black italic tracking-tighter">OK</span></div>
                      </div>
                      <div className="flex items-center justify-between">
                         <span className="text-[10px] font-black uppercase text-white/40 italic tracking-widest">Saúde Firestore</span>
