                <HardDrive size={300} className="absolute -bottom-24 -right-24 text-white/5 group-hover:scale-110 transition-transform duration-1000" />
             </div>
          </div>
        );
    }
  };

  const renderGEDExplorer = () => {
    if (currentFolder) {
      const folderFiles = files.filter(f => f.category === currentFolder);
      return (
        <div className="space-y-6 animate-in slide-in-from-right-4">
           <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
              <div className="flex items-center gap-6">
                 <button onClick={() => setCurrentFolder(null)} className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-900 hover:text-white transition-all shadow-sm">
                    <ChevronLeft size={24} />
                 </button>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{currentFolder}</h3>
                    <div className="flex items-center gap-2 mt-2">
                       <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">GED</span>
                       <ChevronRight size={10} className="text-slate-300" />
                       <span className="text-[8px] font-black text-indigo-600 uppercase tracking-widest">{currentFolder}</span>
                    </div>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(true)} className="px-8 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-xl">
                 <Upload size={18} /> Novo Documento
