    const protocolId = `PRT-${Date.now().toString().slice(-6)}`;
    const ticketRef = await addDoc(collection(db, 'tickets'), {
      ...newProtocol,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      protocolo: protocolId
    });

    await addDoc(collection(db, `tickets/${ticketRef.id}/messages`), {
      text: `Protocolo ${protocolId} iniciado automaticamente. Aguarde um atendente.`,
      sender: 'Sistema',
      timestamp: serverTimestamp(),
      type: 'notification'
    });

    setIsNewProtocolModalOpen(false);
    setNewProtocol({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  };

  const handleSendMessage = async (fileData?: { name: string, content: string }) => {
    if (!chatMessage.trim() && !fileData || !selectedTicket) return;

    const isFirstHumanMessage = chatHistory.filter(m => m.sender === 'Secretaria').length === 0;

    if (isFirstHumanMessage && !fileData) {
      await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
        text: `Atendimento iniciado por Secretaria Digital.`,
        sender: 'Sistema',
        timestamp: serverTimestamp(),
        type: 'notification'
      });
      await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
        text: `Olá! Sou atendente da Secretaria. Como posso ajudar você hoje?`,
        sender: 'Secretaria',
        timestamp: serverTimestamp()
      });
    }

    const msg = chatMessage;
    setChatMessage('');

    await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
      text: fileData ? `Arquivo enviado: ${fileData.name}` : msg,
      fileUrl: fileData?.content || null,
