           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 border-4 border-white/5">
              <div className="flex items-center justify-between">
                 <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Novo Atendimento</h3>
                 <button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 hover:text-white transition-all"><X size={20}/></button>
              </div>
              <form onSubmit={handleOpenProtocol} className="space-y-6">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Aluno Requerente</label><input required value={newProtocol.user} onChange={e => setNewProtocol({...newProtocol, user: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner" placeholder="Identifique o aluno..." /></div>
                 <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Assunto</label><select value={newProtocol.subject} onChange={e => setNewProtocol({...newProtocol, subject: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Acadêmico</option><option>Financeiro</option><option>Suporte Técnico</option></select></div>
                    <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Prioridade</label><select value={newProtocol.priority} onChange={e => setNewProtocol({...newProtocol, priority: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Baixa</option><option>Média</option><option>Alta</option></select></div>
                 </div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Descrição</label><textarea required value={newProtocol.description} onChange={e => setNewProtocol({...newProtocol, description: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl h-32 font-medium text-[11px] italic shadow-inner resize-none" placeholder="Relato da demanda..." /></div>
                 <button type="submit" className="w-full py-6 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-2xl transition-all">Abrir e Iniciar Atendimento</button>
              </form>
           </div>
        </div>
      )}

      {isUploadModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-4 text-indigo-600 shadow-inner"><Upload size={40}/></div>
              <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Novo Documento</h3>
              <div className="space-y-6 text-left">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 italic ml-4">Categoria</label><select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select></div>
                 <div className="border-4 border-dashed border-slate-100 rounded-[3rem] p-12 text-center hover:border-indigo-400 hover:bg-indigo-50/20 transition-all cursor-pointer relative group shadow-inner">
                    <input type="file" onChange={handleFileUpload} className="absolute inset-0 opacity-0 cursor-pointer" accept=".pdf,.xlsx,.txt,.doc,.png,.jpg,.jpeg" />
                    <FileText size={48} className="text-slate-200 mx-auto mb-4 group-hover:text-indigo-400 transition-colors" />
                    <p className="text-[9px] font-black uppercase text-slate-400 tracking-[0.4em] italic leading-tight">Escolher Arquivo do Sistema</p>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(false)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Descartar</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive, Bell, ArrowRightLeft, Star, Heart,
  PlayCircle, PowerOff, UserCheck, ShieldAlert
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';
type ChatFilter = 'ativos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicket, setSelectedTicket] = useState<any | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  // GED & Viewer States
  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [viewerFile, setViewerFile] = useState<any | null>(null);

  // Modais e Formulários
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });

  // Transferência State
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });

  // States Operacionais
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição.');
  const [dirSignature, setDirSignature] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });

    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    getDocs(query(collection(db, 'users'), where('role', '==', 'diretor'))).then(snap => {
      if (!snap.empty) setDirSignature(snap.docs[0].data().signatureUrl);
    });

    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  useEffect(() => {
    if (!selectedTicket) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicket.id}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    });
    return () => unsubChat();
  }, [selectedTicket]);

  const stats = useMemo(() => ({
    pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
    emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
    concluidos: tickets.filter(t => t.status === 'Fechado').length,
    documentos: files.length,
    satisfacao: "98.4%",
    dataFlow: (files.length * 0.45 + tickets.length * 0.01).toFixed(1)
  }), [tickets, files]);

  const filteredTicketsForChat = useMemo(() => {
    return tickets.filter(t => {
      if (chatFilter === 'ativos') return t.status === 'Pendente' || t.status === 'Em Atendimento';
      if (chatFilter === 'finalizados') return t.status === 'Fechado';
      if (chatFilter === 'arquivados') return t.status === 'Arquivado';
      return true;
    });
  }, [tickets, chatFilter]);

  const handleOpenProtocol = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProtocol.user || !newProtocol.description) return;

    const protocolId = `PRT-${Date.now().toString().slice(-6)}`;
    const ticketRef = await addDoc(collection(db, 'tickets'), {
      ...newProtocol,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      protocolo: protocolId
    });

    await addDoc(collection(db, `tickets/${ticketRef.id}/messages`), {
      text: `Protocolo ${protocolId} iniciado automaticamente com base no seu relato: "${newProtocol.description}"`,
      sender: 'Sistema',
      timestamp: serverTimestamp(),
      type: 'notification'
    });

    setIsNewProtocolModalOpen(false);
    setNewProtocol({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicket) return;

    if (selectedTicket.status === 'Pendente') {
      // GATILHO: INICIAR ATENDIMENTO
      await updateDoc(doc(db, 'tickets', selectedTicket.id), { status: 'Em Atendimento', startAt: serverTimestamp() });
      await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
        text: `O atendente entrou na conversa. Atendimento iniciado.`,
        sender: 'Sistema',
        timestamp: serverTimestamp(),
        type: 'notification'
      });
      await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
        text: `Olá! Sou da Secretaria Digital. Já analisei seu pedido de ${selectedTicket.subject} e estou aqui para resolver. Como posso ajudar?`,
        sender: 'Secretaria',
        timestamp: serverTimestamp()
      });
    } else if (selectedTicket.status === 'Em Atendimento') {
      // GATILHO: ENCERRAR ATENDIMENTO
      if(confirm("Encerrar este atendimento agora?")) {
        await updateDoc(doc(db, 'tickets', selectedTicket.id), { status: 'Fechado', closedAt: serverTimestamp() });
        await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
          text: `Atendimento finalizado pela secretaria.`,
          sender: 'Sistema',
          timestamp: serverTimestamp(),
          type: 'notification'
        });
        // Enviar card de satisfação
        await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
          text: `Como você avalia nosso suporte?`,
          sender: 'Sistema',
          timestamp: serverTimestamp(),
          type: 'satisfaction_card'
        });
        setSelectedTicket(null);
      }
    }
  };

  const handleArchiveTicket = async () => {
    if (!selectedTicket) return;
    if (confirm("Mover esta conversa para o arquivo morto?")) {
      await updateDoc(doc(db, 'tickets', selectedTicket.id), { status: 'Arquivado' });
      alert("Atendimento arquivado with sucesso.");
      setSelectedTicket(null);
    }
  };

  const handleSendMessage = async (fileData?: { name: string, content: string }) => {
    if (!chatMessage.trim() && !fileData || !selectedTicket) return;

    const msg = chatMessage;
    setChatMessage('');

    await addDoc(collection(db, `tickets/${selectedTicket.id}/messages`), {
      text: fileData ? `Arquivo enviado: ${fileData.name}` : msg,
      fileUrl: fileData?.content || null,
      fileName: fileData?.name || null,
      sender: 'Secretaria',
      timestamp: serverTimestamp()
    });

    await updateDoc(doc(db, 'tickets', selectedTicket.id), {
      lastMessage: fileData ? `Arquivo: ${fileData.name}` : msg,
      lastUpdate: serverTimestamp()
    });
  };

  const handleChatFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      handleSendMessage({ name: file.name, content: event.target?.result as string });
    };
    reader.readAsDataURL(file);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (event) => {
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: file.name,
        category: uploadData.category,
        content: event.target?.result, 
        uploader: 'Secretaria',
        createdAt: serverTimestamp(),
        size: file.size
      });
      setIsUploadModalOpen(false);
    };
    reader.readAsDataURL(file);
  };

  const handleValidateStudent = async (studentId: string) => {
    await updateDoc(doc(db, 'users', studentId), { status: 'ativo', validatedAt: serverTimestamp() });
    alert("Aluno validado com sucesso!");
  };

  // ADDED: Missing method renderOperationalView
  const renderOperationalView = () => {
    return (
      <div className="space-y-6 animate-in slide-in-from-bottom-4">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {[
            { id: 'declaracao', title: 'Declaração de Matrícula', icon: <FileText size={32}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
            { id: 'validacao', title: 'Validação de Alunos', icon: <UserCheck size={32}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
            { id: 'transferencia', title: 'Transferência Interna', icon: <ArrowRightLeft size={32}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
            { id: 'inadimplencia', title: 'Gestão de Pendências', icon: <ShieldAlert size={32}/>, color: 'text-rose-600', bg: 'bg-rose-50' }
          ].map(op => (
            <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 hover:shadow-2xl transition-all group flex flex-col items-center text-center shadow-sm">
              <div className={`w-16 h-16 ${op.bg} ${op.color} rounded-2xl flex items-center justify-center mb-6 shadow-inner group-hover:scale-110 transition-transform`}>{op.icon}</div>
              <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{op.title}</h4>
            </button>
          ))}
        </div>

        {opSubView === 'validacao' && (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
            <div className="p-8 border-b bg-slate-50/50 flex items-center justify-between">
              <h3 className="text-sm font-black uppercase italic text-slate-800">Alunos Aguardando Validação</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                  <tr><th className="px-10 py-6">Nome</th><th className="px-10 py-6">E-mail</th><th className="px-10 py-6">Status</th><th className="px-10 py-6 text-center">Ação</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[10px]">
                  {students.filter(s => s.status === 'pendente' || s.status === 'rascunho').map(s => (
                    <tr key={s.uid}>
                      <td className="px-10 py-6 font-black uppercase italic text-slate-900">{s.displayName}</td>
                      <td className="px-10 py-6 font-bold text-slate-400">{s.email}</td>
                      <td className="px-10 py-6"><span className="px-4 py-1 bg-amber-50 text-amber-600 rounded-full font-black uppercase italic border border-amber-100">{s.status}</span></td>
                      <td className="px-10 py-6 text-center"><button onClick={() => handleValidateStudent(s.uid)} className="px-6 py-2 bg-emerald-600 text-white rounded-xl text-[8px] font-black uppercase italic hover:bg-emerald-700 transition-all">Validar Aluno</button></td>
                    </tr>
                  ))}
                  {students.filter(s => s.status === 'pendente' || s.status === 'rascunho').length === 0 && (
                    <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black uppercase italic text-[10px]">Nenhum aluno pendente.</td></tr>
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    );
  };

  const renderGEDExplorer = () => {
    if (currentFolder) {
      const folderFiles = files.filter(f => f.category === currentFolder);
      return (
        <div className="space-y-6 animate-in slide-in-from-right-4">
           <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
              <div className="flex items-center gap-6">
                 <button onClick={() => setCurrentFolder(null)} className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-900 hover:text-white transition-all shadow-sm"><ChevronLeft size={24} /></button>
                 <div>
                    <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{currentFolder}</h3>
                    <div className="flex items-center gap-2 mt-2"><span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">GED</span><ChevronRight size={10} className="text-slate-300" /><span className="text-[8px] font-black text-indigo-600 uppercase tracking-widest">{currentFolder}</span></div>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(true)} className="px-8 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-xl"><Upload size={18} /> Novo Documento</button>
           </div>
           <div className="bg-white rounded-[3.5rem] border border-slate-200 shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                 <table className="w-full text-left">
                    <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                       <tr><th className="px-10 py-6">Nome</th><th className="px-10 py-6">Data</th><th className="px-10 py-6">Tamanho</th><th className="px-10 py-6 text-center">Gestão</th></tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100 text-[10px]">
                       {folderFiles.length === 0 ? (
                         <tr><td colSpan={4} className="p-32 text-center text-slate-300 italic uppercase font-black tracking-widest">Nenhum arquivo nesta categoria.</td></tr>
                       ) : folderFiles.map(file => (
                         <tr key={file.id} className="hover:bg-indigo-50/10 group transition-all">
                            <td className="px-10 py-6">
                               <div className="flex items-center gap-4">
                                  <div className="p-3 rounded-xl bg-indigo-50 text-indigo-600 shadow-sm"><FileText size={20}/></div>
                                  <span className="font-black text-slate-900 uppercase italic tracking-tight">{file.title}</span>
                               </div>
                            </td>
                            <td className="px-10 py-6 font-bold text-slate-400">{file.createdAt?.seconds ? new Date(file.createdAt.seconds * 1000).toLocaleDateString() : '---'}</td>
                            <td className="px-10 py-6 font-mono text-slate-500">{(file.size / 1024).toFixed(1)} KB</td>
                            <td className="px-10 py-6">
                               <div className="flex items-center justify-center gap-3">
                                  <button onClick={() => setViewerFile(file)} className="p-3 bg-white border border-slate-100 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm" title="Visualizar"><Eye size={16}/></button>
                                  <a href={file.content} download={file.title} className="p-3 bg-white border border-slate-100 text-emerald-600 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"><Download size={16}/></a>
                                  <button onClick={async () => { if(confirm("Excluir?")) await deleteDoc(doc(db, 'secretaria_arquivos', file.id)); }} className="p-3 bg-white border border-slate-100 text-rose-500 rounded-xl hover:bg-rose-600 hover:text-white transition-all shadow-sm"><Trash2 size={16}/></button>
                               </div>
                            </td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
        </div>
      );
    }
    return (
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-6 animate-in zoom-in-95">
         {[
           { name: 'Matrículas', icon: <FileText size={32}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
           { name: 'Financeiro', icon: <CheckCircle2 size={32}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
           { name: 'Históricos', icon: <History size={32}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
           { name: 'Regulamentos', icon: <AlertCircle size={32}/>, color: 'text-slate-600', bg: 'bg-slate-100' },
           { name: 'Certificados', icon: <FileBadge size={32}/>, color: 'text-rose-600', bg: 'bg-rose-50' },
           { name: 'Pautas', icon: <FolderOpen size={32}/>, color: 'text-indigo-400', bg: 'bg-slate-50' }
         ].map((f, i) => {
           const count = files.filter(file => file.category === f.name).length;
           return (
             <div key={i} onClick={() => setCurrentFolder(f.name)} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 hover:shadow-2xl transition-all group cursor-pointer text-center relative shadow-sm overflow-hidden">
                <div className={`w-16 h-16 ${f.bg} ${f.color} rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-inner group-hover:scale-110 transition-transform`}>{f.icon}</div>
                <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{f.name}</h4>
                <p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-2">{count} documentos</p>
                <div className="absolute bottom-4 right-4 p-2 bg-indigo-50 text-indigo-600 rounded-lg opacity-0 group-hover:opacity-100 transition-all"><ChevronRight size={14}/></div>
             </div>
           );
         })}
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col lg:flex-row lg:items-center justify-between gap-6 no-print">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Secretaria Digital</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Suporte Acadêmico e Gestão Discente Master.</p>
        </div>
