                           <td className="px-10 py-6 text-center"><button onClick={() => handleValidateStudent(s.uid)} className="px-6 py-2 bg-indigo-600 text-white rounded-xl text-[8px] font-black uppercase italic hover:bg-indigo-700 transition-all shadow-md">Aprovar Aluno</button></td>
