                    <div className="p-6 bg-white/5 rounded-2xl border border-white/10 flex items-center justify-between shadow-inner"><div className="flex items-center gap-3"><Database className="text-indigo-400" size={18}/><span className="text-[9px] font-black uppercase tracking-widest italic">siteigreja-461f6-master-node</span></div></div>
                 </div>
              </div>
              <HardDrive size={300} className="absolute -bottom-24 -right-24 text-white/5 group-hover:scale-110 transition-transform duration-1000" />
            </div>
          </div>
