              <div className="relative flex-1 max-w-md"><Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={18} /><input type="text" placeholder="Protocolo, nome ou aluno..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-16 pr-6 py-4 bg-white border border-slate-200 rounded-2xl text-[10px] font-black outline-none shadow-inner" /></div>
              <button onClick={() => setIsNewProtocolModalOpen(true)} className="bg-slate-900 text-white px-10 py-4 rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-xl"><Plus size={18}/> Abrir Protocolo</button>
