              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b italic"><tr><th className="px-10 py-6">Protocolo</th><th className="px-10 py-6">Requerente</th><th className="px-10 py-6">Assunto</th><th className="px-10 py-6">Status</th><th className="px-10 py-6 text-center">Gestão</th></tr></thead>
                <tbody className="divide-y divide-slate-100 text-[10px]">
                  {tickets.filter(t => t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || t.protocolo?.includes(searchTerm)).map(t => (
                    <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors">
                      <td className="px-10 py-6 font-mono font-bold text-indigo-600">{t.protocolo}</td>
                      <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{t.user}</td>
                      <td className="px-10 py-6 font-bold text-slate-500 uppercase italic">{t.subject}</td>
                      <td className="px-10 py-6"><span className={`px-4 py-1.5 rounded-full font-black uppercase italic border ${t.status === 'Fechado' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : t.status === 'Arquivado' ? 'bg-slate-100 text-slate-400' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>{t.status}</span></td>
                      <td className="px-10 py-6 text-center"><button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-3 bg-white border border-slate-100 rounded-xl text-indigo-600 shadow-sm hover:scale-110 transition-all"><MessageSquare size={16}/></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[750px] animate-in slide-in-from-right-5">
             <div className="lg:col-span-4 flex flex-col gap-6">
                <div className="bg-white rounded-[3.5rem] border border-slate-200 shadow-sm flex flex-col overflow-hidden flex-1">
                   <div className="p-6 border-b bg-slate-50/50 flex flex-col gap-4">
                      <h4 className="text-[10px] font-black uppercase italic tracking-widest text-slate-500 text-center">Filas de Gestão</h4>
                      <div className="grid grid-cols-3 gap-2">
                         {(['ativos', 'finalizados', 'arquivados'] as ChatFilter[]).map(f => (
                           <button key={f} onClick={() => setChatFilter(f)} className={`py-3 rounded-xl text-[8px] font-black uppercase italic transition-all border ${chatFilter === f ? 'bg-slate-900 text-white border-slate-900 shadow-lg' : 'bg-white text-slate-400 border-slate-100'}`}>{f}</button>
                         ))}
                      </div>
                   </div>
                   <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                      {filteredTicketsForChat.length === 0 ? <div className="p-10 text-center text-slate-300 font-black uppercase italic text-[9px]">Fila vazia.</div> : filteredTicketsForChat.map(t => (
                        <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-6 rounded-[2.5rem] border transition-all cursor-pointer flex items-center gap-4 ${selectedTicketId === t.id ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl' : 'bg-slate-50 border-slate-100 text-slate-600 hover:bg-white'}`}>
                           <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center font-black italic">{(t.user||'A').charAt(0)}</div>
                           <div className="flex-1 overflow-hidden"><p className="text-xs font-black uppercase italic truncate">{t.user}</p><p className={`text-[8px] font-bold truncate mt-1 ${selectedTicketId === t.id ? 'text-indigo-200' : 'text-slate-400'}`}>{t.lastMessage || t.subject}</p></div>
                        </div>
                      ))}
                   </div>
                </div>
                <div className="bg-slate-900 p-8 rounded-[3.5rem] shadow-2xl text-white space-y-6 border border-white/5 relative overflow-hidden group">
                   <div className="relative z-10"><div className="flex items-center gap-3 mb-4"><Heart className="text-rose-500 fill-rose-500" size={16} /><h5 className="text-[10px] font-black uppercase tracking-widest italic text-indigo-400">Eficiência Suporte</h5></div>
                      <p className="text-[11px] font-medium italic text-white/60 leading-relaxed mb-6">Média real baseada em conclusões vs protocolos abertos.</p>
