                          <button 
                            onClick={handleArchiveTicket} 
                            className="p-3 bg-slate-100 text-slate-400 rounded-xl hover:bg-slate-900 hover:text-white transition-all shadow-sm" 
                            title="Mover para Arquivo Morto"
                          >
                            <Archive size={20}/>
                          </button>
                          <button onClick={() => setSelectedTicketId(null)} className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:bg-rose-50 transition-all"><X size={20}/></button>
