        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 border-4 border-white/5">
              <div className="flex items-center justify-between"><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Novo Atendimento</h3><button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all"><X size={20}/></button></div>
              <form onSubmit={handleOpenProtocol} className="space-y-6">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Identificação Aluno</label><input required value={newProtocol.user} onChange={e => setNewProtocol({...newProtocol, user: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-sm shadow-inner" placeholder="Nome do Aluno..." /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Assunto Acadêmico</label><select value={newProtocol.subject} onChange={e => setNewProtocol({...newProtocol, subject: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Acadêmico</option><option>Financeiro</option><option>Suporte</option></select></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Relato do Chamado</label><textarea required value={newProtocol.description} onChange={e => setNewProtocol({...newProtocol, description: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl h-32 font-medium text-[11px] italic shadow-inner resize-none" placeholder="Descrição do problema..." /></div>
                 <button type="submit" className="w-full py-6 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic hover:bg-indigo-600 shadow-2xl transition-all">Abrir Registro</button>
              </form>
           </div>
        </div>
      )}

      {isUploadModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 text-center">
              <div className="w-20 h-20 bg-indigo-50 rounded-3xl flex items-center justify-center mx-auto mb-4 text-indigo-600 shadow-inner"><Upload size={40}/></div>
              <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Novo Documento</h3>
              <div className="space-y-6 text-left">
                 <select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select>
                 <div className="border-4 border-dashed border-slate-100 rounded-[3rem] p-12 text-center hover:border-indigo-400 transition-all cursor-pointer relative group shadow-inner">
                    <input type="file" onChange={(e) => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=async(ev)=>{ await addDoc(collection(db, 'secretaria_arquivos'), {title:f.name, category:uploadData.category, content:ev.target?.result, uploader:'Secretaria', createdAt:serverTimestamp(), size:f.size}); setIsUploadModalOpen(false); }; r.readAsDataURL(f); } }} className="absolute inset-0 opacity-0 cursor-pointer" accept=".pdf,.png,.jpg,.jpeg" />
                    <FileText size={48} className="text-slate-200 mx-auto mb-4 group-hover:text-indigo-400 transition-colors" /><p className="text-[9px] font-black uppercase text-slate-400 tracking-[0.4em] italic">Escolher Arquivo</p>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(false)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic">Descartar</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive, Bell, ArrowRightLeft, Star, Heart,
  PlayCircle, PowerOff, UserCheck, ShieldAlert, FileSignature, Save
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';
type ChatFilter = 'ativos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [viewerFile, setViewerFile] = useState<any | null>(null);
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularly matriculado nesta instituição de ensino teológico.');
  const [dirSignature, setDirSignature] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  const selectedTicket = useMemo(() => {
    return tickets.find(t => t.id === selectedTicketId) || null;
  }, [tickets, selectedTicketId]);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    getDocs(query(collection(db, 'users'), where('role', '==', 'diretor'))).then(snap => {
      if (!snap.empty) setDirSignature(snap.docs[0].data().signatureUrl);
    });
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  useEffect(() => {
    if (!selectedTicketId) {
      setChatHistory([]);
      return;
    }
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const finished = tickets.filter(t => t.status === 'Fechado' || t.status === 'Arquivado').length;
    const total = tickets.length;
    const satValue = total > 0 ? ((finished / total) * 100).toFixed(1) : "0.0";
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      concluidos: finished,
      documentos: files.length,
      satisfacao: `${satValue}%`,
      dataFlow: (files.length * 0.45 + tickets.length * 0.01).toFixed(1)
    };
  }, [tickets, files]);

  const filteredTicketsForChat = useMemo(() => {
    return tickets.filter(t => {
      if (chatFilter === 'ativos') return t.status === 'Pendente' || t.status === 'Em Atendimento';
      if (chatFilter === 'finalizados') return t.status === 'Fechado';
      if (chatFilter === 'arquivados') return t.status === 'Arquivado';
      return true;
    });
  }, [tickets, chatFilter]);

  const handleOpenProtocol = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProtocol.user || !newProtocol.description) return;
    const protocolId = `PRT-${Date.now().toString().slice(-6)}`;
    const ticketRef = await addDoc(collection(db, 'tickets'), { ...newProtocol, status: 'Pendente', createdAt: serverTimestamp(), protocolo: protocolId });
    await addDoc(collection(db, `tickets/${ticketRef.id}/messages`), { text: `Protocolo ${protocolId} iniciado.`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification' });
    setIsNewProtocolModalOpen(false);
    setNewProtocol({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicketId) return;
    const ticketRef = doc(db, 'tickets', selectedTicketId);
    try {
      if (selectedTicket?.status === 'Pendente') {
        await updateDoc(ticketRef, { status: 'Em Atendimento', startedAt: serverTimestamp() });
        await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), { text: `Suporte iniciado.`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification' });
      } else {
        if(window.confirm("Deseja realmente ENCERRAR este atendimento?")) {
          await updateDoc(ticketRef, { status: 'Fechado', closedAt: serverTimestamp() });
          await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), { text: `Atendimento finalizado.`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification' });
          setSelectedTicketId(null);
        }
      }
    } catch (error: any) {
      alert("Erro: " + error.message);
    }
  };

  const handleArchiveTicket = async () => {
    if (!selectedTicketId) return;
    if (window.confirm("Mover para o ARQUIVO MORTO?")) {
      try {
        await updateDoc(doc(db, 'tickets', selectedTicketId), { status: 'Arquivado', archivedAt: serverTimestamp() });
        setSelectedTicketId(null);
      } catch (error: any) {
        alert("Erro: " + error.message);
      }
    }
  };

  const handleSendMessage = async (fileData?: { name: string, content: string }) => {
    if (!chatMessage.trim() && !fileData || !selectedTicketId) return;
    const msg = chatMessage;
    setChatMessage('');
    try {
      await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), { 
        text: fileData ? `Arquivo: ${fileData.name}` : msg, 
        fileUrl: fileData?.content || null, 
        fileName: fileData?.name || null, 
        sender: 'Secretaria', 
        timestamp: serverTimestamp() 
      });
      await updateDoc(doc(db, 'tickets', selectedTicketId), { 
        lastMessage: fileData ? `Arquivo: ${fileData.name}` : msg, 
        lastUpdate: serverTimestamp()
      });
    } catch (err) { console.error(err); }
  };

  const handleSaveDeclaration = async () => {
    if (!selectedStudentForDecl) { alert("Selecione um aluno."); return; }
    const fileName = `DECLARACAO_MATRICULA_${selectedStudentForDecl.displayName.replace(/\s/g, '_')}.pdf`;

    const docContent = `
      DECLARAÇÃO DE MATRÍCULA
      ----------------------
      Aluno: ${selectedStudentForDecl.displayName}
      Matrícula: ${selectedStudentForDecl.academicId || 'S/ID'}
      Status: Ativo
      Data de Emissão: ${new Date().toLocaleDateString()}

      ${declContent}
    `;

    try {
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName,
        category: 'Matrículas',
        content: `data:text/plain;base64,${btoa(docContent)}`,
        uploader: 'Sistema - Secretaria',
        createdAt: serverTimestamp(),
        size: docContent.length
      });
      alert("Declaração salva na pasta 'Matrículas'.");
      setOpSubView('main');
    } catch (err) { alert("Erro ao salvar documento."); }
  };

  const handleTransfer = async () => {
    if (!transferData.studentId || !transferData.courseId) return;
    const student = students.find(s => s.uid === transferData.studentId);
    const course = courses.find(c => c.id === transferData.courseId);

    if (!student || !course) return;

    const fileName = `TERMO_TRANSFERENCIA_${student.displayName.replace(/\s/g, '_')}_${Date.now().toString().slice(-4)}.pdf`;

    const docContent = `
      TERMO OFICIAL DE TRANSFERÊNCIA INTERNA
      ======================================
      ESCOLA BÍBLICA EAD - SECRETARIA ACADÊMICA

      IDENTIFICAÇÃO DO DISCENTE:
      Nome: ${student.displayName}
      ID Acadêmico: ${student.academicId || 'S/ID'}

      DADOS DA MOVIMENTAÇÃO:
      Disciplina de Destino: ${course.nome}
      Data do Requerimento: ${new Date().toLocaleDateString()}

      TERMOS:
      Pelo presente termo, a Secretaria Acadêmica confirma a transferência 
      de registro de matrícula do aluno supracitado para a nova disciplina 
      escolhida, mantendo-se o histórico de créditos e encargos vigentes.

      Assinado eletronicamente pela Diretoria de Ensino.
      -----------------------------------------------
      Código de Autenticação: ${Math.random().toString(36).substring(2, 15).toUpperCase()}
    `;

    try {
      await updateDoc(doc(db, 'users', transferData.studentId), { 
        cursoInicial: transferData.courseId, 
        transferAt: serverTimestamp() 
      });

      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName,
        category: 'Históricos',
        content: `data:text/plain;base64,${btoa(docContent)}`,
        uploader: 'Sistema - Automático',
        createdAt: serverTimestamp(),
        size: docContent.length
      });

      alert("Transferência realizada. Termo de Transferência salvo em 'Históricos'.");
      setOpSubView('main');
    } catch (err) { alert("Falha na operação."); }
  };

  const handleValidateStudent = async (studentId: string) => {
    await updateDoc(doc(db, 'users', studentId), { status: 'ativo', validatedAt: serverTimestamp() });
    alert("Aluno validado!");
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'declaracao':
        return (
          <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-2xl max-w-4xl mx-auto space-y-10 animate-in zoom-in-95">
             <header className="flex justify-between border-b-2 border-slate-900 pb-10">
                <div className="flex items-center gap-4">
                   <div className="bg-slate-900 p-4 rounded-2xl text-white"><FileBadge size={32}/></div>
                   <div className="font-black italic text-slate-900 leading-none">
                      <p className="text-xl">ESCOLA BÍBLICA EAD</p>
                      <p className="text-[9px] uppercase tracking-widest mt-1 text-slate-400">Secretaria Digital Master</p>
                   </div>
                </div>
                <div className="text-right"><p className="text-[9px] font-black uppercase text-slate-400 italic">Certidão Oficial</p><p className="text-sm font-mono font-bold text-slate-900">MAT-{Date.now().toString().slice(-6)}</p></div>
             </header>
             <div className="space-y-6">
                <div className="space-y-2">
                   <label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Selecione o Aluno Requerente</label>
                   <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner outline-none">
                      <option value="">Buscar na base de dados...</option>
                      {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Conteúdo da Declaração</label>
                   <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-slate-50 p-10 rounded-[2.5rem] border-2 border-dashed border-slate-200 outline-none text-sm font-medium italic min-h-[200px] shadow-inner" />
                </div>
             </div>
             <footer className="pt-20 flex flex-col items-center">
                {dirSignature && <img src={dirSignature} className="h-20 grayscale mb-2" />}
                <p className="text-[10px] font-black uppercase italic text-slate-900 border-t border-slate-200 pt-2 px-10">Diretoria de Ensino</p>
             </footer>
             <div className="flex gap-4 pt-10 no-print">
                <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic">Voltar</button>
                <button onClick={handleSaveDeclaration} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase flex items-center justify-center gap-3 italic shadow-xl"><Save size={18}/> Salvar e Gerar</button>
             </div>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8 animate-in slide-in-from-bottom-5">
             <div className="flex items-center gap-4 border-b pb-6">
                <div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><ArrowRightLeft size={24}/></div>
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Transferência de Matriz</h3>
             </div>
             <div className="space-y-6">
                <div className="space-y-2">
                   <label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Aluno Destino</label>
                   <select value={transferData.studentId} onChange={e => setTransferData({...transferData, studentId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner">
                      <option value="">Selecionar Aluno...</option>
                      {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Novo Curso / Turma</label>
                   <select value={transferData.courseId} onChange={e => setTransferData({...transferData, courseId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner">
                      <option value="">Selecionar Novo Curso...</option>
                      {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                   </select>
                </div>
                <div className="flex gap-4 pt-6">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase">Cancelar</button>
                   <button onClick={handleTransfer} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase italic shadow-lg">Efetivar Transferência</button>
                </div>
             </div>
          </div>
        );
      case 'inadimplencia':
        return (
          <div className="bg-white rounded-[3.5rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-3"><ShieldAlert className="text-rose-500" /> Auditoria de Pendências</h3>
                <button onClick={() => setOpSubView('main')} className="p-3 bg-white border border-slate-100 rounded-xl hover:bg-rose-50 hover:text-rose-600 transition-all"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase italic border-b"><tr><th className="px-10 py-6">Requerente</th><th className="px-10 py-6">Tipo de Pendência</th><th className="px-10 py-6">Impacto Acadêmico</th><th className="px-10 py-6">Situação</th></tr></thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.slice(0, 8).map(s => (
                        <tr key={s.uid} className="hover:bg-rose-50/10 transition-colors">
                           <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-10 py-6 font-bold text-slate-500">Regularização de Matrícula</td>
                           <td className="px-10 py-6 font-medium text-slate-400 italic">Bloqueio de Certificado</td>
                           <td className="px-10 py-6"><span className="px-4 py-1.5 bg-rose-50 text-rose-600 rounded-full font-black uppercase italic border border-rose-100">Pendente</span></td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'validacao':
        const pending = students.filter(s => s.status === 'pendente' || s.status === 'rascunho' || !s.status);
        return (
          <div className="bg-white rounded-[3.5rem] border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-3"><UserCheck className="text-indigo-600" /> Fila de Validação Acadêmica</h3>
                <button onClick={() => setOpSubView('main')} className="p-3 bg-white border border-slate-100 rounded-xl"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase italic border-b"><tr><th className="px-10 py-6">Solicitante</th><th className="px-10 py-6">Data de Ingresso</th><th className="px-10 py-6">Status Atual</th><th className="px-10 py-6 text-center">Gestão</th></tr></thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pending.length === 0 ? <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black italic uppercase tracking-[0.3em]">Sem solicitações em aberto</td></tr> : pending.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50/10 transition-colors">
                           <td className="px-10 py-6 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-10 py-6 font-bold text-slate-400">{s.createdAt?.seconds ? new Date(s.createdAt.seconds * 1000).toLocaleDateString() : 'Recente'}</td>
