                   <button onClick={handleTransfer} className="flex-1 py-5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase italic shadow-lg">Efetivar e Salvar Termo</button>
                </div>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-in zoom-in-95">
             {[
               { id: 'declaracao', title: 'Declaração de Matrícula', icon: <FileText size={32}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
               { id: 'validacao', title: 'Validação Acadêmica', icon: <UserCheck size={32}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
               { id: 'transferencia', title: 'Transferência de Matriz', icon: <ArrowRightLeft size={32}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
               { id: 'inadimplencia', title: 'Auditoria Financeira', icon: <ShieldAlert size={32}/>, color: 'text-rose-600', bg: 'bg-rose-50' }
             ].map(op => (
               <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 transition-all flex flex-col items-center shadow-sm group">
                  <div className={`w-16 h-16 ${op.bg} ${op.color} rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform shadow-inner`}>{op.icon}</div>
                  <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{op.title}</h4>
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in">
      <header className="flex justify-between items-center no-print">
        <div><h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter">Secretaria Master</h1><p className="text-slate-500 text-sm italic font-medium">Gestão Acadêmica de Alto Nível.</p></div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab)} className={`px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'}`}>{tab}</button>
          ))}
        </div>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 no-print">
         {[
           { label: 'Fila de Espera', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={20}/> },
           { label: 'Atendimentos', value: stats.emAtendimento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <AlertCircle size={20}/> },
           { label: 'Satisfação', value: stats.satisfacao, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <Star size={20}/> },
           { label: 'Arquivos GED', value: stats.documentos, color: 'text-slate-600', bg: 'bg-slate-50', icon: <FolderOpen size={20}/> }
         ].map((s, i) => (
           <div key={i} className={`${s.bg} p-8 rounded-[2.5rem] border border-slate-200 flex items-center gap-6 shadow-sm`}>
              <div className="p-4 bg-white rounded-2xl text-slate-400 shadow-sm">{s.icon}</div>
