                                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'secretaria_arquivos', f.id)); }} className="p-2.5 bg-white border border-slate-100 text-rose-500 rounded-xl hover:bg-rose-600 transition-all shadow-sm"><Trash2 size={16}/></button>
