                    <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform shadow-inner"><FolderOpen size={30}/></div>
                    <h4 className="text-[11px] font-black text-slate-900 uppercase italic leading-none">{f}</h4>
                    <p className="text-[7px] font-bold text-slate-400 uppercase mt-2">{files.filter(file => file.category === f).length} itens</p>
                 </div>
               ))}
            </div>
