        )}

        {activeTab === 'operacional' && renderOperationalView()}
      </main>

      {/* FULLSCREEN DOCUMENT VIEWER */}
      {viewerFile && (
        <div className="fixed inset-0 z-[5000] bg-slate-950 flex flex-col animate-in fade-in duration-300">
           <header className="p-6 md:px-12 md:py-8 border-b border-white/10 flex items-center justify-between bg-slate-900 shadow-2xl">
