                     <tr><th className="px-10 py-6">Requerente</th><th className="px-10 py-6">Pendência</th><th className="px-10 py-6">Impacto</th><th className="px-10 py-6">Situação</th><th className="px-10 py-6 text-center">Gestão</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
