                              <button onClick={() => handleRegularizeDebt(s.uid)} className="p-2.5 bg-white border border-slate-100 text-emerald-600 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm" title="Regularizar"><CheckCircle size={16}/></button>
