                <button onClick={() => setIsNewProtocolModalOpen(true)} className="bg-slate-900 text-white px-8 py-3.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-2 shadow-xl hover:bg-indigo-600 transition-all italic"><Plus size={16}/> Abrir Chamado</button>
             </div>
