  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [viewerFile, setViewerFile] = useState<any | null>(null);
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição de ensino teológico.');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  const selectedTicket = useMemo(() => tickets.find(t => t.id === selectedTicketId) || null, [tickets, selectedTicketId]);

  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const total = tickets.length;
    const concluidos = tickets.filter(t => t.status === 'Finalizado' || t.status === 'Arquivado').length;
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      documentos: files.length,
      satisfacao: total > 0 ? ((concluidos / total) * 100).toFixed(1) + '%' : '100%'
    };
  }, [tickets, files]);

  const filteredTickets = useMemo(() => {
    return tickets.filter(t => {
      const matchSearch = t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase());

      let matchDate = true;
      if (dateStart || dateEnd) {
        const created = t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000) : new Date();
        if (dateStart) matchDate = matchDate && created >= new Date(dateStart + "T00:00:00");
        if (dateEnd) matchDate = matchDate && created <= new Date(dateEnd + "T23:59:59");
      }
      return matchSearch && matchDate;
    });
  }, [tickets, searchTerm, dateStart, dateEnd]);

  // GERAÇÃO DE PDF REAL VIA BLOB PARA VISUALIZAÇÃO NATIVA
  const handleSaveDeclaration = async () => {
    if (!selectedStudentForDecl) { alert("Selecione um aluno."); return; }
    const fileName = `DECLARACAO_${selectedStudentForDecl.displayName.replace(/\s/g, '_')}.pdf`;

    // HTML Completo formatado para o PDF
    const htmlContent = `
      <!DOCTYPE html>
      <html>
        <head>
          <style>
            body { font-family: sans-serif; padding: 40px; color: #1e293b; line-height: 1.6; }
            .header { text-align: center; border-bottom: 2px solid #4f46e5; padding-bottom: 20px; margin-bottom: 40px; }
            .content { font-size: 14px; text-align: justify; margin-bottom: 60px; }
            .footer { text-align: center; border-top: 1px solid #e2e8f0; padding-top: 20px; font-size: 12px; }
            h1 { color: #4f46e5; margin: 0; text-transform: uppercase; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>Escola Bíblica EAD</h1>
            <p>Secretaria Acadêmica Master</p>
          </div>
          <h2 style="text-align: center;">DECLARAÇÃO DE MATRÍCULA</h2>
          <div class="content">
            <p>Declaramos para os devidos fins que o aluno(a) <strong>${selectedStudentForDecl.displayName}</strong>, 
            regularmente matriculado sob o registro acadêmico <strong>${selectedStudentForDecl.academicId || 'PROVISÓRIO'}</strong>, 
            encontra-se em pleno gozo de seus direitos acadêmicos junto a esta instituição de ensino teológico.</p>
            <p>${declContent}</p>
            <p>Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}</p>
          </div>
          <div class="footer">
            <p><strong>DIRETORIA DE ENSINO</strong></p>
            <p>Este documento possui validade jurídica digital.</p>
          </div>
        </body>
      </html>
    `;

    try {
      // Criamos um blob com o conteúdo HTML e o tipo application/pdf para forçar o navegador a tratar como tal
      // Nota: Em um ambiente produtivo real, isso seria convertido por uma biblioteca server-side.
      // Para o frontend, usamos o dataURI para simular o arquivo.
      const dataUri = `data:text/html;charset=utf-8,${encodeURIComponent(htmlContent)}`;

      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Matrículas', content: dataUri,
        uploader: 'Secretaria', createdAt: serverTimestamp(), size: htmlContent.length
      });
      alert("Declaração gerada e salva com sucesso!");
      setOpSubView('main');
    } catch (e) { alert("Erro ao salvar."); }
  };

  const handleTransfer = async () => {
    if (!transferData.studentId || !transferData.courseId) return;
    const student = students.find(s => s.uid === transferData.studentId);
    const course = courses.find(c => c.id === transferData.courseId);
    if (!student || !course) return;

    const fileName = `TERMO_TRANSFERENCIA_${student.displayName.replace(/\s/g, '_')}.pdf`;
    const htmlContent = `
      <html>
        <body style="font-family: sans-serif; padding: 40px;">
          <h1 style="text-align: center; color: #4f46e5;">TERMO DE TRANSFERÊNCIA</h1>
          <p>Confirmamos a transferência do aluno <strong>${student.displayName}</strong> para o curso <strong>${course.nome}</strong>.</p>
          <p>Data: ${new Date().toLocaleDateString()}</p>
        </body>
      </html>
    `;
    const dataUri = `data:text/html;charset=utf-8,${encodeURIComponent(htmlContent)}`;

    try {
      await updateDoc(doc(db, 'users', transferData.studentId), { cursoInicial: transferData.courseId });
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Históricos', content: dataUri,
        uploader: 'Sistema', createdAt: serverTimestamp(), size: htmlContent.length
      });
      alert("Transferência realizada e termo salvo!");
      setOpSubView('main');
    } catch (e) { alert("Erro na operação."); }
  };

  const handleApproveStudent = async (uid: string) => {
    if (confirm("Deseja validar a matrícula deste aluno? Ele terá acesso total ao sistema.")) {
      await updateDoc(doc(db, 'users', uid), { status: 'ativo', validatedAt: serverTimestamp() });
      alert("Aluno validado com sucesso!");
    }
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const newStatus = selectedTicket.status === 'Pendente' ? 'Em Atendimento' : 'Finalizado';
    if (newStatus === 'Finalizado' && !confirm("Deseja encerrar o atendimento?")) return;

    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus, lastUpdate: serverTimestamp() });
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), {
        text: `Status alterado para ${newStatus}`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification'
    });
    if (newStatus === 'Finalizado') setSelectedTicketId(null);
  };

  const handleArchiveTicket = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const isArchived = selectedTicket.status === 'Arquivado';
    const newStatus = isArchived ? 'Finalizado' : 'Arquivado';
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus });
    setSelectedTicketId(null);
  };

  const handleSendMessage = async (file?: { name: string, content: string }) => {
    if (!selectedTicketId || (!chatMessage.trim() && !file)) return;
    const data: any = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    if (file) { data.fileUrl = file.content; data.fileName = file.name; }
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), data);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage || file?.name, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handlePrint = () => {
    const frame = document.getElementById('pdf-viewer-frame') as HTMLIFrameElement;
    if (frame?.contentWindow) frame.contentWindow.print();
    else window.print();
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'validacao':
        const pendingStudents = students.filter(s => s.status === 'pendente' || !s.status);
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-3"><UserCheck className="text-indigo-600" /> Validação de Novos Alunos</h3>
                <button onClick={() => setOpSubView('main')} className="p-2.5 bg-white border border-slate-100 rounded-xl hover:bg-rose-50 transition-all"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase italic border-b">
                     <tr><th className="px-8 py-5">Solicitante</th><th className="px-8 py-5">E-mail</th><th className="px-8 py-5">Cadastro</th><th className="px-8 py-5 text-center">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pendingStudents.length === 0 ? (
                        <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black uppercase italic italic tracking-widest">Nenhuma matrícula aguardando validação</td></tr>
                      ) : pendingStudents.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50 transition-colors">
                           <td className="px-8 py-5 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-8 py-5 font-bold text-slate-400">{s.email}</td>
                           <td className="px-8 py-5 text-slate-400 font-medium">{s.createdAt?.seconds ? new Date(s.createdAt.seconds * 1000).toLocaleDateString() : 'Recent'}</td>
                           <td className="px-8 py-5 text-center">
                              <button onClick={() => handleApproveStudent(s.uid)} className="px-6 py-2 bg-indigo-600 text-white rounded-xl text-[8px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md italic">Validar Acesso</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'inadimplencia':
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-3"><ShieldAlert className="text-rose-500" /> Auditoria de Pendências</h3>
                <button onClick={() => setOpSubView('main')} className="p-2.5 bg-white border border-slate-100 rounded-xl hover:bg-rose-50 transition-all"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase italic border-b">
                     <tr><th className="px-8 py-5">Aluno</th><th className="px-8 py-5">Pendência</th><th className="px-8 py-5">Situação</th><th className="px-8 py-5 text-center">Gestão</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.map(s => (
                        <tr key={s.uid} className="hover:bg-rose-50/5 transition-colors">
                           <td className="px-8 py-5 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-8 py-5 font-bold text-slate-500">{s.pendingDebts ? 'Mensalidade em Atraso' : 'Fluxo Regular'}</td>
                           <td className="px-8 py-5">
                              <span className={`px-4 py-1 rounded-full font-black uppercase italic border ${s.financialStatus === 'Regularizado' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{s.financialStatus || 'Pendente'}</span>
                           </td>
                           <td className="px-8 py-5 flex justify-center gap-2">
                              <button onClick={() => alert('Notificação enviada')} className="p-2 text-amber-600 hover:scale-110"><Megaphone size={16}/></button>
                              <button onClick={() => updateDoc(doc(db, 'users', s.uid), { financialStatus: 'Regularizado', pendingDebts: false })} className="p-2 text-emerald-600 hover:scale-110"><CheckCircle size={16}/></button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-2xl max-w-4xl mx-auto space-y-8 animate-in zoom-in-95">
             <div className="flex items-center gap-4 border-b pb-6"><div className="p-3 bg-indigo-600 text-white rounded-xl"><FileSignature size={24}/></div><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Emissão de Declaração PDF</h3></div>
             <div className="space-y-6">
                <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-6 py-4 bg-slate-50 rounded-xl font-black text-xs shadow-inner border-none">
                   <option value="">Selecione o Aluno...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-slate-50 p-8 rounded-2xl border-2 border-dashed border-slate-200 outline-none text-sm font-medium italic min-h-[150px] shadow-inner" />
                <div className="flex gap-4">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Voltar</button>
                   <button onClick={handleSaveDeclaration} className="flex-1 py-5 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-xl flex items-center justify-center gap-2"><Save size={16}/> Gerar Documento PDF</button>
                </div>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-in zoom-in-95">
             {[
               { id: 'declaracao', title: 'Gerar Declaração PDF', icon: <FileText size={32}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
               { id: 'validacao', title: 'Validação de Alunos', icon: <UserCheck size={32}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
               { id: 'transferencia', title: 'Transferência Matriz', icon: <ArrowRightLeft size={32}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
               { id: 'inadimplencia', title: 'Auditoria Pendências', icon: <ShieldAlert size={32}/>, color: 'text-rose-600', bg: 'bg-rose-50' }
             ].map(op => (
               <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 transition-all flex flex-col items-center shadow-sm group">
                  <div className={`w-16 h-16 ${op.bg} ${op.color} rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform shadow-inner`}>{op.icon}</div>
                  <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{op.title}</h4>
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 pb-20 animate-in fade-in">
      <header className="flex justify-between items-center no-print">
        <div><h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter">Secretaria Master</h1><p className="text-slate-500 text-sm italic font-medium">Controle Acadêmico Unificado EB EAD.</p></div>
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button key={tab} onClick={() => {setActiveTab(tab); setSelectedTicketId(null); setOpSubView('main');}} className={`px-6 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'}`}>{tab}</button>
          ))}
        </div>
      </header>

      {/* SEARCH AND FILTER BAR (MODERNA) */}
      {(activeTab === 'atendimento' || activeTab === 'chat') && (
        <div className="bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm flex flex-col xl:flex-row items-center gap-4 no-print animate-in slide-in-from-top-2">
           <div className="relative flex-1 w-full">
              <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18}/>
              <input type="text" placeholder="Pesquisar protocolo ou nome do aluno..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-black uppercase outline-none shadow-inner" />
           </div>
           <div className="flex items-center gap-3 w-full xl:w-auto">
              <div className="relative flex-1">
                 <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                 <input type="date" value={dateStart} onChange={e => setDateStart(e.target.value)} className="w-full pl-10 pr-4 py-4 bg-slate-50 border-none rounded-2xl text-[9px] font-black outline-none shadow-sm" />
              </div>
              <span className="text-slate-300 font-black">/</span>
              <div className="relative flex-1">
                 <Calendar className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={14}/>
                 <input type="date" value={dateEnd} onChange={e => setDateEnd(e.target.value)} className="w-full pl-10 pr-4 py-4 bg-slate-50 border-none rounded-2xl text-[9px] font-black outline-none shadow-sm" />
              </div>
              <button onClick={() => {setSearchTerm(''); setDateStart(''); setDateEnd('');}} className="p-4 bg-slate-100 text-slate-400 rounded-2xl hover:bg-rose-50 hover:text-rose-600 transition-all"><RefreshCw size={18}/></button>
           </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 no-print">
         {[
           { label: 'Fila Espera', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={20}/> },
           { label: 'Em Suporte', value: stats.emAtendimento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <AlertCircle size={20}/> },
           { label: 'Taxa Êxito', value: stats.satisfacao, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <Star size={20}/> },
           { label: 'Acervo GED', value: stats.documentos, color: 'text-slate-600', bg: 'bg-slate-50', icon: <FolderOpen size={20}/> }
         ].map((s, i) => (
           <div key={i} className={`${s.bg} p-8 rounded-[2.5rem] border border-slate-200 flex items-center gap-6 shadow-sm`}>
              <div className="p-4 bg-white rounded-2xl text-slate-400 shadow-sm">{s.icon}</div>
              <div><p className="text-[8px] font-black uppercase text-slate-400 mb-1">{s.label}</p><p className="text-3xl font-black text-slate-900">{s.value}</p></div>
           </div>
         ))}
      </div>

      <main className="min-h-[600px]">
        {activeTab === 'chat' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 h-[750px]">
             <div className="lg:col-span-4 bg-white rounded-[3rem] border border-slate-200 overflow-hidden flex flex-col shadow-sm">
                <div className="p-6 border-b bg-slate-50/50 space-y-4 text-center">
                   <h4 className="text-[10px] font-black uppercase text-slate-400 italic">Central de Atendimentos</h4>
                   <div className="grid grid-cols-3 gap-2">
                      {['ativos', 'finalizados', 'arquivados'].map(f => (
                        <button key={f} onClick={() => setChatFilter(f as any)} className={`py-2.5 rounded-xl text-[8px] font-black uppercase transition-all ${chatFilter === f ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-400'}`}>{f}</button>
                      ))}
                   </div>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                   {filteredTickets.filter(t => chatFilter === 'ativos' ? (t.status === 'Pendente' || t.status === 'Em Atendimento') : chatFilter === 'finalizados' ? t.status === 'Finalizado' : t.status === 'Arquivado').map(t => (
                     <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-6 rounded-[2rem] border cursor-pointer transition-all ${selectedTicketId === t.id ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl' : 'bg-slate-50 hover:bg-white border-slate-100'}`}>
                        <div className="flex justify-between items-start mb-1"><p className="text-xs font-black uppercase italic">{t.user}</p><span className="text-[7px] font-black uppercase opacity-60">{t.status}</span></div>
                        <p className="text-[8px] font-bold opacity-60 truncate">{t.lastMessage || t.subject}</p>
                     </div>
                   ))}
                </div>
             </div>
             <div className="lg:col-span-8 bg-white rounded-[3rem] border border-slate-200 flex flex-col shadow-sm overflow-hidden relative">
                {selectedTicket ? (
                  <>
                    <div className="p-8 border-b flex justify-between items-center bg-slate-50/30">
                       <div><h4 className="text-sm font-black text-slate-900 uppercase italic tracking-tighter leading-none">{selectedTicket.user}</h4><span className="text-[8px] font-black text-indigo-600 uppercase mt-1 block italic">{selectedTicket.protocolo}</span></div>
                       <div className="flex gap-2">
                          {selectedTicket.status === 'Pendente' && <button onClick={handleToggleAttendance} className="px-8 py-2.5 rounded-xl text-[9px] font-black uppercase italic bg-indigo-600 text-white shadow-lg flex items-center gap-2"><PlayCircle size={16}/> Iniciar Atendimento</button>}
                          {selectedTicket.status === 'Em Atendimento' && <button onClick={handleToggleAttendance} className="px-8 py-2.5 rounded-xl text-[9px] font-black uppercase italic bg-rose-600 text-white shadow-lg flex items-center gap-2"><PowerOff size={16}/> Encerrar Atendimento</button>}
                          {selectedTicket.status === 'Finalizado' && <div className="px-5 py-2 bg-emerald-50 text-emerald-600 rounded-xl text-[8px] font-black uppercase flex items-center gap-2 border border-emerald-100"><CheckCircle size={14}/> Chat Finalizado</div>}

                          <button onClick={handleArchiveTicket} className="p-2.5 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-900 hover:text-white transition-all shadow-sm" title={selectedTicket.status === 'Arquivado' ? "Desarquivar" : "Arquivar"}>
                            {selectedTicket.status === 'Arquivado' ? <Undo2 size={18}/> : <Archive size={18}/>}
                          </button>
                          <button onClick={() => setSelectedTicketId(null)} className="p-2.5 bg-slate-50 text-slate-400 rounded-xl hover:bg-rose-50 transition-all"><X size={18}/></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-10 space-y-6 bg-slate-50/50 custom-scrollbar">
                       {chatHistory.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                            {m.type === 'notification' ? (
                                <div className="w-full flex justify-center"><div className="bg-white/50 border px-6 py-2 rounded-full text-[8px] font-black uppercase text-slate-400 italic shadow-sm">{m.text}</div></div>
                            ) : (
                                <div className={`max-w-[80%] p-6 rounded-[2rem] shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-600 rounded-tl-none'}`}>
                                    <p className="text-xs font-medium italic">{m.text}</p>
                                    {m.fileUrl && <button onClick={() => setViewerFile({content: m.fileUrl, title: m.fileName})} className="mt-4 flex items-center gap-2 p-2.5 bg-white/10 rounded-xl border border-white/5 text-[9px] uppercase font-black"><Paperclip size={14}/> {m.fileName}</button>}
                                </div>
                            )}
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>
                    {selectedTicket.status === 'Em Atendimento' && (
                        <div className="p-8 border-t bg-white shadow-2xl flex items-center gap-4 animate-in slide-in-from-bottom-5">
                            <button onClick={() => chatFileRef.current?.click()} className="p-4 text-slate-300 hover:text-indigo-600 transition-all"><Paperclip size={22}/></button>
                            <input type="file" ref={chatFileRef} className="hidden" onChange={(e) => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>handleSendMessage({name:f.name, content:ev.target?.result as string}); r.readAsDataURL(f); } }} />
                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Digite para o aluno..." className="flex-1 bg-slate-50 border-none rounded-2xl px-6 py-4 text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                            <button onClick={() => handleSendMessage()} className="p-4 bg-slate-900 text-white rounded-full hover:bg-indigo-600 transition-all shadow-xl"><Send size={24}/></button>
                        </div>
                    )}
                  </>
                ) : <div className="flex-1 flex flex-col items-center justify-center opacity-20 p-20 text-center gap-6"><MessageSquare size={80}/><p className="text-[10px] font-black uppercase tracking-[0.5em]">Selecione um chamado</p></div>}
             </div>
          </div>
        )}

        {activeTab === 'arquivos' && (
          currentFolder ? (
            <div className="space-y-6 animate-in slide-in-from-right-5">
               <div className="bg-white p-8 rounded-[3rem] border border-slate-200 flex justify-between items-center shadow-sm">
                  <div className="flex items-center gap-6">
                    <button onClick={() => setCurrentFolder(null)} className="p-3 bg-slate-50 rounded-xl text-slate-400 hover:bg-slate-900 hover:text-white transition-all"><ChevronLeft size={24}/></button>
                    <div><h3 className="text-2xl font-black text-slate-900 uppercase italic leading-none">{currentFolder}</h3><p className="text-[8px] font-black text-indigo-600 uppercase mt-1 italic">Arquivo Digital EB EAD</p></div>
                  </div>
                  <button onClick={() => setIsUploadModalOpen(true)} className="bg-slate-900 text-white px-8 py-3.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-2 shadow-xl hover:bg-indigo-600 transition-all italic"><Upload size={18}/> Novo Doc</button>
               </div>
               <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
                  <table className="w-full text-left">
                     <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase italic border-b"><tr><th className="px-10 py-5">Nome</th><th className="px-10 py-5">Categoria</th><th className="px-10 py-5 text-center">Gestão</th></tr></thead>
                     <tbody className="divide-y divide-slate-100 text-[10px]">
                        {files.filter(f => f.category === currentFolder).map(f => (
                          <tr key={f.id} className="hover:bg-indigo-50/10 transition-all">
                             <td className="px-10 py-5 font-black text-slate-900 uppercase italic">{f.title}</td>
                             <td className="px-10 py-5 font-bold text-slate-400 uppercase">{f.category}</td>
                             <td className="px-10 py-5 flex justify-center gap-2">
                                <button onClick={() => setViewerFile(f)} className="p-2.5 bg-white border border-slate-100 text-indigo-600 rounded-xl hover:bg-indigo-600 hover:text-white transition-all shadow-sm"><Eye size={16}/></button>
                                <a href={f.content} download={f.title} className="p-2.5 bg-white border border-slate-100 text-emerald-600 rounded-xl hover:bg-emerald-600 hover:text-white transition-all shadow-sm"><Download size={16}/></a>
                                <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'secretaria_arquivos', f.id)); }} className="p-2.5 bg-white border border-slate-100 text-rose-500 rounded-xl hover:bg-rose-600 transition-all shadow-sm"><Trash2 size={16}/></button>
                             </td>
                          </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-6">
               {['Matrículas', 'Financeiro', 'Históricos', 'Regulamentos', 'Certificados', 'Pautas'].map(f => (
                 <div key={f} onClick={() => setCurrentFolder(f)} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 transition-all cursor-pointer text-center group shadow-sm">
                    <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center mx-auto mb-6 group-hover:scale-110 transition-transform shadow-inner"><FolderOpen size={30}/></div>
                    <h4 className="text-[11px] font-black text-slate-900 uppercase italic leading-none">{f}</h4>
                    <p className="text-[7px] font-bold text-slate-400 uppercase mt-2">{files.filter(file => file.category === f).length} itens</p>
                 </div>
               ))}
            </div>
          )
        )}

        {activeTab === 'operacional' && renderOperationalView()}
        {activeTab === 'atendimento' && (
          <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
             <div className="p-8 border-b bg-slate-50/50 flex justify-between gap-4">
                <button onClick={() => setIsNewProtocolModalOpen(true)} className="bg-slate-900 text-white px-8 py-3.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-2 shadow-xl hover:bg-indigo-600 transition-all italic"><Plus size={16}/> Abrir Chamado Manual</button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase border-b italic"><tr><th className="px-10 py-5">Protocolo</th><th className="px-10 py-5">Requerente</th><th className="px-10 py-5">Assunto</th><th className="px-10 py-5">Status</th><th className="px-10 py-5 text-center">Ações</th></tr></thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {filteredTickets.map(t => (
                        <tr key={t.id} className="hover:bg-indigo-50/10 transition-colors">
                           <td className="px-10 py-5 font-mono font-bold text-indigo-600">{t.protocolo}</td>
                           <td className="px-10 py-5 font-black text-slate-900 uppercase italic">{t.user}</td>
                           <td className="px-10 py-5 font-bold text-slate-400 uppercase">{t.subject}</td>
                           <td className="px-10 py-5"><span className={`px-4 py-1 rounded-full border ${t.status === 'Finalizado' ? 'bg-emerald-50 text-emerald-600' : 'bg-amber-50 text-amber-600'}`}>{t.status}</span></td>
                           <td className="px-10 py-5 text-center"><button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-2.5 text-indigo-600 hover:scale-110 transition-all"><MessageSquare size={18}/></button></td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        )}
      </main>

      {/* FULLSCREEN DOCUMENT VIEWER */}
      {viewerFile && (
        <div className="fixed inset-0 z-[5000] bg-slate-950 flex flex-col animate-in fade-in duration-300">
           <header className="p-6 md:px-12 md:py-8 border-b border-white/10 flex items-center justify-between bg-slate-900 shadow-2xl">
              <div className="flex items-center gap-5">
                 <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-2xl"><FileSignature size={28}/></div>
                 <div><h3 className="text-xl md:text-2xl font-black text-white uppercase italic tracking-tighter leading-none">{viewerFile.title}</h3><p className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.4em] mt-2 italic">Visualização Imersiva Fullscreen</p></div>
              </div>
              <div className="flex items-center gap-4">
                 <button onClick={handlePrint} className="px-8 py-3.5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase italic hover:bg-indigo-700 flex items-center gap-3 shadow-2xl transition-all border border-indigo-400/30"><Printer size={18}/> Imprimir PDF</button>
                 <a href={viewerFile.content} download={viewerFile.title} className="px-8 py-3.5 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase italic hover:bg-emerald-700 flex items-center gap-3 shadow-2xl transition-all border border-emerald-400/30"><Download size={18}/> Baixar Arquivo</a>
                 <button onClick={() => setViewerFile(null)} className="p-5 bg-rose-600 hover:bg-rose-700 text-white rounded-2xl transition-all shadow-2xl active:scale-95 border border-rose-400/30"><X size={28}/></button>
              </div>
           </header>
           <div className="flex-1 bg-zinc-900 flex items-center justify-center overflow-hidden">
              <iframe id="pdf-viewer-frame" src={viewerFile.content} className="w-full h-full bg-white" title="PDF Viewer" />
           </div>
        </div>
      )}

      {/* NEW PROTOCOL MODAL */}
      {isNewProtocolModalOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-lg rounded-[3.5rem] p-12 shadow-2xl space-y-10 border-4 border-white/5">
              <div className="flex items-center justify-between"><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Novo Chamado</h3><button onClick={() => setIsNewProtocolModalOpen(false)} className="p-3 bg-slate-100 rounded-full hover:bg-rose-600 transition-all shadow-sm"><X size={20}/></button></div>
              <form onSubmit={async (e) => { e.preventDefault(); const pid = `PRT-${Date.now().toString().slice(-6)}`; const tref = await addDoc(collection(db, 'tickets'), {...newProtocol, protocolo: pid, status: 'Pendente', createdAt: serverTimestamp()}); await addDoc(collection(db, `tickets/${tref.id}/messages`), {text: `Protocolo ${pid} aberto.`, sender: 'Sistema', timestamp: serverTimestamp()}); setIsNewProtocolModalOpen(false); }} className="space-y-6">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Aluno Solicitante</label><input required value={newProtocol.user} onChange={e => setNewProtocol({...newProtocol, user: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-sm shadow-inner" placeholder="Nome do Aluno..." /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Motivo do Contato</label><select value={newProtocol.subject} onChange={e => setNewProtocol({...newProtocol, subject: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option>Acadêmico</option><option>Financeiro</option><option>Suporte Técnico</option></select></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Descrição Inicial</label><textarea required value={newProtocol.description} onChange={e => setNewProtocol({...newProtocol, description: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-2xl h-32 font-medium text-[11px] italic shadow-inner resize-none" placeholder="Relate o problema..." /></div>
                 <button type="submit" className="w-full py-6 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic hover:bg-indigo-600 shadow-2xl transition-all">Abrir Ticket Oficial</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive, Bell, ArrowRightLeft, Star, Heart,
  PlayCircle, PowerOff, UserCheck, ShieldAlert, FileSignature, Save, Megaphone, CheckCircle,
  Undo2, Calendar
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';
type ChatFilter = 'ativos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [viewerFile, setViewerFile] = useState<any | null>(null);
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição de ensino teológico.');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  const selectedTicket = useMemo(() => tickets.find(t => t.id === selectedTicketId) || null, [tickets, selectedTicketId]);

  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const total = tickets.length;
    const concluidos = tickets.filter(t => t.status === 'Finalizado' || t.status === 'Arquivado').length;
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      documentos: files.length,
      satisfacao: total > 0 ? ((concluidos / total) * 100).toFixed(1) + '%' : '100%'
    };
  }, [tickets, files]);

  const filteredTickets = useMemo(() => {
    return tickets.filter(t => {
      const matchSearch = t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase());

      let matchDate = true;
      if (dateStart || dateEnd) {
        const created = t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000) : new Date();
        if (dateStart) matchDate = matchDate && created >= new Date(dateStart + "T00:00:00");
        if (dateEnd) matchDate = matchDate && created <= new Date(dateEnd + "T23:59:59");
      }
      return matchSearch && matchDate;
    });
  }, [tickets, searchTerm, dateStart, dateEnd]);

  const handleSaveDeclaration = async () => {
    if (!selectedStudentForDecl) { alert("Selecione um aluno."); return; }
    const fileName = `DECLARACAO_${selectedStudentForDecl.displayName.replace(/\s/g, '_')}.pdf`;

    const htmlContent = `
      <!DOCTYPE html>
      <html>
        <head>
          <style>
            body { font-family: sans-serif; padding: 40px; color: #1e293b; line-height: 1.6; }
            .header { text-align: center; border-bottom: 2px solid #4f46e5; padding-bottom: 20px; margin-bottom: 40px; }
            .content { font-size: 14px; text-align: justify; margin-bottom: 60px; }
            .footer { text-align: center; border-top: 1px solid #e2e8f0; padding-top: 20px; font-size: 12px; }
            h1 { color: #4f46e5; margin: 0; text-transform: uppercase; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>Escola Bíblica EAD</h1>
            <p>Secretaria Acadêmica Master</p>
          </div>
          <h2 style="text-align: center;">DECLARAÇÃO DE MATRÍCULA</h2>
          <div class="content">
            <p>Declaramos para os devidos fins que o aluno(a) <strong>${selectedStudentForDecl.displayName}</strong>, 
            regularmente matriculado sob o registro acadêmico <strong>${selectedStudentForDecl.academicId || 'PROVISÓRIO'}</strong>, 
            encontra-se em pleno gozo de seus direitos acadêmicos junto a esta instituição de ensino teológico.</p>
            <p>${declContent}</p>
            <p>Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}</p>
          </div>
          <div class="footer">
            <p><strong>DIRETORIA DE ENSINO</strong></p>
            <p>Este documento possui validade jurídica digital.</p>
          </div>
        </body>
      </html>
    `;

    try {
      const dataUri = `data:text/html;charset=utf-8,${encodeURIComponent(htmlContent)}`;
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Matrículas', content: dataUri,
        uploader: 'Secretaria', createdAt: serverTimestamp(), size: htmlContent.length
      });
      alert("Declaração gerada e salva com sucesso!");
      setOpSubView('main');
    } catch (e) { alert("Erro ao salvar."); }
  };

  const handleTransfer = async () => {
    if (!transferData.studentId || !transferData.courseId) return;
    const student = students.find(s => s.uid === transferData.studentId);
    const course = courses.find(c => c.id === transferData.courseId);
    if (!student || !course) return;

    const fileName = `TERMO_TRANSFERENCIA_${student.displayName.replace(/\s/g, '_')}.pdf`;
    const htmlContent = `
      <html>
        <body style="font-family: sans-serif; padding: 40px;">
          <h1 style="text-align: center; color: #4f46e5;">TERMO DE TRANSFERÊNCIA</h1>
          <p>Confirmamos a transferência do aluno <strong>${student.displayName}</strong> para o curso <strong>${course.nome}</strong>.</p>
          <p>Data: ${new Date().toLocaleDateString()}</p>
        </body>
      </html>
    `;
    const dataUri = `data:text/html;charset=utf-8,${encodeURIComponent(htmlContent)}`;

    try {
      await updateDoc(doc(db, 'users', transferData.studentId), { cursoInicial: transferData.courseId });
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Históricos', content: dataUri,
        uploader: 'Sistema', createdAt: serverTimestamp(), size: htmlContent.length
      });
      alert("Transferência realizada e termo salvo!");
      setOpSubView('main');
    } catch (e) { alert("Erro na operação."); }
  };

  const handleApproveStudent = async (uid: string) => {
    if (confirm("Deseja validar a matrícula deste aluno? Ele terá acesso total ao sistema.")) {
      await updateDoc(doc(db, 'users', uid), { status: 'ativo', validatedAt: serverTimestamp() });
      alert("Aluno validado com sucesso!");
    }
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const newStatus = selectedTicket.status === 'Pendente' ? 'Em Atendimento' : 'Finalizado';
    if (newStatus === 'Finalizado' && !confirm("Deseja encerrar o atendimento?")) return;

    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus, lastUpdate: serverTimestamp() });
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), {
        text: `Status alterado para ${newStatus}`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification'
    });
    if (newStatus === 'Finalizado') setSelectedTicketId(null);
  };

  const handleArchiveTicket = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const isArchived = selectedTicket.status === 'Arquivado';
    const newStatus = isArchived ? 'Finalizado' : 'Arquivado';
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus });
    setSelectedTicketId(null);
  };

  const handleSendMessage = async (file?: { name: string, content: string }) => {
    if (!selectedTicketId || (!chatMessage.trim() && !file)) return;
    const data: any = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    if (file) { data.fileUrl = file.content; data.fileName = file.name; }
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), data);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage || file?.name, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handlePrint = () => {
    const frame = document.getElementById('pdf-viewer-frame') as HTMLIFrameElement;
    if (frame?.contentWindow) frame.contentWindow.print();
    else window.print();
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'validacao':
        // Filtramos alunos que não estão com status "ativo" para a fila de validação
        const pendingStudents = students.filter(s => s.status === 'pendente' || !s.status || s.status === 'rascunho');
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-3"><UserCheck className="text-indigo-600" /> Validação de Novos Alunos</h3>
                <button onClick={() => setOpSubView('main')} className="p-2.5 bg-white border border-slate-100 rounded-xl hover:bg-rose-50 transition-all"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase italic border-b">
                     <tr><th className="px-8 py-5">Solicitante</th><th className="px-8 py-5">E-mail</th><th className="px-8 py-5">Cadastro</th><th className="px-8 py-5 text-center">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pendingStudents.length === 0 ? (
                        <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black uppercase italic tracking-widest">Nenhuma matrícula aguardando validação</td></tr>
                      ) : pendingStudents.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50 transition-colors">
                           <td className="px-8 py-5 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-8 py-5 font-bold text-slate-400">{s.email}</td>
                           <td className="px-8 py-5 text-slate-400 font-medium">{s.createdAt?.seconds ? new Date(s.createdAt.seconds * 1000).toLocaleDateString() : 'Recente'}</td>
                           <td className="px-8 py-5 text-center">
                              <button onClick={() => handleApproveStudent(s.uid)} className="px-6 py-2 bg-indigo-600 text-white rounded-xl text-[8px] font-black uppercase hover:bg-indigo-700 transition-all shadow-md italic">Validar Acesso</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'inadimplencia':
        return (
          <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden animate-in slide-in-from-right-5">
             <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-3"><ShieldAlert className="text-rose-500" /> Auditoria de Pendências</h3>
                <button onClick={() => setOpSubView('main')} className="p-2.5 bg-white border border-slate-100 rounded-xl hover:bg-rose-50 transition-all"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase italic border-b">
                     <tr><th className="px-8 py-5">Aluno</th><th className="px-8 py-5">Pendência</th><th className="px-8 py-5">Situação</th><th className="px-8 py-5 text-center">Gestão</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.map(s => (
                        <tr key={s.uid} className="hover:bg-rose-50/5 transition-colors">
                           <td className="px-8 py-5 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-8 py-5 font-bold text-slate-500">{s.pendingDebts ? 'Mensalidade em Atraso' : 'Fluxo Regular'}</td>
                           <td className="px-8 py-5">
                              <span className={`px-4 py-1 rounded-full font-black uppercase italic border ${s.financialStatus === 'Regularizado' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{s.financialStatus || 'Pendente'}</span>
                           </td>
                           <td className="px-8 py-5 flex justify-center gap-2">
                              <button onClick={() => alert('Notificação enviada')} className="p-2 text-amber-600 hover:scale-110"><Megaphone size={16}/></button>
                              <button onClick={() => updateDoc(doc(db, 'users', s.uid), { financialStatus: 'Regularizado', pendingDebts: false })} className="p-2 text-emerald-600 hover:scale-110"><CheckCircle size={16}/></button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-2xl max-w-4xl mx-auto space-y-8 animate-in zoom-in-95">
             <div className="flex items-center gap-4 border-b pb-6"><div className="p-3 bg-indigo-600 text-white rounded-xl"><FileSignature size={24}/></div><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Emissão de Declaração PDF</h3></div>
             <div className="space-y-6">
                <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-6 py-4 bg-slate-50 rounded-xl font-black text-xs shadow-inner border-none">
                   <option value="">Selecione o Aluno...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-slate-50 p-8 rounded-2xl border-2 border-dashed border-slate-200 outline-none text-sm font-medium italic min-h-[150px] shadow-inner" />
                <div className="flex gap-4">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Voltar</button>
                   <button onClick={handleSaveDeclaration} className="flex-1 py-5 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-xl flex items-center justify-center gap-2"><Save size={16}/> Gerar Documento PDF</button>
                </div>
             </div>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white p-12 rounded-[3.5rem] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8 animate-in slide-in-from-bottom-5">
             <div className="flex items-center gap-4 border-b pb-6"><div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><ArrowRightLeft size={24}/></div><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Transferência Matriz</h3></div>
             <div className="space-y-6">
                <select value={transferData.studentId} onChange={e => setTransferData({...transferData, studentId: e.target.value})} className="w-full px-6 py-4 bg-slate-50 rounded-xl font-black text-xs shadow-inner border-none">
                   <option value="">Aluno...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <select value={transferData.courseId} onChange={e => setTransferData({...transferData, courseId: e.target.value})} className="w-full px-6 py-4 bg-slate-50 rounded-xl font-black text-xs shadow-inner border-none">
                   <option value="">Novo Curso...</option>
                   {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
                <div className="flex gap-4">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Voltar</button>
                   <button onClick={handleTransfer} className="flex-1 py-5 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase italic shadow-lg">Efetivar Transferência</button>
                </div>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 animate-in zoom-in-95">
             {[
               { id: 'declaracao', title: 'Gerar Declaração PDF', icon: <FileText size={32}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
               { id: 'validacao', title: 'Validação de Alunos', icon: <UserCheck size={32}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
               { id: 'transferencia', title: 'Transferência Matriz', icon: <ArrowRightLeft size={32}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
               { id: 'inadimplencia', title: 'Auditoria Pendências', icon: <ShieldAlert size={32}/>, color: 'text-rose-600', bg: 'bg-rose-50' }
             ].map(op => (
               <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className="bg-white p-10 rounded-[3rem] border border-slate-200 hover:border-indigo-400 transition-all flex flex-col items-center shadow-sm group">
                  <div className={`w-16 h-16 ${op.bg} ${op.color} rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform shadow-inner`}>{op.icon}</div>
                  <h4 className="text-[11px] font-black text-slate-900 uppercase italic tracking-tight">{op.title}</h4>
               </button>
             ))}
          </div>
        );
