                 <select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-8 py-4 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner outline-none"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select>
                 <div className="border-4 border-dashed border-slate-100 rounded-3xl p-16 text-center hover:border-indigo-400 transition-all relative group shadow-inner bg-slate-50/50">
                    <input type="file" onChange={(e) => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=async(ev)=>{ await addDoc(collection(db, 'secretaria_arquivos'), {title:f.name, category:uploadData.category, content:ev.target?.result, uploader:'Secretaria', createdAt:serverTimestamp(), size:f.size}); setIsUploadModalOpen(false); }; r.readAsDataURL(f); } }} className="absolute inset-0 opacity-0 cursor-pointer" accept=".pdf,.png,.jpg,.jpeg,.webp" />
                    <FileText size={54} className="text-slate-200 mx-auto mb-4 group-hover:text-indigo-400 transition-colors" /><p className="text-[10px] font-black uppercase text-slate-400 tracking-[0.4em] italic">Anexar Documento</p>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(false)} className="w-full py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-rose-50 transition-all">Cancelar</button>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive, Bell, ArrowRightLeft, Star, Heart,
  PlayCircle, PowerOff, UserCheck, ShieldAlert, FileSignature, Save, Megaphone, CheckCircle,
  Undo2, Calendar
} from 'lucide-react';

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';
type ChatFilter = 'ativos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [viewerFile, setViewerFile] = useState<any | null>(null);
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição de ensino teológico.');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  const selectedTicket = useMemo(() => tickets.find(t => t.id === selectedTicketId) || null, [tickets, selectedTicketId]);

  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const total = tickets.length;
    const concluidos = tickets.filter(t => t.status === 'Finalizado' || t.status === 'Arquivado').length;
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      documentos: files.length,
      satisfacao: total > 0 ? ((concluidos / total) * 100).toFixed(1) + '%' : '100%'
    };
  }, [tickets, files]);

  const filteredTickets = useMemo(() => {
    return tickets.filter(t => {
      const matchSearch = t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase());
      let matchDate = true;
      if (dateStart || dateEnd) {
        const created = t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000) : new Date();
        if (dateStart) matchDate = matchDate && created >= new Date(dateStart + "T00:00:00");
        if (dateEnd) matchDate = matchDate && created <= new Date(dateEnd + "T23:59:59");
      }
      return matchSearch && matchDate;
    });
  }, [tickets, searchTerm, dateStart, dateEnd]);

  // DESIGN ANTERIOR RESTAURADO (LIMPO E ELEGANTE)
  const generateCleanDocumentHTML = (title: string, bodyText: string) => {
    return `
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="UTF-8">
          <style>
            body { font-family: sans-serif; padding: 40px; color: #1e293b; line-height: 1.6; background: white; }
            .header { text-align: center; border-bottom: 2px solid #4f46e5; padding-bottom: 20px; margin-bottom: 40px; }
            .content { font-size: 14px; text-align: justify; margin-bottom: 60px; }
            .footer { text-align: center; border-top: 1px solid #e2e8f0; padding-top: 20px; font-size: 12px; }
            h1 { color: #4f46e5; margin: 0; text-transform: uppercase; font-size: 24px; }
            p { margin: 10px 0; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>Escola Bíblica EAD</h1>
            <p>Secretaria Acadêmica Master</p>
          </div>
          <h2 style="text-align: center; font-size: 18px;">${title.toUpperCase()}</h2>
          <div class="content">
            ${bodyText}
            <p style="margin-top: 30px;">Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}</p>
          </div>
          <div class="footer">
            <p><strong>DIRETORIA DE ENSINO</strong></p>
            <p>Este documento possui validade jurídica digital.</p>
          </div>
        </body>
      </html>
    `;
  };

  const handleSaveDeclaration = async () => {
    if (!selectedStudentForDecl) { alert("Selecione um aluno."); return; }
    const fileName = `DECLARACAO_${selectedStudentForDecl.displayName.replace(/\s/g, '_')}.pdf`;
    const body = `
      <p>Declaramos para os devidos fins que o aluno(a) <strong>${selectedStudentForDecl.displayName}</strong>, 
      regularmente matriculado sob o registro acadêmico <strong>${selectedStudentForDecl.academicId || 'PROVISÓRIO'}</strong>, 
      encontra-se em pleno gozo de seus direitos acadêmicos junto a esta instituição de ensino teológico.</p>
      <p>${declContent}</p>
    `;
    try {
      const html = generateCleanDocumentHTML('Declaração de Matrícula', body);
      // Para o visualizador nativo funcionar com as opções de download/print, passamos o HTML como Data URI mas forçamos o download via metadata
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Matrículas', content: `data:text/html;charset=utf-8,${encodeURIComponent(html)}`,
        uploader: 'Secretaria', createdAt: serverTimestamp(), size: html.length
      });
      alert("Documento gerado e salvo!");
      setOpSubView('main');
    } catch (e) { alert("Erro ao salvar."); }
  };

  const handleTransfer = async () => {
    if (!transferData.studentId || !transferData.courseId) return;
    const student = students.find(s => s.uid === transferData.studentId);
    const course = courses.find(c => c.id === transferData.courseId);
    if (!student || !course) return;

    const fileName = `TERMO_TRANSFERENCIA_${student.displayName.replace(/\s/g, '_')}.pdf`;
    const body = `
      <p>Confirmamos a transferência do aluno <strong>${student.displayName}</strong>, matrícula <strong>${student.academicId || 'N/A'}</strong>, para o curso <strong>${course.nome}</strong>.</p>
      <p>A alteração curricular foi processada e o aluno encontra-se apto para as novas disciplinas.</p>
    `;
    try {
      const html = generateCleanDocumentHTML('Termo de Transferência', body);
      await updateDoc(doc(db, 'users', transferData.studentId), { cursoInicial: transferData.courseId });
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Históricos', content: `data:text/html;charset=utf-8,${encodeURIComponent(html)}`,
        uploader: 'Sistema', createdAt: serverTimestamp(), size: html.length
      });
      alert("Transferência realizada!");
      setOpSubView('main');
    } catch (e) { alert("Erro na operação."); }
  };

  const handleApproveStudent = async (uid: string) => {
    if (confirm("Validar matrícula deste aluno?")) {
      await updateDoc(doc(db, 'users', uid), { status: 'ativo', validatedAt: serverTimestamp() });
      alert("Aluno validado!");
    }
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const newStatus = selectedTicket.status === 'Pendente' ? 'Em Atendimento' : 'Finalizado';
    if (newStatus === 'Finalizado' && !confirm("Encerrar atendimento?")) return;
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus, lastUpdate: serverTimestamp() });
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), {
        text: `Status alterado para ${newStatus}`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification'
    });
    if (newStatus === 'Finalizado') setSelectedTicketId(null);
  };

  const handleArchiveTicket = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: selectedTicket.status === 'Arquivado' ? 'Finalizado' : 'Arquivado' });
    setSelectedTicketId(null);
  };

  const handleSendMessage = async (file?: { name: string, content: string }) => {
    if (!selectedTicketId || (!chatMessage.trim() && !file)) return;
    const data: any = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    if (file) { data.fileUrl = file.content; data.fileName = file.name; }
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), data);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage || file?.name, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'validacao':
        const pendingStudents = students.filter(s => s.status === 'pendente' || !s.status || s.status === 'rascunho' || s.status === 'inativo');
        return (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-sm font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-2"><UserCheck size={16} className="text-indigo-600" /> Validação de Matrículas</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-lg"><X size={16}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase italic border-b">
                     <tr><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">E-mail</th><th className="px-6 py-3 text-center">Gestão</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pendingStudents.length === 0 ? (
                        <tr><td colSpan={3} className="p-10 text-center text-slate-300 font-black uppercase text-[10px]">Sem pendências</td></tr>
                      ) : pendingStudents.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50 transition-colors">
                           <td className="px-6 py-3 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-6 py-3 font-bold text-slate-400">{s.email}</td>
                           <td className="px-6 py-3 text-center">
                              <button onClick={() => handleApproveStudent(s.uid)} className="px-4 py-1.5 bg-indigo-600 text-white rounded-lg text-[8px] font-black uppercase italic">Validar</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'inadimplencia':
        return (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-sm font-black text-slate-900 uppercase italic tracking-tighter flex items-center gap-2"><ShieldAlert size={16} className="text-rose-500" /> Auditoria Financeira</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-lg"><X size={16}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase border-b">
                     <tr><th className="px-6 py-3">Aluno</th><th className="px-6 py-3">Situação</th><th className="px-6 py-3">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.map(s => (
                        <tr key={s.uid} className="hover:bg-rose-50/5 transition-colors">
                           <td className="px-6 py-3 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-6 py-3"><span className={`px-3 py-1 rounded-full font-black uppercase italic text-[8px] border ${s.financialStatus === 'Regularizado' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>{s.financialStatus || 'Pendente'}</span></td>
                           <td className="px-6 py-3 flex gap-2">
                              <button className="p-2 text-amber-600 hover:scale-110 transition-transform"><Megaphone size={14}/></button>
                              <button onClick={() => updateDoc(doc(db, 'users', s.uid), { financialStatus: 'Regularizado', pendingDebts: false })} className="p-2 text-emerald-600 hover:scale-110 transition-transform"><CheckCircle size={14}/></button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-xl max-w-2xl mx-auto space-y-6 animate-in zoom-in-95">
             <div className="flex items-center gap-3 border-b pb-4"><div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg"><FileSignature size={20}/></div><h3 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter">Emissão de Declaração</h3></div>
             <div className="space-y-4">
                <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Selecione o Aluno...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-slate-50 p-6 rounded-2xl border-2 border-dashed border-slate-200 outline-none text-xs font-medium italic min-h-[120px] shadow-inner" />
                <div className="flex gap-3">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Cancelar</button>
                   <button onClick={handleSaveDeclaration} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg italic flex items-center justify-center gap-2"><Save size={16}/> Gerar e Arquivar</button>
                </div>
             </div>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm max-w-xl mx-auto space-y-6 animate-in fade-in">
             <div className="flex items-center gap-3 border-b pb-4"><div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><ArrowRightLeft size={20}/></div><h3 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter">Transferência Matriz</h3></div>
             <div className="space-y-4">
                <select value={transferData.studentId} onChange={e => setTransferData({...transferData, studentId: e.target.value})} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Aluno Solicitante...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <select value={transferData.courseId} onChange={e => setTransferData({...transferData, courseId: e.target.value})} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Novo Curso...</option>
                   {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
                <div className="flex gap-3">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Voltar</button>
                   <button onClick={handleTransfer} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg italic">Processar</button>
                </div>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-in zoom-in-95">
             {[
               { id: 'declaracao', title: 'Declarações PDF', icon: <FileText size={20}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
               { id: 'validacao', title: 'Validação Alunos', icon: <UserCheck size={20}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
               { id: 'transferencia', title: 'Transferências', icon: <ArrowRightLeft size={20}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
               { id: 'inadimplencia', title: 'Auditoria Finan.', icon: <ShieldAlert size={20}/>, color: 'text-rose-600', bg: 'bg-rose-50' }
             ].map(op => (
               <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className="bg-white p-6 rounded-2xl border border-slate-200 hover:border-indigo-400 transition-all flex flex-col items-center shadow-sm group">
                  <div className={`w-12 h-12 ${op.bg} ${op.color} rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-inner`}>{op.icon}</div>
                  <h4 className="text-[9px] font-black text-slate-900 uppercase italic tracking-tight">{op.title}</h4>
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 pb-10 animate-in fade-in h-full">
      <header className="flex justify-between items-center no-print">
        <div><h1 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Secretaria Digital</h1><p className="text-slate-500 text-[10px] italic font-medium mt-1 uppercase tracking-widest">Gestão Acadêmica Central EB-EAD</p></div>
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button key={tab} onClick={() => {setActiveTab(tab); setSelectedTicketId(null); setOpSubView('main');}} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'}`}>{tab}</button>
          ))}
        </div>
      </header>

      {(activeTab === 'atendimento' || activeTab === 'chat') && (
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col xl:flex-row items-center gap-4 no-print animate-in slide-in-from-top-1">
           <div className="relative flex-[2] w-full">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
              <input type="text" placeholder="BUSCAR ALUNO OU PROTOCOLO..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-12 pr-6 py-3.5 bg-slate-50 border-none rounded-xl text-[9px] font-black uppercase outline-none shadow-inner tracking-widest" />
           </div>
           <div className="flex items-center gap-3 w-full xl:w-auto bg-slate-50 p-1.5 rounded-xl border border-slate-100 flex-1">
              <input type="date" value={dateStart} onChange={e => setDateStart(e.target.value)} className="flex-1 bg-transparent border-none text-[9px] font-black outline-none px-2" />
              <span className="text-slate-300 font-black">-</span>
              <input type="date" value={dateEnd} onChange={e => setDateEnd(e.target.value)} className="flex-1 bg-transparent border-none text-[9px] font-black outline-none px-2" />
              <button onClick={() => {setSearchTerm(''); setDateStart(''); setDateEnd('');}} className="p-2 bg-white text-slate-400 rounded-lg hover:text-rose-500 shadow-sm"><RefreshCw size={14}/></button>
           </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 no-print">
         {[
           { label: 'Matrículas', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={16}/> },
