                  <div className="flex items-center gap-4">
                    <button onClick={() => setCurrentFolder(null)} className="p-2.5 bg-slate-50 rounded-xl text-slate-400 hover:bg-slate-900 hover:text-white border border-slate-100 shadow-sm"><ChevronLeft size={20}/></button>
                    <div><h3 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter leading-none">{currentFolder}</h3><p className="text-[8px] font-black text-indigo-600 uppercase mt-0.5 italic tracking-widest">Documentos GED</p></div>
                  </div>
                  <button onClick={() => setIsUploadModalOpen(true)} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-2 shadow-lg hover:bg-indigo-600 transition-all italic"><Upload size={16}/> Novo Doc</button>
               </div>
               <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
                  <table className="w-full text-left">
                     <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase italic border-b tracking-widest">
                       <tr>
                         <th className="px-8 py-4">Nomenclatura</th>
                         <th className="px-8 py-4">Tamanho</th>
                         <th className="px-8 py-4">Tipo</th>
                         <th className="px-8 py-4">Anexado por</th>
                         <th className="px-8 py-4 text-center">Gestão</th>
                       </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100 text-[10px]">
                        {files.filter(f => f.category === currentFolder).map(f => (
                          <tr key={f.id} className="hover:bg-indigo-50/20 transition-all">
                             <td className="px-8 py-4 font-black text-slate-900 uppercase italic">{f.title}</td>
                             <td className="px-8 py-4 font-bold text-slate-400 uppercase">{formatFileSize(f.size)}</td>
                             <td className="px-8 py-4 font-bold text-indigo-600 uppercase">{f.type === 'application/pdf' ? 'PDF' : 'DOC'}</td>
                             <td className="px-8 py-4 font-bold text-slate-400 uppercase italic">{f.uploader || 'Sistema'}</td>
                             <td className="px-8 py-4 flex justify-center gap-2">
                                <button onClick={() => setViewerFile(f)} className="p-2 bg-white border border-slate-100 text-indigo-600 rounded-lg hover:bg-indigo-600 hover:text-white transition-all"><Eye size={16}/></button>
                                <button onClick={() => handleDirectDownload(f)} className="p-2 bg-white border border-slate-100 text-emerald-600 rounded-lg hover:bg-emerald-600 hover:text-white transition-all"><Download size={16}/></button>
                                <button onClick={async () => { if(confirm('Excluir arquivo permanentemente?')) await deleteDoc(doc(db, 'secretaria_arquivos', f.id)); }} className="p-2 bg-white border border-slate-100 text-rose-500 rounded-lg hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={16}/></button>
                             </td>
                          </tr>
                        ))}
                     </tbody>
                  </table>
               </div>
            </div>
          ) : (
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4 animate-in zoom-in-95">
               {['Matrículas', 'Financeiro', 'Históricos', 'Regulamentos', 'Certificados', 'Pautas'].map(f => (
                 <div key={f} onClick={() => setCurrentFolder(f)} className="bg-white p-8 rounded-2xl border border-slate-200 hover:border-indigo-400 transition-all cursor-pointer text-center group shadow-sm">
