          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 animate-in zoom-in-95">
             {[
               { id: 'declaracao', title: 'Declarações PDF', icon: <FileText size={20}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
               { id: 'validacao', title: 'Validação Alunos', icon: <UserCheck size={20}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
               { id: 'transferencia', title: 'Transferências', icon: <ArrowRightLeft size={20}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
               { id: 'inadimplencia', title: 'Auditoria Finan.', icon: <ShieldAlert size={20}/>, color: 'text-rose-600', bg: 'bg-rose-50' }
             ].map(op => (
               <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className="bg-white p-6 rounded-2xl border border-slate-200 hover:border-indigo-400 transition-all flex flex-col items-center shadow-sm group">
                  <div className={`w-12 h-12 ${op.bg} ${op.color} rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-inner`}>{op.icon}</div>
                  <h4 className="text-[9px] font-black text-slate-900 uppercase italic tracking-tight">{op.title}</h4>
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 pb-10 animate-in fade-in h-full">
      <header className="flex justify-between items-center no-print">
        <div><h1 className="text-xl font-black text-slate-900 uppercase italic leading-none">Secretaria Master</h1><p className="text-slate-500 text-[10px] italic font-medium mt-1 uppercase tracking-widest">Gestão Acadêmica Central EB-EAD</p></div>
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button key={tab} onClick={() => {setActiveTab(tab); setSelectedTicketId(null); setOpSubView('main');}} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'}`}>{tab}</button>
          ))}
        </div>
      </header>

      {(activeTab === 'atendimento' || activeTab === 'chat') && (
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col xl:flex-row items-center gap-4 no-print animate-in slide-in-from-top-1">
           <div className="relative flex-[2] w-full">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
              <input type="text" placeholder="BUSCAR ALUNO OU PROTOCOLO..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-12 pr-6 py-3.5 bg-slate-50 border-none rounded-xl text-[9px] font-black uppercase outline-none shadow-inner tracking-widest" />
           </div>
           <div className="flex items-center gap-3 w-full xl:w-auto bg-slate-50 p-1.5 rounded-xl border border-slate-100 flex-1">
              <input type="date" value={dateStart} onChange={e => setDateStart(e.target.value)} className="flex-1 bg-transparent border-none text-[9px] font-black outline-none px-2" />
              <span className="text-slate-300 font-black">-</span>
              <input type="date" value={dateEnd} onChange={e => setDateEnd(e.target.value)} className="flex-1 bg-transparent border-none text-[9px] font-black outline-none px-2" />
              <button onClick={() => {setSearchTerm(''); setDateStart(''); setDateEnd('');}} className="p-2 bg-white text-slate-400 rounded-lg hover:text-rose-50 shadow-sm"><RefreshCw size={14}/></button>
           </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 no-print">
         {[
           { label: 'Matrículas', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={16}/> },
           { label: 'Chamados', value: stats.emAtendimento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <AlertCircle size={16}/> },
           { label: 'Eficiência', value: stats.satisfacao, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <Star size={16}/> },
           { label: 'GED Acervo', value: stats.documentos, color: 'text-slate-600', bg: 'bg-slate-50', icon: <FolderOpen size={16}/> }
         ].map((s, i) => (
           <div key={i} className={`${s.bg} p-4 rounded-2xl border border-slate-200 flex items-center gap-4 shadow-sm`}>
              <div className="p-2.5 bg-white rounded-lg text-slate-400 shadow-sm border border-slate-100 shrink-0">{s.icon}</div>
              <div><p className="text-[7px] font-black uppercase text-slate-400 mb-0.5 italic">{s.label}</p><p className="text-xl font-black text-slate-900 leading-none">{s.value}</p></div>
           </div>
         ))}
      </div>

      <main className="flex-1 min-h-[400px]">
        {activeTab === 'chat' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 h-[600px]">
             <div className="lg:col-span-4 bg-white rounded-2xl border border-slate-200 overflow-hidden flex flex-col shadow-sm">
                <div className="p-5 border-b bg-slate-50/50 space-y-3 text-center">
                   <h4 className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Atendimentos</h4>
                   <div className="grid grid-cols-3 gap-1.5">
                      {['ativos', 'finalizados', 'arquivados'].map(f => (
                        <button key={f} onClick={() => setChatFilter(f as any)} className={`py-2 rounded-lg text-[8px] font-black uppercase transition-all shadow-sm ${chatFilter === f ? 'bg-slate-900 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}>{f}</button>
                      ))}
                   </div>
                </div>
                <div className="flex-1 overflow-y-auto p-3 space-y-2 custom-scrollbar">
                   {filteredTickets.filter(t => chatFilter === 'ativos' ? (t.status === 'Pendente' || t.status === 'Em Atendimento') : chatFilter === 'finalizados' ? t.status === 'Finalizado' : t.status === 'Arquivado').map(t => (
                     <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-4 rounded-xl border cursor-pointer transition-all ${selectedTicketId === t.id ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg' : 'bg-slate-50 hover:bg-white border-slate-100'}`}>
                        <div className="flex justify-between items-start mb-1"><p className="text-[10px] font-black uppercase italic tracking-tight">{t.user}</p><span className="text-[6px] font-black uppercase opacity-60 bg-black/10 px-1.5 py-0.5 rounded-full">{t.status}</span></div>
                        <p className="text-[8px] font-bold opacity-60 truncate italic">{t.lastMessage || t.subject}</p>
                     </div>
                   ))}
                </div>
             </div>
             <div className="lg:col-span-8 bg-white rounded-2xl border border-slate-200 flex flex-col shadow-sm overflow-hidden relative">
                {selectedTicket ? (
                  <>
                    <div className="p-5 border-b flex justify-between items-center bg-slate-50/30">
                       <div><h4 className="text-sm font-black text-slate-900 uppercase italic leading-none">{selectedTicket.user}</h4><span className="text-[8px] font-black text-indigo-600 uppercase mt-1 block italic">{selectedTicket.protocolo}</span></div>
                       <div className="flex gap-1.5">
                          {selectedTicket.status === 'Pendente' && <button onClick={handleToggleAttendance} className="px-4 py-2 rounded-lg text-[8px] font-black uppercase italic bg-indigo-600 text-white shadow-lg"><PlayCircle size={14} className="inline mr-1"/> Iniciar</button>}
                          {selectedTicket.status === 'Em Atendimento' && <button onClick={handleToggleAttendance} className="px-4 py-2 rounded-lg text-[8px] font-black uppercase italic bg-rose-600 text-white shadow-lg"><PowerOff size={14} className="inline mr-1"/> Encerrar</button>}
                          {selectedTicket.status === 'Finalizado' && <div className="px-4 py-2 bg-emerald-50 text-emerald-600 rounded-lg text-[8px] font-black uppercase italic"><CheckCircle size={12} className="inline mr-1"/> Concluído</div>}
                          <button onClick={handleArchiveTicket} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:bg-slate-900 hover:text-white border border-slate-100"><Archive size={16}/></button>
                          <button onClick={() => setSelectedTicketId(null)} className="p-2 bg-slate-50 text-slate-400 rounded-lg hover:bg-rose-50 border border-slate-100"><X size={16}/></button>
                       </div>
                    </div>
                    <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50 custom-scrollbar">
                       {chatHistory.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                            {m.type === 'notification' ? (
                                <div className="w-full flex justify-center my-2"><div className="bg-white/80 border border-slate-200 px-4 py-1.5 rounded-full text-[7px] font-black uppercase text-slate-400 italic shadow-sm">{m.text}</div></div>
                            ) : (
                                <div className={`max-w-[85%] p-4 rounded-2xl shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-600 rounded-tl-none'}`}>
                                    <p className="text-[11px] font-medium italic leading-relaxed">{m.text}</p>
                                    {m.fileUrl && <button onClick={() => setViewerFile({content: m.fileUrl, title: m.fileName})} className="mt-3 flex items-center gap-2 p-2 bg-white/10 rounded-lg border border-white/5 text-[8px] uppercase font-black hover:bg-white/20 transition-all"><Paperclip size={12}/> {m.fileName}</button>}
                                </div>
                            )}
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>
                    {selectedTicket.status === 'Em Atendimento' && (
                        <div className="p-4 border-t bg-white flex items-center gap-3 animate-in slide-in-from-bottom-1">
                            <button onClick={() => chatFileRef.current?.click()} className="p-3 text-slate-300 hover:text-indigo-600 transition-all bg-slate-50 rounded-xl"><Paperclip size={18}/></button>
                            <input type="file" ref={chatFileRef} className="hidden" onChange={(e) => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>handleSendMessage({name:f.name, content:ev.target?.result as string}); r.readAsDataURL(f); } }} />
                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ACADÊMICA..." className="flex-1 bg-slate-50 border-none rounded-xl px-5 py-3 text-[9px] font-black uppercase tracking-widest shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                            <button onClick={() => handleSendMessage()} className="p-3 bg-slate-900 text-white rounded-full hover:bg-indigo-600 transition-all shadow-md active:scale-95"><Send size={20}/></button>
                        </div>
