                  </>
                ) : <div className="flex-1 flex flex-col items-center justify-center opacity-20 p-20 text-center gap-4"><MessageSquare size={80}/><p className="text-[10px] font-black uppercase tracking-[0.4em] italic">Aguardando Chamado</p></div>}
             </div>
          </div>
        )}

        {activeTab === 'arquivos' && (
          currentFolder ? (
            <div className="space-y-5 animate-in slide-in-from-right-2">
               <div className="bg-white p-6 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
