                  <table className="w-full text-left">
                     <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase italic border-b tracking-widest">
                       <tr>
                         <th className="px-8 py-4">Nomenclatura</th>
                         <th className="px-8 py-4">Tamanho</th>
                         <th className="px-8 py-4">Tipo</th>
                         <th className="px-8 py-4">Anexado por</th>
                         <th className="px-8 py-4 text-center">Gestão</th>
                       </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100 text-[10px]">
                        {files.filter(f => f.category === currentFolder).map(f => (
                          <tr key={f.id} className="hover:bg-indigo-50/20 transition-all">
                             <td className="px-8 py-4 font-black text-slate-900 uppercase italic">{f.title}</td>
