import React, { useState, useEffect } from 'react';
// Correcting imports for Firebase modular SDK
import { onAuthStateChanged } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from './firebase';
import { UserRole, MainView, User, ProfessorSubView } from './types';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [activeProfessorSubView, setActiveProfessorSubView] = useState<ProfessorSubView>('cursos');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          const userRef = doc(db, 'users', user.uid);
          let userDoc = await getDoc(userRef);

          if (!userDoc.exists()) {
            const initialData = {
              nome: user.displayName || 'Novo Usuário',
              role: 'aluno',
              email: user.email,
              createdAt: new Date()
            };
            await setDoc(userRef, initialData);
            userDoc = await getDoc(userRef);
          }

          const userData = userDoc.data();
          const role = (userData?.role as UserRole) || 'aluno';

          setCurrentUser({
            uid: user.uid,
            email: user.email,
            displayName: userData?.nome || user.displayName || 'Usuário',
            role: role,
            photoURL: user.photoURL || undefined
          });
        } catch (error) {
          console.error("Erro ao buscar perfil RBAC:", error);
          setCurrentUser(null);
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const navigateToSubView = (main: MainView, sub?: ProfessorSubView) => {
    setActiveView(main);
    if (sub) setActiveProfessorSubView(sub);
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
          <p className="text-xs font-bold uppercase tracking-widest text-slate-500">Escola Bíblica EAD</p>
        </div>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView onNavigate={navigateToSubView} />;
      case 'professor': return <ProfessorView user={currentUser} activeSubView={activeProfessorSubView} />;
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView user={currentUser} />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView onNavigate={navigateToSubView} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans antialiased text-slate-900">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setIsMobileMenuOpen(false); }}
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <div className="flex-1 flex overflow-hidden">
        {(activeView === 'professor') && (
          <Sidebar 
            activeSub={activeProfessorSubView} 
            setActiveSub={setActiveProfessorSubView} 
          />
        )}

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8 h-full">
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive, Bell, ArrowRightLeft, Star, Heart,
  PlayCircle, PowerOff, UserCheck, ShieldAlert, FileSignature, Save, Megaphone, CheckCircle,
  Undo2, Calendar
} from 'lucide-react';

interface SecretariatViewProps {
  user: User;
}

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia';
type ChatFilter = 'ativos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [viewerFile, setViewerFile] = useState<any | null>(null);
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição de ensino teológico.');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, []);

  const selectedTicket = useMemo(() => tickets.find(t => t.id === selectedTicketId) || null, [tickets, selectedTicketId]);

  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const total = tickets.length;
    const concluidos = tickets.filter(t => t.status === 'Finalizado' || t.status === 'Arquivado').length;
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      documentos: files.length,
      satisfacao: total > 0 ? ((concluidos / total) * 100).toFixed(1) + '%' : '100%'
    };
  }, [tickets, files]);

  const filteredTickets = useMemo(() => {
    return tickets.filter(t => {
      const matchSearch = t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase());
      let matchDate = true;
      if (dateStart || dateEnd) {
        const created = t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000) : new Date();
        if (dateStart) matchDate = matchDate && created >= new Date(dateStart + "T00:00:00");
        if (dateEnd) matchDate = matchDate && created <= new Date(dateEnd + "T23:59:59");
      }
      return matchSearch && matchDate;
    });
  }, [tickets, searchTerm, dateStart, dateEnd]);

  const generateCleanDocumentHTML = (title: string, bodyText: string) => {
    return `
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="UTF-8">
          <style>
            body { font-family: sans-serif; padding: 40px; color: #1e293b; line-height: 1.6; background: white; }
            .header { text-align: center; border-bottom: 2px solid #4f46e5; padding-bottom: 20px; margin-bottom: 40px; }
            .content { font-size: 14px; text-align: justify; margin-bottom: 60px; }
            .footer { text-align: center; border-top: 1px solid #e2e8f0; padding-top: 20px; font-size: 12px; }
            h1 { color: #4f46e5; margin: 0; text-transform: uppercase; font-size: 24px; }
            p { margin: 10px 0; }
          </style>
        </head>
        <body>
          <div class="header">
            <h1>Escola Bíblica EAD</h1>
            <p>Secretaria Acadêmica Master</p>
          </div>
          <h2 style="text-align: center; font-size: 18px;">${title.toUpperCase()}</h2>
          <div class="content">
            ${bodyText}
            <p style="margin-top: 30px;">Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}</p>
          </div>
          <div class="footer">
            <p><strong>DIRETORIA DE ENSINO</strong></p>
            <p>Este documento possui validade jurídica digital.</p>
          </div>
        </body>
      </html>
    `;
  };

  const formatFileSize = (bytes: number) => {
    if (!bytes) return '---';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleSaveDeclaration = async () => {
    if (!selectedStudentForDecl) { alert("Selecione um aluno."); return; }
    const fileName = `DECLARACAO_${selectedStudentForDecl.displayName.replace(/\s/g, '_')}.pdf`;
    const body = `
      <p>Declaramos para os devidos fins que o aluno(a) <strong>${selectedStudentForDecl.displayName}</strong>, 
      regularmente matriculado sob o registro acadêmico <strong>${selectedStudentForDecl.academicId || 'PROVISÓRIO'}</strong>, 
      encontra-se em pleno gozo de seus direitos acadêmicos junto a esta instituição de ensino teológico.</p>
      <p>${declContent}</p>
    `;
    try {
      const html = generateCleanDocumentHTML('Declaração de Matrícula', body);
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Matrículas', content: `data:text/html;charset=utf-8,${encodeURIComponent(html)}`,
        uploader: 'Secretaria', createdAt: serverTimestamp(), size: html.length, type: 'application/pdf'
      });
      alert("Documento gerado!");
      setOpSubView('main');
    } catch (e) { alert("Erro ao salvar."); }
  };

  const handleTransfer = async () => {
    if (!transferData.studentId || !transferData.courseId) return;
    const student = students.find(s => s.uid === transferData.studentId);
    const course = courses.find(c => c.id === transferData.courseId);
    if (!student || !course) return;

    const fileName = `TERMO_TRANSFERENCIA_${student.displayName.replace(/\s/g, '_')}.pdf`;
    const body = `
      <p>Confirmamos a transferência do aluno <strong>${student.displayName}</strong>, matrícula <strong>${student.academicId || 'N/A'}</strong>, para o curso <strong>${course.nome}</strong>.</p>
      <p>A alteração curricular foi processada e o aluno encontra-se apto para as novas disciplinas.</p>
    `;
    try {
      const html = generateCleanDocumentHTML('Termo de Transferência', body);
      await updateDoc(doc(db, 'users', transferData.studentId), { cursoInicial: transferData.courseId });
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: fileName, category: 'Históricos', content: `data:text/html;charset=utf-8,${encodeURIComponent(html)}`,
        uploader: 'Secretaria', createdAt: serverTimestamp(), size: html.length, type: 'application/pdf'
      });
      alert("Transferência realizada!");
      setOpSubView('main');
    } catch (e) { alert("Erro na operação."); }
  };

  const handleApproveStudent = async (uid: string) => {
    if (confirm("Validar matrícula deste aluno?")) {
      await updateDoc(doc(db, 'users', uid), { status: 'ativo', validatedAt: serverTimestamp() });
      alert("Aluno validado!");
    }
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const newStatus = selectedTicket.status === 'Pendente' ? 'Em Atendimento' : 'Finalizado';
    if (newStatus === 'Finalizado' && !confirm("Encerrar atendimento?")) return;
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus, lastUpdate: serverTimestamp() });
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), {
        text: `Status alterado para ${newStatus}`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification'
    });
    if (newStatus === 'Finalizado') setSelectedTicketId(null);
  };

  const handleArchiveTicket = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: selectedTicket.status === 'Arquivado' ? 'Finalizado' : 'Arquivado' });
    setSelectedTicketId(null);
  };

  const handleSendMessage = async (file?: { name: string, content: string }) => {
    if (!selectedTicketId || (!chatMessage.trim() && !file)) return;
    const data: any = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    if (file) { data.fileUrl = file.content; data.fileName = file.name; }
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), data);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage || file?.name, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handleDirectDownload = (file: any) => {
    const link = document.createElement('a');
    link.href = file.content;
    link.download = file.title;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'validacao':
        const pendingStudents = students.filter(s => s.status === 'pendente' || !s.status || s.status === 'rascunho' || s.status === 'inativo');
        return (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-sm font-black text-slate-900 uppercase italic flex items-center gap-2"><UserCheck size={16} className="text-indigo-600" /> Validação de Matrículas</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-lg"><X size={16}/></button>
             </div>
             <div className="overflow-x-auto">
