                        <th className="px-6 py-3">ID Aluno</th>
                        <th className="px-6 py-3">Matrícula</th>
                        <th className="px-6 py-3">Solicitante</th>
                        <th className="px-6 py-3">E-mail</th>
                        <th className="px-6 py-3 text-center">Gestão</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pendingStudents.length === 0 ? (
                        <tr><td colSpan={5} className="p-10 text-center text-slate-300 font-black uppercase text-[10px]">Sem pendências de validação</td></tr>
                      ) : pendingStudents.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50 transition-colors">
                           <td className="px-6 py-3 font-mono text-[9px] text-slate-400">#{s.uid.slice(0,6)}</td>
                           <td className="px-6 py-3 font-black text-indigo-600">{s.academicId || 'Pendente'}</td>
                           <td className="px-6 py-3 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-6 py-3 font-bold text-slate-400">{s.email}</td>
                           <td className="px-6 py-3 text-center">
                              <button onClick={() => handleApproveStudent(s.uid)} className="px-4 py-1.5 bg-indigo-600 text-white rounded-lg text-[8px] font-black uppercase italic">Validar Acesso</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'inadimplencia':
        return (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-sm font-black text-slate-900 uppercase italic flex items-center gap-2"><ShieldAlert size={16} className="text-rose-500" /> Auditoria Financeira</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-lg"><X size={16}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase border-b">
                     <tr>
                        <th className="px-6 py-3">Nome do Aluno</th>
                        <th className="px-6 py-3">Situação</th>
                        <th className="px-6 py-3">Status Bloqueio</th>
                        <th className="px-6 py-3 text-center">Ações</th>
                     </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.map(s => (
                        <tr key={s.uid} className="hover:bg-rose-50/5 transition-colors">
                           <td className="px-6 py-3 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-6 py-3">
                              <span className={`px-3 py-1 rounded-full font-black uppercase italic text-[8px] border ${s.pendingDebts ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>
                                 {s.pendingDebts ? 'Inadimplente' : 'Regularizado'}
                              </span>
                           </td>
                           <td className="px-6 py-3">
