                                title="Notificar Pendência"
                              >
                                <Megaphone size={14}/>
                              </button>
                              <button 
                                onClick={async () => { 
                                  if(confirm(`Confirmar regularização do aluno ${s.displayName}?`)) {
                                    await updateDoc(doc(db, 'users', s.uid), { financialStatus: 'Regularizado', pendingDebts: false, status: 'ativo' });
                                    alert("Financeiro atualizado!");
                                  }
                                }} 
                                className="p-2 text-emerald-600 hover:scale-110 transition-transform bg-emerald-50 rounded-lg border border-emerald-100"
                                title="Regularizar Cadastro"
                              >
                                <CheckCircle size={14}/>
                              </button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-xl max-w-2xl mx-auto space-y-6 animate-in zoom-in-95">
             <div className="flex items-center gap-3 border-b pb-4"><div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg"><FileSignature size={20}/></div><h3 className="text-lg font-black text-slate-900 uppercase italic">Emissão de Declaração</h3></div>
             <div className="space-y-4">
                <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Selecione o Aluno...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-slate-50 p-6 rounded-2xl border-2 border-dashed border-slate-200 outline-none text-xs font-medium italic min-h-[120px] shadow-inner" />
