                   <button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Cancelar</button>
                   <button onClick={handleSaveDeclaration} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg italic flex items-center justify-center gap-2"><Save size={16}/> Gerar e Arquivar</button>
                </div>
