                       <div><h4 className="text-sm font-black text-slate-900 uppercase italic leading-none">{selectedTicket.user}</h4><span className="text-[8px] font-black text-indigo-600 uppercase mt-1 block italic">{selectedTicket.protocolo}</span></div>
                       <div className="flex gap-1.5">
