                            <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ACADÊMICA..." className="flex-1 bg-slate-50 border-none rounded-xl px-5 py-3 text-[9px] font-black uppercase tracking-widest shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                            <button onClick={() => handleSendMessage()} className="p-3 bg-slate-900 text-white rounded-full hover:bg-indigo-600 transition-all shadow-md active:scale-95"><Send size={20}/></button>
