             </div>
          </div>
        )}

        {activeTab === 'arquivos' && (
          currentFolder ? (
            <div className="space-y-5 animate-in slide-in-from-right-2">
               <div className="bg-white p-6 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
                  <div className="flex items-center gap-4">
                    <button onClick={() => setCurrentFolder(null)} className="p-2.5 bg-slate-50 rounded-xl text-slate-400 hover:bg-slate-900 hover:text-white border border-slate-100 shadow-sm transition-colors"><ChevronLeft size={20}/></button>
                    <div><h3 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter leading-none">{currentFolder}</h3><p className="text-[8px] font-black text-indigo-600 uppercase mt-0.5 italic tracking-widest">Documentos GED</p></div>
                  </div>
                  <button onClick={() => setIsUploadModalOpen(true)} className="bg-slate-900 text-white px-6 py-2.5 rounded-xl text-[9px] font-black uppercase flex items-center gap-2 shadow-lg hover:bg-indigo-600 transition-all italic tracking-widest"><Upload size={16}/> Novo Doc</button>
               </div>
               <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
                  <table className="w-full text-left">
                     <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase italic border-b tracking-widest">
                       <tr>
                         <th className="px-8 py-4">Nomenclatura</th>
                         <th className="px-8 py-4">Tamanho</th>
                         <th className="px-8 py-4">Tipo</th>
                         <th className="px-8 py-4">Anexado por</th>
