                           <td className="px-8 py-4"><span className={`px-4 py-1 rounded-full border font-black uppercase italic text-[7px] ${t.status === 'Finalizado' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : t.status === 'Arquivado' ? 'bg-slate-100 text-slate-500' : 'bg-amber-50 text-amber-600 border-amber-100'}`}>{t.status}</span></td>
                           <td className="px-8 py-4 text-center">
                              <div className="flex justify-center gap-2">
