              <div className="w-16 h-16 bg-indigo-50 rounded-xl flex items-center justify-center mx-auto mb-2 text-indigo-600 shadow-inner border border-indigo-100"><Upload size={32}/></div>
              <h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Repositório GED</h3>
              <div className="space-y-6 text-left">
                 <select value={uploadData.category} onChange={e => setUploadData({...uploadData, category: e.target.value})} className="w-full px-6 py-3 bg-slate-50 border-none rounded-xl font-black text-[9px] uppercase shadow-inner outline-none"><option>Matrículas</option><option>Financeiro</option><option>Históricos</option><option>Regulamentos</option><option>Certificados</option><option>Pautas</option></select>
                 <div className="border-2 border-dashed border-slate-100 rounded-2xl p-10 text-center hover:border-indigo-400 transition-all relative group shadow-inner bg-slate-50/50">
                    <input type="file" onChange={(e) => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=async(ev)=>{ await addDoc(collection(db, 'secretaria_arquivos'), {title:f.name, category:uploadData.category, content:ev.target?.result, uploader:user?.displayName || 'Secretaria', createdAt:serverTimestamp(), size:f.size, type:f.type}); setIsUploadModalOpen(false); }; r.readAsDataURL(f); } }} className="absolute inset-0 opacity-0 cursor-pointer" accept=".pdf,.png,.jpg,.jpeg,.webp" />
                    <FileText size={40} className="text-slate-200 mx-auto mb-2 group-hover:text-indigo-400 transition-colors" /><p className="text-[9px] font-black uppercase text-slate-400 italic">Anexar Documento</p>
                 </div>
              </div>
              <button onClick={() => setIsUploadModalOpen(false)} className="w-full py-4 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic hover:bg-rose-50 transition-all">Cancelar</button>
           </div>
