};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, CheckCircle2, MessageSquare, 
  Search, Plus, X, FolderOpen, FileText, Download, Upload, 
  Send, User as UserIcon, MoreVertical, Filter, Paperclip, Check, ChevronRight,
  Archive, Trash2, Printer, ShieldCheck, History, FileUp, Eye,
  FileBadge, Database, Activity, RefreshCw, FileSpreadsheet, Ban, Settings, HardDrive,
  ChevronLeft, MoreHorizontal, FileArchive, Bell, ArrowRightLeft, Star, Heart,
  PlayCircle, PowerOff, UserCheck, ShieldAlert, FileSignature, Save, Megaphone, CheckCircle,
  Undo2, Calendar, Fingerprint, PenTool
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

const loadJSPDF = () => {
  return new Promise((resolve) => {
    if ((window as any).jspdf) return resolve((window as any).jspdf);
    const script = document.createElement('script');
    script.src = "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js";
    script.onload = () => resolve((window as any).jspdf);
    document.head.appendChild(script);
  });
};

interface SecretariatViewProps {
  user: User;
}

type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia' | 'assinatura';
type ChatFilter = 'ativos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('ativos');

  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateStart, setDateStart] = useState('');
  const [dateEnd, setDateEnd] = useState('');

  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [isNewProtocolModalOpen, setIsNewProtocolModalOpen] = useState(false);
  const [isUploadModalOpen, setIsUploadModalOpen] = useState(false);
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [dirSignature, setDirSignature] = useState<string | null>(null);

  const [newProtocol, setNewProtocol] = useState({ user: '', subject: 'Acadêmico', priority: 'Média', description: '' });
  const [uploadData, setUploadData] = useState({ title: '', category: 'Matrículas' });
  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição de ensino teológico.');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubTickets = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), (snap) => {
      setTickets(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubFiles = onSnapshot(query(collection(db, 'secretaria_arquivos'), orderBy('createdAt', 'desc')), (snap) => {
      setFiles(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setStudents(snap.docs.map(d => ({ uid: d.id, ...d.data() })));
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const fetchSignatures = async () => {
      const secDoc = await getDoc(doc(db, 'users', user.uid));
      if (secDoc.exists()) setSecSignature(secDoc.data().signatureUrl || null);

      const dirQuery = query(collection(db, 'users'), where('role', '==', 'diretor'));
      const dirSnap = await getDocs(dirQuery);
      if (!dirSnap.empty) setDirSignature(dirSnap.docs[0].data().signatureUrl || null);
    };

    fetchSignatures();
    return () => { unsubTickets(); unsubFiles(); unsubStudents(); unsubCourses(); };
  }, [user.uid]);

  const selectedTicket = useMemo(() => tickets.find(t => t.id === selectedTicketId) || null, [tickets, selectedTicketId]);

  useEffect(() => {
    if (!selectedTicketId) { setChatHistory([]); return; }
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const total = tickets.length;
    const concluidos = tickets.filter(t => t.status === 'Finalizado' || t.status === 'Arquivado').length;
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      documentos: files.length,
      satisfacao: total > 0 ? ((concluidos / total) * 100).toFixed(1) + '%' : '100%'
    };
  }, [tickets, files]);

  const filteredTickets = useMemo(() => {
    return tickets.filter(t => {
      const matchSearch = t.user?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase());
      let matchDate = true;
      if (dateStart || dateEnd) {
        const created = t.createdAt?.seconds ? new Date(t.createdAt.seconds * 1000) : new Date();
        if (dateStart) matchDate = matchDate && created >= new Date(dateStart + "T00:00:00");
        if (dateEnd) matchDate = matchDate && created <= new Date(dateEnd + "T23:59:59");
      }
      return matchSearch && matchDate;
    });
  }, [tickets, searchTerm, dateStart, dateEnd]);

  const formatFileSize = (bytes: number) => {
    if (!bytes) return '---';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const handleOpenInNewTab = (content: string) => {
    try {
      if (content.startsWith('data:application/pdf;base64,')) {
        const base64Str = content.split(',')[1];
        const binaryString = window.atob(base64Str);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
          bytes[i] = binaryString.charCodeAt(i);
        }
        const blob = new Blob([bytes], { type: 'application/pdf' });
        const blobUrl = URL.createObjectURL(blob);
        window.open(blobUrl, '_blank');
      } else if (content.startsWith('data:application/pdf') || content.startsWith('data:image')) {
        const parts = content.split(';base64,');
        const contentType = parts[0].split(':')[1];
        const raw = window.atob(parts[1]);
        const uInt8Array = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; ++i) { uInt8Array[i] = raw.charCodeAt(i); }
        const blob = new Blob([uInt8Array], { type: contentType });
        window.open(URL.createObjectURL(blob), '_blank');
      } else {
        window.open(content, '_blank');
      }
    } catch (e) {
      console.error("Erro no visualizador:", e);
      window.open(content, '_blank');
    }
  };

  const generateVerificationCode = () => {
    return Math.random().toString(36).substring(2, 10).toUpperCase() + '-' + Date.now().toString(36).toUpperCase();
  };

  const generateProfessionalPDF = async (title: string, bodyText: string, verificationCode: string) => {
    const jspdf: any = await loadJSPDF();
    const doc = new jspdf.jsPDF();

    // 1. Marca d'água elegante
    doc.setTextColor(245, 245, 245);
    doc.setFontSize(60);
    doc.text("EB-EAD", 105, 150, { align: 'center', angle: 45 });

    // 2. Bordas e Detalhes Clean
    doc.setDrawColor(230, 230, 230);
    doc.rect(5, 5, 200, 287);
    doc.setDrawColor(79, 70, 229);
    doc.line(20, 45, 190, 45); // Linha superior sob header

    // 3. Cabeçalho Institucional
    doc.setTextColor(79, 70, 229);
    doc.setFontSize(26);
    doc.setFont("helvetica", "bold");
    doc.text("Escola Bíblica EAD", 105, 25, { align: 'center' });

    doc.setTextColor(100, 116, 139);
    doc.setFontSize(9);
    doc.setFont("helvetica", "normal");
    doc.text("SECRETARIA ACADÊMICA CENTRAL EB-EAD", 105, 33, { align: 'center' });
    doc.text("CENTRO DE EXCELÊNCIA EM EDUCAÇÃO TEOLÓGICA", 105, 38, { align: 'center' });

    // 4. Conteúdo do Documento
    doc.setTextColor(30, 41, 59);
    doc.setFontSize(18);
    doc.setFont("helvetica", "bold");
    doc.text(title, 105, 65, { align: 'center' });

    doc.setFontSize(11);
    doc.setFont("helvetica", "normal");
    const splitBody = doc.splitTextToSize(bodyText, 170);
    doc.text(splitBody, 20, 85);

    // 5. Bloco de Assinaturas (Se houver)
    const startSignY = 210;
    doc.setDrawColor(200, 200, 200);

    // Diretor
    if (dirSignature) {
      doc.addImage(dirSignature, 'PNG', 35, startSignY - 20, 40, 15);
      doc.line(25, startSignY, 85, startSignY);
      doc.setFontSize(8);
      doc.setFont("helvetica", "bold");
      doc.text("DIRETORIA DE ENSINO", 55, startSignY + 5, { align: 'center' });
    }

    // Secretário
    if (secSignature) {
      doc.addImage(secSignature, 'PNG', 135, startSignY - 20, 40, 15);
      doc.line(125, startSignY, 185, startSignY);
      doc.setFontSize(8);
      doc.setFont("helvetica", "bold");
      doc.text("SECRETARIA ACADÊMICA", 155, startSignY + 5, { align: 'center' });
    }

    // 6. Rodapé de Validação Jurídica
    doc.setFillColor(248, 250, 252);
    doc.rect(10, 260, 190, 25, 'F');

    doc.setTextColor(79, 70, 229);
    doc.setFontSize(8);
    doc.setFont("helvetica", "bold");
    doc.text("ESTE DOCUMENTO POSSUI VALIDADE JURÍDICA DIGITAL", 105, 268, { align: 'center' });

    doc.setTextColor(100, 116, 139);
    doc.setFont("helvetica", "normal");
    doc.text("Documento assinado digitalmente conforme diretrizes do sistema central de gestão EB-EAD.", 105, 273, { align: 'center' });
    doc.text(`CÓDIGO DE VERIFICAÇÃO: ${verificationCode}`, 105, 278, { align: 'center' });
    doc.text(`Data de Emissão: ${new Date().toLocaleDateString('pt-BR')} às ${new Date().toLocaleTimeString('pt-BR')}`, 105, 282, { align: 'center' });

    return doc.output('datauristring');
  };

  const handleSaveDeclaration = async () => {
    if (!selectedStudentForDecl) { alert("Selecione um aluno."); return; }
    const vCode = generateVerificationCode();
    const fileName = `DECLARACAO_${selectedStudentForDecl.displayName.replace(/\s/g, '_')}.pdf`;
    const body = `Declaramos para os devidos fins que o aluno(a) ${selectedStudentForDecl.displayName}, regularmente matriculado sob o registro acadêmico ${selectedStudentForDecl.academicId || 'PROVISÓRIO'}, encontra-se em pleno gozo de seus direitos acadêmicos junto a esta instituição de ensino teológico.\n\n${declContent}`;

    try {
      const pdfDataUri = await generateProfessionalPDF('DECLARAÇÃO DE MATRÍCULA', body, vCode);
      await addDoc(collection(db, 'secretaria_arquivos'), { 
        title: fileName, 
        category: 'Matrículas', 
        content: pdfDataUri, 
        uploader: user.displayName, 
        createdAt: serverTimestamp(), 
        size: pdfDataUri.length, 
        type: 'application/pdf',
        verificationCode: vCode
      });
      alert("Documento oficial gerado com sucesso!");
      setOpSubView('main');
    } catch (e) { alert("Erro ao gerar PDF."); }
  };

  const handleTransfer = async () => {
    if (!transferData.studentId || !transferData.courseId) { alert("Selecione o aluno e o curso."); return; }
    const student = students.find(s => s.uid === transferData.studentId);
    const course = courses.find(c => c.id === transferData.courseId);
    if (!student || !course) return;
    const vCode = generateVerificationCode();
    try {
      const fileName = `TERMO_TRANSFERENCIA_${student.displayName.replace(/\s/g, '_')}.pdf`;
      const body = `Confirmamos através deste termo a transferência definitiva do aluno ${student.displayName}, matrícula ${student.academicId || 'N/A'}, para a disciplina de ${course.nome}.\n\nA alteração curricular foi processada eletronicamente e o aluno encontra-se apto para as novas responsabilidades acadêmicas conforme regimento interno EB-EAD.`;

      const pdfDataUri = await generateProfessionalPDF('TERMO DE TRANSFERÊNCIA MATRIZ', body, vCode);
      await updateDoc(doc(db, 'users', transferData.studentId), { cursoInicial: transferData.courseId });
      await addDoc(collection(db, 'secretaria_arquivos'), { 
        title: fileName, 
        category: 'Históricos', 
        content: pdfDataUri, 
        uploader: user.displayName, 
        createdAt: serverTimestamp(), 
        size: pdfDataUri.length, 
        type: 'application/pdf',
        verificationCode: vCode
      });
      alert("Transferência oficializada!");
      setOpSubView('main');
    } catch (e) { alert("Erro na operação."); }
  };

  const handleToggleAttendance = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    const newStatus = selectedTicket.status === 'Pendente' ? 'Em Atendimento' : 'Finalizado';
    if (newStatus === 'Finalizado' && !confirm("Encerrar atendimento?")) return;
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: newStatus, lastUpdate: serverTimestamp() });
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), { text: `Status alterado para ${newStatus}`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification' });
    if (newStatus === 'Finalizado') setSelectedTicketId(null);
  };

  const handleReopenTicket = async () => {
    if (!selectedTicketId || !selectedTicket) return;
    await updateDoc(doc(db, 'tickets', selectedTicketId), { status: 'Em Atendimento', lastUpdate: serverTimestamp() });
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), { text: `Chamado reaberto pela Secretaria Master.`, sender: 'Sistema', timestamp: serverTimestamp(), type: 'notification' });
  };

  const renderOperationalView = () => {
    switch(opSubView) {
      case 'assinatura':
        return (
          <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8 animate-in zoom-in-95 text-center">
             <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto mb-2 text-indigo-600 shadow-inner border border-indigo-100"><PenTool size={36}/></div>
             <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Validação Digital do Secretário</h3>
             <p className="text-slate-400 text-[10px] font-medium uppercase tracking-widest italic max-w-sm mx-auto">Sua assinatura será vinculada automaticamente a todos os documentos oficiais da EB-EAD.</p>
             <div className="bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100 flex flex-col items-center justify-center min-h-[200px] shadow-inner">
                {secSignature ? (
                  <img src={secSignature} alt="Sua Assinatura" className="h-28 object-contain drop-shadow-md grayscale hover:grayscale-0 transition-all cursor-pointer" title="Visualização de Segurança" />
                ) : (
                  <div className="text-center opacity-30"><Fingerprint size={60} className="mx-auto mb-4" /><p className="text-[9px] font-black uppercase tracking-[0.4em]">Biometria Ausente</p></div>
                )}
             </div>
             <div className="flex gap-3">
                <button onClick={() => setOpSubView('main')} className="flex-1 py-4.5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Voltar</button>
                <button onClick={() => setIsSignModalOpen(true)} className="flex-1 py-4.5 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all italic tracking-widest">{secSignature ? 'Atualizar Assinatura' : 'Criar Identidade Digital'}</button>
             </div>
          </div>
        );
      case 'validacao':
        const pendingStudents = students.filter(s => s.status === 'pendente' || !s.status || s.status === 'rascunho' || s.status === 'inativo');
        return (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-sm font-black text-slate-900 uppercase italic flex items-center gap-2"><UserCheck size={16} className="text-indigo-600" /> Validação de Matrículas</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-lg transition-colors"><X size={16}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase italic border-b">
                     <tr><th className="px-6 py-3">ID Aluno</th><th className="px-6 py-3">Matrícula</th><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">E-mail</th><th className="px-6 py-3 text-center">Gestão</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {pendingStudents.length === 0 ? (
                        <tr><td colSpan={5} className="p-10 text-center text-slate-300 font-black uppercase text-[10px]">Sem pendências</td></tr>
                      ) : pendingStudents.map(s => (
                        <tr key={s.uid} className="hover:bg-indigo-50 transition-colors">
                           <td className="px-6 py-3 font-mono text-[9px] text-slate-400">#{s.uid.slice(0,6)}</td>
                           <td className="px-6 py-3 font-black text-indigo-600">{s.academicId || 'S/N'}</td>
                           <td className="px-6 py-3 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-6 py-3 font-bold text-slate-400">{s.email}</td>
                           <td className="px-6 py-3 text-center">
                              <button onClick={() => { if(confirm('Validar matrícula?')) updateDoc(doc(db, 'users', s.uid), { status: 'ativo' }); }} className="px-4 py-1.5 bg-indigo-600 text-white rounded-lg text-[8px] font-black uppercase italic">Validar Acesso</button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'inadimplencia':
        return (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden animate-in fade-in">
             <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50/30">
                <h3 className="text-sm font-black text-slate-900 uppercase italic flex items-center gap-2"><ShieldAlert size={16} className="text-rose-500" /> Auditoria Financeira</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-lg"><X size={16}/></button>
             </div>
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                   <thead className="bg-slate-50 text-[8px] font-black text-slate-400 uppercase border-b">
                     <tr><th className="px-6 py-3">Nome do Aluno</th><th className="px-6 py-3">Situação</th><th className="px-6 py-3">Status Bloqueio</th><th className="px-6 py-3 text-center">Ações</th></tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100 text-[10px]">
                      {students.map(s => (
                        <tr key={s.uid} className="hover:bg-rose-50/5 transition-colors">
                           <td className="px-6 py-3 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                           <td className="px-6 py-3"><span className={`px-3 py-1 rounded-full font-black uppercase italic text-[8px] border ${s.pendingDebts ? 'bg-rose-50 text-rose-600 border-rose-100' : 'bg-emerald-50 text-emerald-600 border-emerald-100'}`}>{s.pendingDebts ? 'Inadimplente' : 'Regularizado'}</span></td>
                           <td className="px-6 py-3"><span className={`px-3 py-1 rounded-full font-black uppercase italic text-[8px] border ${s.status === 'inativo' ? 'bg-slate-100 text-slate-500' : 'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>{s.status === 'inativo' ? 'Bloqueado' : 'Liberado'}</span></td>
                           <td className="px-6 py-3 flex justify-center gap-2">
                              <button onClick={() => alert(`Cobrança enviada para ${s.email}`)} className="p-2 text-amber-600 hover:scale-110 transition-transform bg-amber-50 rounded-lg"><Megaphone size={14}/></button>
                              <button onClick={async () => { if(confirm(`Regularizar ${s.displayName}?`)) { await updateDoc(doc(db, 'users', s.uid), { pendingDebts: false, status: 'ativo' }); alert("Financeiro atualizado!"); } }} className="p-2 text-emerald-600 hover:scale-110 transition-transform bg-emerald-50 rounded-lg"><CheckCircle size={14}/></button>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-xl max-w-2xl mx-auto space-y-6 animate-in zoom-in-95">
             <div className="flex items-center gap-3 border-b pb-4"><div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg"><FileSignature size={20}/></div><h3 className="text-lg font-black text-slate-900 uppercase italic">Emissão de Declaração Oficial</h3></div>
             <div className="space-y-4">
                <select onChange={(e) => setSelectedStudentForDecl(students.find(s => s.uid === e.target.value))} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Selecione o Aluno...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <textarea value={declContent} onChange={e => setDeclContent(e.target.value)} className="w-full bg-slate-50 p-6 rounded-2xl border-2 border-dashed border-slate-200 outline-none text-xs font-medium italic min-h-[120px] shadow-inner" />
                <div className="flex gap-3">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Cancelar</button>
                   <button onClick={handleSaveDeclaration} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg italic flex items-center justify-center gap-2"><Save size={16}/> Gerar e Assinar</button>
                </div>
             </div>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm max-w-xl mx-auto space-y-6 animate-in fade-in">
             <div className="flex items-center gap-3 border-b pb-4"><div className="p-3 bg-amber-50 text-amber-600 rounded-xl"><ArrowRightLeft size={20}/></div><h3 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter">Transferência de Matriz</h3></div>
             <div className="space-y-4">
                <select value={transferData.studentId} onChange={e => setTransferData({...transferData, studentId: e.target.value})} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Aluno Solicitante...</option>
                   {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                </select>
                <select value={transferData.courseId} onChange={e => setTransferData({...transferData, courseId: e.target.value})} className="w-full px-5 py-3 bg-slate-50 rounded-xl font-black text-[10px] shadow-inner border-none outline-none">
                   <option value="">Disciplina de Destino...</option>
                   {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                </select>
                <div className="flex gap-3">
                   <button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl text-[9px] font-black uppercase italic">Voltar</button>
                   <button onClick={handleTransfer} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl text-[9px] font-black uppercase shadow-lg italic">Processar Transferência</button>
                </div>
             </div>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4 animate-in zoom-in-95">
             {[
               { id: 'declaracao', title: 'Declarações PDF', icon: <FileText size={20}/>, color: 'text-indigo-600', bg: 'bg-indigo-50' },
               { id: 'validacao', title: 'Validação Alunos', icon: <UserCheck size={20}/>, color: 'text-emerald-600', bg: 'bg-emerald-50' },
               { id: 'transferencia', title: 'Transferências', icon: <ArrowRightLeft size={20}/>, color: 'text-amber-600', bg: 'bg-amber-50' },
               { id: 'inadimplencia', title: 'Auditoria Finan.', icon: <ShieldAlert size={20}/>, color: 'text-rose-600', bg: 'bg-rose-50' },
               { id: 'assinatura', title: 'Minha Assinatura', icon: <PenTool size={20}/>, color: 'text-indigo-600', bg: 'bg-slate-900 text-white' }
             ].map(op => (
               <button key={op.id} onClick={() => setOpSubView(op.id as OperationalSubView)} className={`p-6 rounded-2xl border border-slate-200 hover:border-indigo-400 transition-all flex flex-col items-center shadow-sm group ${op.id === 'assinatura' ? 'bg-slate-900' : 'bg-white'}`}>
                  <div className={`w-12 h-12 rounded-xl flex items-center justify-center mb-4 group-hover:scale-110 transition-transform shadow-inner ${op.id === 'assinatura' ? 'bg-white/10 text-white' : op.bg + ' ' + op.color}`}>{op.icon}</div>
                  <h4 className={`text-[9px] font-black uppercase italic tracking-tight ${op.id === 'assinatura' ? 'text-white' : 'text-slate-900'}`}>{op.title}</h4>
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 pb-10 animate-in fade-in h-full">
      <header className="flex justify-between items-center no-print">
        <div><h1 className="text-xl font-black text-slate-900 uppercase italic leading-none">Secretaria Master</h1><p className="text-slate-500 text-[10px] italic font-medium mt-1 uppercase tracking-widest">Gestão Acadêmica Central EB-EAD</p></div>
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
          {(['atendimento', 'chat', 'arquivos', 'operacional'] as SecretariatTab[]).map(tab => (
            <button key={tab} onClick={() => {setActiveTab(tab); setSelectedTicketId(null); setOpSubView('main');}} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'}`}>{tab}</button>
          ))}
        </div>
      </header>

      {(activeTab === 'atendimento' || activeTab === 'chat') && (
        <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col xl:flex-row items-center gap-4 no-print animate-in slide-in-from-top-1">
           <div className="relative flex-[2] w-full">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={16}/>
              <input type="text" placeholder="BUSCAR ALUNO OU PROTOCOLO..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full pl-12 pr-6 py-3.5 bg-slate-50 border-none rounded-xl text-[9px] font-black uppercase outline-none shadow-inner tracking-widest" />
           </div>
           <div className="flex items-center gap-3 w-full xl:w-auto bg-slate-50 p-1.5 rounded-xl border border-slate-100 flex-1">
              <input type="date" value={dateStart} onChange={e => setDateStart(e.target.value)} className="flex-1 bg-transparent border-none text-[9px] font-black outline-none px-2" />
              <span className="text-slate-300 font-black">-</span>
              <input type="date" value={dateEnd} onChange={e => setDateEnd(e.target.value)} className="flex-1 bg-transparent border-none text-[9px] font-black outline-none px-2" />
              <button onClick={() => {setSearchTerm(''); setDateStart(''); setDateEnd('');}} className="p-2 bg-white text-slate-400 rounded-lg hover:text-rose-50 shadow-sm transition-colors"><RefreshCw size={14}/></button>
           </div>
        </div>
      )}

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 no-print">
         {[
           { label: 'Pendentes', value: stats.pendentes, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={16}/> },
           { label: 'Em Atendimento', value: stats.emAtendimento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <AlertCircle size={16}/> },
           { label: 'Eficiência', value: stats.satisfacao, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <Star size={16}/> },
           { label: 'GED Acervo', value: stats.documentos, color: 'text-slate-600', bg: 'bg-slate-50', icon: <FolderOpen size={16}/> }
         ].map((s, i) => (
           <div key={i} className={`${s.bg} p-4 rounded-2xl border border-slate-200 flex items-center gap-4 shadow-sm`}>
              <div className="p-2.5 bg-white rounded-lg text-slate-400 shadow-sm border border-slate-100 shrink-0">{s.icon}</div>
              <div><p className="text-[7px] font-black uppercase text-slate-400 mb-0.5 italic">{s.label}</p><p className="text-xl font-black text-slate-900 leading-none tabular-nums">{s.value}</p></div>
           </div>
         ))}
      </div>

      <main className="flex-1 min-h-[400px]">
        {activeTab === 'chat' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 h-[600px]">
