                                <button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-3 bg-indigo-50 text-indigo-600 hover:bg-indigo-600 hover:text-white rounded-xl transition-all shadow-sm" title="Ir para o Chat"><MessageSquare size={18}/></button>
