import React, { useState, useEffect } from 'react';
import { doc, updateDoc, getDoc, collection, onSnapshot, query, where } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, CreditCard, ChevronRight, PenTool, 
  FileBadge, Save, Palette, Globe, Fingerprint, Lock, 
  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [userSignature, setUserSignature] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const [staff, setStaff] = useState<any[]>([]);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    defaultText: 'Certificamos que o aluno(a) concluiu com êxito os requisitos acadêmicos da disciplina.',
    issuerTitle: 'Diretor Acadêmico'
  });

  const [securityConfig, setSecurityConfig] = useState({
    twoFactorAuth: false,
    sessionTimeout: 60,
    passwordComplexity: 'high',
    loginAlerts: true
  });

  useEffect(() => {
    const fetchSettings = async () => {
      if (auth.currentUser) {
        const userDoc = await getDoc(doc(db, 'users', auth.currentUser.uid));
        if (userDoc.exists()) {
          const data = userDoc.data();
          setUserSignature(data.signatureUrl || null);
          if (data.schoolConfig) setSchoolConfig(data.schoolConfig);
          if (data.securityConfig) setSecurityConfig(data.securityConfig);
        }
        setLoading(false);
