                    <div className="space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Contato Direto</p><p className="text-sm font-bold">{selectedMember.telefone || '---'}</p></div>
                    <div className="col-span-full space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Formação Acadêmica</p><p className="text-sm font-bold leading-relaxed italic">{selectedMember.formacao || 'Sem registro de formação curricular.'}</p></div>
                    <div className="col-span-2 space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Níveis de Acesso Habilitados</p><div className="flex flex-wrap gap-2 mt-2">{selectedMember.permissions?.map((p:any) => <span key={p} className="px-3 py-1 bg-slate-900 text-white rounded-lg text-[8px] font-black uppercase tracking-widest italic">{p}</span>)}</div></div>
                 </div>
                 <div className="pt-12 border-t border-slate-100 flex gap-4">
                    {selectedMember.signatureUrl ? (
                      <div className="flex-1 bg-slate-50 rounded-[2rem] p-6 flex items-center justify-between border border-slate-100 shadow-inner">
                         <div className="space-y-1"><p className="text-[7px] font-black uppercase text-slate-400 italic">Identidade Digital Validada</p><p className="text-[9px] font-bold text-emerald-600">CERTIFICADO EMISSOR ATIVO</p></div>
                         <img src={selectedMember.signatureUrl} className="h-10 grayscale hover:grayscale-0 transition-all opacity-60" />
                      </div>
                    ) : (
                      <button onClick={() => { setSigningUserId(selectedMember.id); setIsSignModalOpen(true); setIsViewModalOpen(false); }} className="flex-1 bg-amber-50 text-amber-600 rounded-[2rem] p-6 text-[10px] font-black uppercase italic border border-amber-100 shadow-sm hover:bg-amber-100 transition-all flex items-center justify-center gap-3"><PenTool size={18}/> Coletar Assinatura Digital</button>
                    )}
