};

export default SettingsView;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc, writeBatch
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, CreditCard, ChevronRight, PenTool, 
  FileBadge, Save, Palette, Globe, Fingerprint, Lock, 
  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck,
  History, ShieldCheck, Zap, Briefcase, Calendar, Download,
  CloudLightning, HardDrive, Key, AlertTriangle, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Equipe States
  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);
  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    formacao: '', cargo: 'professor' as RoleClassification,
    fotoUrl: '', status: 'ativo', availability: 'disponivel',
    acessos: ['dashboard', 'professor', 'alunos', 'secretaria']
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);
  const [activeUsersCount, setActiveUsersCount] = useState(0);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência para o Reino',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    autoEnrollment: false,
    publicCatalog: true
  });

  const [securityConfig, setSecurityConfig] = useState({
    twoFactorAuth: true,
    sessionTimeout: 60,
    passwordComplexity: 'high',
    loginAlerts: true,
    rbacRules: {
      diretor: ['*'],
      vice_diretor: ['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'],
      secretaria: ['dashboard', 'alunos', 'secretaria', 'configuracoes'],
      coordenador: ['dashboard', 'professor', 'alunos', 'secretaria'],
      professor: ['dashboard', 'professor', 'alunos', 'secretaria'],
      apoio: ['secretaria']
    }
  });

  const [financialConfig, setFinancialConfig] = useState({
    rematricula: '150,00',
    diplomacao: '80,00',
    gatewayKey: 'pk_live_********************',
    currency: 'BRL'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(data.schoolConfig);
        if (data.securityConfig) setSecurityConfig(data.securityConfig);
        if (data.financialConfig) setFinancialConfig(data.financialConfig);
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(5)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio']), orderBy('createdAt', 'asc')), (snap) => {
      setStaff(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setActiveUsersCount(snap.size + Math.floor(Math.random() * 3));
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const addGovernanceLog = async (action: string) => {
    await addDoc(collection(db, 'system_logs'), {
      action,
      user: auth.currentUser?.displayName || 'Diretoria',
      timestamp: serverTimestamp(),
      type: 'config_update'
    });
  };

  // Implement handleSaveAll to persist system configurations
  const handleSaveAll = async () => {
    try {
      await setDoc(doc(db, 'system_settings', 'main_config'), {
        schoolConfig,
        securityConfig,
        financialConfig,
        updatedAt: serverTimestamp()
      }, { merge: true });
      await addGovernanceLog('Configurações globais do sistema atualizadas');
      alert("Configurações salvas com sucesso!");
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar configurações.");
    }
  };

  // Implement handleSaveSignature to persist signatures for staff members
  const handleSaveSignature = async (base64: string) => {
    if (!signingUserId) return;
    try {
      await updateDoc(doc(db, 'users', signingUserId), {
        signatureUrl: base64,
        updatedAt: serverTimestamp()
      });
      await addGovernanceLog(`Assinatura digital coletada para o membro da equipe.`);
      setIsSignModalOpen(false);
      setSigningUserId(null);
      alert("Assinatura digital vinculada com sucesso!");
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar assinatura.");
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        endereco: memberForm.endereco,
        formacao: memberForm.formacao,
        role: memberForm.cargo,
        photoURL: memberForm.fotoUrl,
        status: memberForm.status,
        availability: memberForm.availability,
        permissions: memberForm.acessos,
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
        await addGovernanceLog(`Perfil de equipe atualizado: ${memberForm.nome}`);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
        await addGovernanceLog(`Novo membro registrado na equipe: ${memberForm.nome}`);
      }
      setIsMemberModalOpen(false);
      setSelectedMember(null);
    } catch (err) {
      alert("Erro ao processar cadastro.");
    }
  };

  const handleDeleteMember = async (id: string, nome: string) => {
    if (confirm(`Remover ${nome} da equipe permanentemente?`)) {
      await deleteDoc(doc(db, 'users', id));
      await addGovernanceLog(`Membro removido da equipe: ${nome}`);
    }
  };

  const handleCycleAcademicYear = async () => {
    if (confirm(`Iniciar Ciclo ${Number(schoolConfig.academicYear) + 1}?`)) {
      const next = (Number(schoolConfig.academicYear) + 1).toString();
      await updateDoc(doc(db, 'system_settings', 'main_config'), { "schoolConfig.academicYear": next });
      await addGovernanceLog(`Virada de Ciclo Acadêmico: ${next}`);
    }
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Console de Configurações</h1>
