                    <button type="submit" className="flex-1 py-6 bg-slate-900 text-white rounded-3xl text-[11px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic tracking-[0.2em]">{selectedMember ? 'Salvar Alterações Ficha' : 'Concluir Credenciamento Equipe'}</button>
