    diplomacao: '80,00',
    gatewayKey: 'pk_live_********************',
    currency: 'BRL'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(data.schoolConfig);
        if (data.securityConfig) setSecurityConfig(data.securityConfig);
        if (data.financialConfig) setFinancialConfig(data.financialConfig);
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(5)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio'])), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      data.sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));
      setStaff(data);
      setActiveUsersCount(snap.size + Math.floor(Math.random() * 3));
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setMemberForm({ ...memberForm, fotoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

