                         <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                      </div>
                      <p className="text-[9px] font-black uppercase text-slate-400 italic text-center max-w-[200px]">Clique no box acima para selecionar uma foto do seu dispositivo.</p>
                   </div>
                   <div className="md:col-span-8 grid grid-cols-1 sm:grid-cols-2 gap-6">
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Nome Completo</label><input required value={memberForm.nome} onChange={e => setMemberForm({...memberForm, nome: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">E-mail Corporativo</label><input required type="email" value={memberForm.email} onChange={e => setMemberForm({...memberForm, email: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Documento (CPF/RG)</label><input required value={memberForm.documento} onChange={e => setMemberForm({...memberForm, documento: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-mono text-xs" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Telefone Celular</label><input required value={memberForm.telefone} onChange={e => setMemberForm({...memberForm, telefone: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs" /></div>
                   </div>
                 </div>
               </div>

               {/* SEÇÃO 2: ENDEREÇO RESIDENCIAL COMPLETO */}
               <div className="space-y-12">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">02</span><h3 className="text-xl font-black uppercase tracking-tight italic">Residência e Domicílio</h3></div>
                 <div className="grid grid-cols-1 md:grid-cols-12 gap-6">
                    <div className="md:col-span-8 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Logradouro / Rua</label><input value={memberForm.endereco.rua} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, rua: e.target.value}})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Número / Ap</label><input value={memberForm.endereco.numero} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, numero: e.target.value}})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Bairro</label><input value={memberForm.endereco.bairro} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, bairro: e.target.value}})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Cidade</label><input value={memberForm.endereco.cidade} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, cidade: e.target.value}})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-2 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">UF</label><input value={memberForm.endereco.uf} maxLength={2} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, uf: e.target.value}})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs shadow-inner uppercase text-center" /></div>
                 </div>
               </div>

               {/* SEÇÃO 3: CARGO E CREDENCIAIS DE ACESSO */}
               <div className="space-y-12">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">03</span><h3 className="text-xl font-black uppercase tracking-tight italic">Hierarquia e Credenciais</h3></div>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                    <div className="space-y-6">
                      <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Função Acadêmica</label>
                        <select value={memberForm.cargo} onChange={e => setMemberForm({...memberForm, cargo: e.target.value as any})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner">
                           <option value="diretor">Diretor (Master)</option>
                           <option value="vice_diretor">Vice-Diretor (Suplente)</option>
                           <option value="coordenador">Coordenador (Supervisor)</option>
                           <option value="secretaria">Secretário(a) (Gestão)</option>
                           <option value="professor">Professor (Docência)</option>
                           <option value="apoio">Equipe de Apoio (Atendimento)</option>
                        </select>
                      </div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Formação Curricular</label><textarea value={memberForm.formacao} onChange={e => setMemberForm({...memberForm, formacao: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-[2rem] h-28 font-medium text-xs shadow-inner italic" placeholder="Titulacões, especializações..." /></div>
                    </div>
                    <div className="space-y-6 p-8 bg-indigo-50/30 rounded-[3rem] border border-indigo-100 shadow-inner">
                      <div className="flex items-center gap-3 mb-2"><Key size={16} className="text-indigo-600"/><h4 className="text-[10px] font-black uppercase italic text-indigo-900 tracking-widest">Segurança de Login</h4></div>
                      <div className="space-y-4">
                        <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-indigo-400 ml-3 italic">Usuário (Username)</label><input required value={memberForm.username} onChange={e => setMemberForm({...memberForm, username: e.target.value})} className="w-full px-5 py-3 bg-white border border-indigo-100 rounded-xl font-bold text-xs outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                        <div className="space-y-1.5"><label className="text-[8px] font-black uppercase text-indigo-400 ml-3 italic">Senha Provisória</label><input required type="password" value={memberForm.password} onChange={e => setMemberForm({...memberForm, password: e.target.value})} className="w-full px-5 py-3 bg-white border border-indigo-100 rounded-xl font-mono text-xs outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                      </div>
                    </div>
                 </div>
               </div>

               {/* SEÇÃO 4: PERMISSÕES */}
               <div className="space-y-12 pb-20">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">04</span><h3 className="text-xl font-black uppercase tracking-tight italic">Níveis de Acesso Habilitados</h3></div>
                 <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                    {['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'].map(area => (
                      <button 
                        key={area}
                        type="button"
                        onClick={() => {
                          const up = memberForm.acessos.includes(area) ? memberForm.acessos.filter(a => a !== area) : [...memberForm.acessos, area];
                          setMemberForm({...memberForm, acessos: up});
                        }}
                        className={`p-6 rounded-[2rem] border-2 transition-all flex flex-col items-center gap-3 ${memberForm.acessos.includes(area) ? 'bg-indigo-600 border-indigo-400 text-white shadow-xl scale-105' : 'bg-slate-50 border-slate-100 text-slate-400 hover:border-slate-300'}`}
                      >
                        <Shield size={20} className={memberForm.acessos.includes(area) ? 'text-white' : 'text-slate-300'} />
                        <span className="text-[9px] font-black uppercase tracking-widest">{area}</span>
                      </button>
                    ))}
                 </div>
                 <div className="pt-20 flex gap-6">
                    <button type="button" onClick={() => { setIsMemberModalOpen(false); setSelectedMember(null); }} className="px-12 py-6 bg-slate-100 text-slate-400 rounded-[2rem] text-[11px] font-black uppercase italic">Descartar</button>
                    <button type="submit" className="flex-1 py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic tracking-[0.2em]">{selectedMember ? 'Gravar Alterações' : 'Concluir Cadastro Equipe'}</button>
                 </div>
               </div>

             </div>
           </form>
        </div>
      )}

      {/* FICHA COMPLETA VIEW MODAL */}
      {isViewModalOpen && selectedMember && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/95 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in">
           <div className="bg-white w-full max-w-4xl rounded-[4rem] overflow-hidden flex flex-col shadow-2xl relative border-4 border-white/5">
              <button onClick={() => setIsViewModalOpen(false)} className="absolute top-10 right-10 p-4 bg-slate-100 rounded-full hover:bg-rose-600 hover:text-white transition-all z-10"><X size={24}/></button>
              <div className="p-16 space-y-12">
                 <header className="flex items-center gap-8">
                    <div className="w-28 h-28 rounded-[3rem] overflow-hidden shadow-2xl border-4 border-indigo-50 shrink-0 bg-slate-50 flex items-center justify-center">
                       {selectedMember.photoURL ? <img src={selectedMember.photoURL} className="w-full h-full object-cover" /> : <div className="text-3xl font-black italic text-indigo-600">{(selectedMember.nome||'U').charAt(0)}</div>}
                    </div>
                    <div>
                      <h2 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{selectedMember.nome || selectedMember.displayName}</h2>
                      <div className="flex gap-3 mt-4">
                        <span className="text-[10px] font-black uppercase bg-indigo-50 text-indigo-600 px-4 py-1 rounded-full border border-indigo-100">{selectedMember.role?.replace('_', ' ')}</span>
                        <span className="text-[10px] font-black uppercase bg-emerald-50 text-emerald-600 px-4 py-1 rounded-full border border-emerald-100">{selectedMember.staffId}</span>
                      </div>
                    </div>
                 </header>
                 <div className="grid grid-cols-2 lg:grid-cols-3 gap-10 text-slate-900">
                    <div className="space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">E-mail Profissional</p><p className="text-sm font-bold">{selectedMember.email}</p></div>
                    <div className="space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Endereço Residencial</p><p className="text-sm font-bold leading-tight">{selectedMember.endereco?.rua}, {selectedMember.endereco?.numero}<br/>{selectedMember.endereco?.bairro} - {selectedMember.endereco?.cidade}/{selectedMember.endereco?.uf}</p></div>
                    <div className="space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Contato Direto</p><p className="text-sm font-bold">{selectedMember.telefone || '---'}</p></div>
                    <div className="col-span-full space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Formação Acadêmica</p><p className="text-sm font-bold leading-relaxed italic">{selectedMember.formacao || 'Sem registro.'}</p></div>
                    <div className="col-span-2 space-y-1.5"><p className="text-[8px] font-black uppercase text-slate-400 italic tracking-widest">Usuário de Sistema</p><p className="text-sm font-black text-indigo-600 uppercase italic">{selectedMember.username || '---'}</p></div>
                 </div>
                 <div className="pt-12 border-t border-slate-100 flex gap-4">
                    {selectedMember.signatureUrl ? (
                      <div className="flex-1 bg-slate-50 rounded-[2rem] p-6 flex items-center justify-between border border-slate-100 shadow-inner">
                         <div className="space-y-1"><p className="text-[7px] font-black uppercase text-slate-400 italic">Certificado Digital Validado</p><p className="text-[9px] font-bold text-emerald-600 uppercase">Emissão Central Ativa</p></div>
                         <img src={selectedMember.signatureUrl} className="h-10 grayscale hover:grayscale-0 transition-all opacity-60" />
                      </div>
                    ) : (
                      <button onClick={() => { setSigningUserId(selectedMember.id); setIsSignModalOpen(true); setIsViewModalOpen(false); }} className="flex-1 bg-amber-50 text-amber-600 rounded-[2rem] p-6 text-[10px] font-black uppercase italic border border-amber-100 shadow-sm hover:bg-amber-100 transition-all flex items-center justify-center gap-3"><PenTool size={18}/> Coletar Assinatura</button>
                    )}
                 </div>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && (
        <SignaturePad 
          title="Identidade Digital EB-EAD" 
          onCancel={() => setIsSignModalOpen(false)} 
          onSave={handleSaveSignature} 
        />
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, CreditCard, ChevronRight, PenTool, 
  FileBadge, Save, Palette, Globe, Fingerprint, Lock, 
  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck,
  History, ShieldCheck, Zap, Briefcase, Calendar, Download,
  CloudLightning, HardDrive, Key, AlertTriangle, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award, MapPin, User as UserIcon, Upload, BookOpen, BriefcaseBusiness
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Equipe States
  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    dadosCurriculares: {
      formacaoAcademica: '',
      especializacoes: '',
      experienciaProfissional: '',
      resumoBio: ''
    },
    cargo: 'professor' as RoleClassification,
    fotoUrl: '', status: 'ativo', availability: 'disponivel',
    acessos: ['dashboard', 'professor', 'alunos', 'secretaria'],
    username: '', password: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);
  const [activeUsersCount, setActiveUsersCount] = useState(0);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência para o Reino',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    autoEnrollment: false,
    publicCatalog: true
  });

  const [securityConfig, setSecurityConfig] = useState({
    twoFactorAuth: true,
    sessionTimeout: 60,
    passwordComplexity: 'high',
    loginAlerts: true,
    rbacRules: {
      diretor: ['*'],
      vice_diretor: ['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'],
      secretaria: ['dashboard', 'alunos', 'secretaria', 'configuracoes'],
      coordenador: ['dashboard', 'professor', 'alunos', 'secretaria'],
      professor: ['dashboard', 'professor', 'alunos', 'secretaria'],
      apoio: ['secretaria']
    }
  });

  const [financialConfig, setFinancialConfig] = useState({
    rematricula: '150,00',
    diplomacao: '80,00',
    gatewayKey: 'pk_live_********************',
    currency: 'BRL'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(data.schoolConfig);
        if (data.securityConfig) setSecurityConfig(data.securityConfig);
        if (data.financialConfig) setFinancialConfig(data.financialConfig);
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(5)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio'])), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      data.sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));
      setStaff(data);
      setActiveUsersCount(snap.size + Math.floor(Math.random() * 3));
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setMemberForm({ ...memberForm, fotoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const addGovernanceLog = async (action: string) => {
    await addDoc(collection(db, 'system_logs'), {
      action,
      user: auth.currentUser?.displayName || 'Diretoria',
      timestamp: serverTimestamp(),
      type: 'config_update'
    });
  };

  const handleSaveAll = async () => {
    try {
      await setDoc(doc(db, 'system_settings', 'main_config'), {
        schoolConfig,
        securityConfig,
        financialConfig,
        updatedAt: serverTimestamp()
      }, { merge: true });
      await addGovernanceLog('Configurações globais atualizadas');
      alert("Configurações salvas!");
    } catch (err) {
      alert("Erro ao salvar.");
    }
  };

  const handleSaveSignature = async (base64: string) => {
    if (!signingUserId) return;
    await updateDoc(doc(db, 'users', signingUserId), { signatureUrl: base64, updatedAt: serverTimestamp() });
    setIsSignModalOpen(false);
    setSigningUserId(null);
    alert("Assinatura vinculada!");
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        endereco: memberForm.endereco,
        dadosCurriculares: memberForm.dadosCurriculares,
        role: memberForm.cargo,
        photoURL: memberForm.fotoUrl,
        status: memberForm.status,
        availability: memberForm.availability,
        permissions: memberForm.acessos,
        username: memberForm.username,
        password: memberForm.password,
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
        await addGovernanceLog(`Perfil de equipe atualizado: ${memberForm.nome}`);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
        await addGovernanceLog(`Novo membro registrado: ${memberForm.nome}`);
      }
      setIsMemberModalOpen(false);
      setSelectedMember(null);
    } catch (err) {
      alert("Erro ao processar.");
    }
  };

  const handleDeleteMember = async (id: string, nome: string) => {
    if (id === auth.currentUser?.uid) {
      alert("Operação bloqueada: Você não pode excluir seu próprio perfil de acesso.");
      return;
    }
    if (confirm(`Remover ${nome} permanentemente?`)) {
      await deleteDoc(doc(db, 'users', id));
      await addGovernanceLog(`Membro removido: ${nome}`);
    }
  };

  const handleCycleAcademicYear = async () => {
    if (confirm(`Iniciar Ciclo ${Number(schoolConfig.academicYear) + 1}?`)) {
      const next = (Number(schoolConfig.academicYear) + 1).toString();
      await updateDoc(doc(db, 'system_settings', 'main_config'), { "schoolConfig.academicYear": next });
      await addGovernanceLog(`Virada de Ciclo Acadêmico: ${next}`);
    }
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 text-slate-900">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Console de Configurações</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2 uppercase tracking-widest text-[10px]">Governança EB-EAD • {schoolConfig.schoolName}</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm overflow-x-auto">
          {[
            { id: 'geral', label: 'Institucional', icon: <Building size={14}/> },
            { id: 'equipe', label: 'Equipe', icon: <Users size={14}/> },
            { id: 'seguranca', label: 'Segurança', icon: <Shield size={14}/> },
            { id: 'financeiro', label: 'Financeiro', icon: <CreditCard size={14}/> },
            { id: 'infra', label: 'Infraestrutura', icon: <HardDrive size={14}/> }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as SettingsTab)}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
      </header>

      <main className="min-h-[500px]">
        {/* ABA GERAL */}
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in slide-in-from-bottom-4">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white p-10 rounded-[4rem] border border-slate-200 shadow-sm space-y-10">
                <div className="flex items-center gap-5 border-b border-slate-50 pb-8">
