                       <div className="space-y-2.5"><p className="text-[10px] font-black uppercase text-slate-400 italic tracking-widest">Endereço de Domicílio</p><p className="text-base font-bold leading-tight flex items-start gap-3"><MapPin size={18} className="text-indigo-400 shrink-0"/> {selectedMember.endereco?.rua}, {selectedMember.endereco?.numero}<br/>{selectedMember.endereco?.bairro} - {selectedMember.endereco?.cidade}/{selectedMember.endereco?.uf}</p></div>
                       <div className="space-y-2.5"><p className="text-[10px] font-black uppercase text-slate-400 italic tracking-widest">Níveis de Acesso</p><div className="flex flex-wrap gap-2 mt-3">{selectedMember.permissions?.map((p:any) => <span key={p} className="px-4 py-1.5 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase tracking-widest italic">{p}</span>)}</div></div>
                    </div>
                    <div className="bg-slate-50 p-10 rounded-[3rem] border border-slate-100 shadow-inner space-y-10">
                       <div className="space-y-3"><p className="text-[10px] font-black uppercase text-slate-400 italic tracking-widest flex items-center gap-2"><GraduationCap size={16} className="text-indigo-500"/> Titulação Máxima</p><p className="text-sm font-bold italic text-slate-600 leading-relaxed">{selectedMember.dadosCurriculares?.formacaoAcademica || 'Não informada.'}</p></div>
                       <div className="space-y-3"><p className="text-[10px] font-black uppercase text-slate-400 italic tracking-widest flex items-center gap-2"><Award size={16} className="text-indigo-500"/> Especializações</p><p className="text-sm font-bold italic text-slate-600 leading-relaxed">{selectedMember.dadosCurriculares?.especializacoes || 'Não informada.'}</p></div>
                    </div>
                 </div>

                 <div className="pt-16 border-t border-slate-50 flex flex-col md:flex-row gap-6">
                    {selectedMember.signatureUrl ? (
                      <div className="flex-1 bg-white rounded-[2.5rem] p-8 flex items-center justify-between border-2 border-slate-50 shadow-2xl">
                         <div className="space-y-2"><p className="text-[8px] font-black uppercase text-slate-400 italic">Identidade Digital Criptografada</p><p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest flex items-center gap-2 italic"><ShieldCheck size={14}/> Validade Jurídica EB-EAD</p></div>
                         <img src={selectedMember.signatureUrl} className="h-16 grayscale opacity-60 hover:opacity-100 transition-all cursor-pointer" />
                      </div>
                    ) : (
                      <button onClick={() => { setSigningUserId(selectedMember.id); setIsSignModalOpen(true); setIsViewModalOpen(false); }} className="flex-1 bg-amber-50 text-amber-600 rounded-[2.5rem] p-8 text-xs font-black uppercase italic border border-amber-100 shadow-xl hover:bg-amber-100 transition-all flex items-center justify-center gap-4"><PenTool size={24}/> Coletar Assinatura Oficial</button>
                    )}
                    <button onClick={() => setIsViewModalOpen(false)} className="px-16 py-8 bg-slate-900 text-white rounded-[2.5rem] text-xs font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-2xl">Fechar Ficha</button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && (
        <SignaturePad 
          title="Consolidação de Identidade Digital" 
          onCancel={() => setIsSignModalOpen(false)} 
          onSave={handleSaveSignature} 
        />
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, CreditCard, ChevronRight, PenTool, 
  FileBadge, Save, Palette, Globe, Fingerprint, Lock, 
  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck,
  History, ShieldCheck, Zap, Briefcase, Calendar, Download,
  CloudLightning, HardDrive, Key, AlertTriangle, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award, MapPin, User as UserIcon, Upload, BookOpen, 
  BriefcaseBusiness, Cpu, Server, BarChart3, Globe2
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio' | 'ti';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Equipe States
  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    dadosCurriculares: {
      formacaoAcademica: '',
      especializacoes: '',
      experienciaProfissional: '',
      resumoBio: ''
    },
    cargo: 'professor' as RoleClassification,
    fotoUrl: '', status: 'ativo',
    acessos: ['dashboard', 'professor', 'alunos', 'secretaria'],
    username: '', password: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência para o Reino',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    autoEnrollment: false,
    publicCatalog: true
  });

  const [securityConfig, setSecurityConfig] = useState({
    twoFactorAuth: true,
    sessionTimeout: 60,
    passwordComplexity: 'high',
    loginAlerts: true,
    rbacRules: {
      ti: ['*'],
      diretor: ['*'],
      vice_diretor: ['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'],
      secretaria: ['dashboard', 'alunos', 'secretaria', 'configuracoes'],
      coordenador: ['dashboard', 'professor', 'alunos', 'secretaria'],
      professor: ['dashboard', 'professor', 'alunos', 'secretaria'],
      apoio: ['secretaria']
    }
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(data.schoolConfig);
        if (data.securityConfig) setSecurityConfig(data.securityConfig);
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(8)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio', 'ti'])), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      // Filtramos o root master da lista pública de equipe conforme solicitado
      const filteredStaff = data.filter(u => u.staffId !== 'MASTER' && u.uid !== 'root_user_id');
      filteredStaff.sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));
      setStaff(filteredStaff);
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setMemberForm({ ...memberForm, fotoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        endereco: memberForm.endereco,
        dadosCurriculares: memberForm.dadosCurriculares,
        role: memberForm.cargo,
        photoURL: memberForm.fotoUrl, // Garantindo salvamento correto da foto
        status: memberForm.status,
        permissions: memberForm.acessos,
        username: memberForm.username,
        password: memberForm.password,
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
      }
      setIsMemberModalOpen(false);
      setSelectedMember(null);
    } catch (err) {
      alert("Erro ao processar.");
    }
  };

  const handleSaveSignature = async (base64: string) => {
    if (!signingUserId) return;
    await updateDoc(doc(db, 'users', signingUserId), { signatureUrl: base64, updatedAt: serverTimestamp() });
    setIsSignModalOpen(false);
    setSigningUserId(null);
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

