                       <div className="space-y-8"><div className="flex items-center gap-4"><div className="w-1.5 h-8 bg-indigo-600 rounded-full"></div><h3 className="text-2xl font-black uppercase italic tracking-tighter">Assinatura Digital EB-EAD</h3></div>
                          {selectedMember.signatureUrl ? (
                            <div className="p-10 bg-slate-900 rounded-[3rem] shadow-2xl flex flex-col items-center justify-center gap-6 relative overflow-hidden group">
                               <p className="text-[9px] font-black uppercase text-indigo-400 tracking-[0.4em] italic z-10">VALIDAÇÃO MASTER ATIVA</p>
                               <img src={selectedMember.signatureUrl} className="h-24 object-contain grayscale opacity-60 group-hover:grayscale-0 group-hover:opacity-100 transition-all cursor-pointer z-10" />
                               <Globe2 size={150} className="absolute -bottom-10 -right-10 text-white/5 opacity-5" />
                            </div>
                          ) : (
                            <button onClick={() => { setSigningUserId(selectedMember.id); setIsSignModalOpen(true); }} className="w-full p-16 bg-amber-50 text-amber-600 rounded-[3rem] border-4 border-dashed border-amber-200 text-xs font-black uppercase italic tracking-widest hover:bg-amber-100 transition-all flex flex-col items-center gap-5"><PenTool size={48} className="animate-bounce" /> Coletar Assinatura Digital Agora</button>
                          )}
                       </div>
                    </div>
                 </div>
                 <div className="pt-20 text-center"><p className="text-[10px] font-black text-slate-300 uppercase italic tracking-[0.6em]">EB-EAD ACADEMIC DOSSIER 2026</p></div>
              </div>
           </main>
        </div>
      )}

      {isSignModalOpen && (
        <SignaturePad 
          title="Consolidação de Identidade Digital" 
          onCancel={() => setIsSignModalOpen(false)} 
          onSave={handleSaveSignature} 
        />
      )}
    </div>
  );
};

