  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck,
  History, ShieldCheck, Zap, Briefcase, Calendar, Download,
  CloudLightning, HardDrive, Key, AlertTriangle, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award, MapPin, User as UserIcon, Upload, BookOpen, 
  BriefcaseBusiness, Cpu, Server, BarChart3, Globe2
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio' | 'ti';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Equipe States
  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    dadosCurriculares: {
      formacaoAcademica: '',
      especializacoes: '',
      experienciaProfissional: '',
      resumoBio: ''
    },
    cargo: 'professor' as RoleClassification,
    fotoUrl: '', status: 'ativo',
    acessos: ['dashboard', 'professor', 'alunos', 'secretaria'],
    username: '', password: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência para o Reino',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    autoEnrollment: false,
    publicCatalog: true
  });

  const [securityConfig, setSecurityConfig] = useState({
    twoFactorAuth: true,
    sessionTimeout: 60,
    passwordComplexity: 'high',
    loginAlerts: true,
    rbacRules: {
      ti: ['*'],
      diretor: ['*'],
      vice_diretor: ['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'],
      secretaria: ['dashboard', 'alunos', 'secretaria', 'configuracoes'],
      coordenador: ['dashboard', 'professor', 'alunos', 'secretaria'],
      professor: ['dashboard', 'professor', 'alunos', 'secretaria'],
      apoio: ['secretaria']
    }
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({...prev, ...data.schoolConfig}));
        if (data.securityConfig) setSecurityConfig(prev => ({...prev, ...data.securityConfig}));
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(8)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(collection(db, 'users'), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      // Filtramos para mostrar apenas membros administrativos/docentes, removendo root anônimo se houver
      const filteredStaff = data.filter(u => u.role && u.role !== 'aluno');
      filteredStaff.sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));
      setStaff(filteredStaff);
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setMemberForm({ ...memberForm, fotoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        endereco: memberForm.endereco,
        dadosCurriculares: memberForm.dadosCurriculares,
        role: memberForm.cargo,
        photoURL: memberForm.fotoUrl,
        status: memberForm.status,
        permissions: memberForm.acessos,
        username: memberForm.username,
        password: memberForm.password,
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
      }
      setIsMemberModalOpen(false);
      setSelectedMember(null);
    } catch (err) {
      alert("Erro ao processar.");
    }
  };

  const handleDeleteMember = async (id: string, name: string) => {
    if (confirm(`Remover credenciamento de ${name} permanentemente?`)) {
      try {
        await deleteDoc(doc(db, 'users', id));
        alert("Credenciamento removido com sucesso.");
      } catch (err) {
        console.error("Erro ao remover membro:", err);
        alert("Erro ao remover credenciamento.");
      }
    }
  };

  const handleSaveSignature = async (base64: string) => {
    if (!signingUserId) return;
    await updateDoc(doc(db, 'users', signingUserId), { signatureUrl: base64, updatedAt: serverTimestamp() });
    setIsSignModalOpen(false);
    setSigningUserId(null);
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 text-slate-900">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Console de Governança</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2 uppercase tracking-widest text-[10px]">Gestão Administrativa & Infraestrutura EB-EAD</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm overflow-x-auto">
          {[
            { id: 'geral', label: 'Institucional', icon: <Building size={14}/> },
            { id: 'equipe', label: 'Equipe', icon: <Users size={14}/> },
            { id: 'seguranca', label: 'Segurança', icon: <Shield size={14}/> },
            { id: 'infra', label: 'Infraestrutura', icon: <HardDrive size={14}/> }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as SettingsTab)}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
      </header>

      <main className="min-h-[600px]">
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in slide-in-from-bottom-4">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-10">
                <div className="flex items-center gap-5 border-b border-slate-50 pb-8">
                  <div className="p-4 bg-indigo-50 text-indigo-600 rounded-3xl shadow-inner"><Building size={28} /></div>
                  <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Identidade Institucional</h3>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Dados Mestres da Organização</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {[
                    { label: 'Nome da Escola', value: schoolConfig.schoolName, icon: <Building size={14}/> },
                    { label: 'Lema Acadêmico', value: schoolConfig.motto, icon: <Award size={14}/> },
                    { label: 'CNPJ', value: schoolConfig.registrationNumber, icon: <FileBadge size={14}/> },
                    { label: 'Portal Oficial', value: schoolConfig.website, icon: <Globe size={14}/> }
                  ].map((field, idx) => (
                    <div key={idx} className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic tracking-widest flex items-center gap-2">{field.icon} {field.label}</label>
                      <div className="w-full px-6 py-4 bg-slate-50 rounded-2xl font-black text-xs text-slate-900 border border-slate-100 shadow-inner">{field.value}</div>
                    </div>
                  ))}
                </div>

                <div className="pt-6 space-y-6">
                   <h4 className="text-[10px] font-black uppercase tracking-widest italic text-slate-400 ml-2">Esquema de Cores Ativo</h4>
                   <div className="grid grid-cols-2 gap-6">
                      <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                         <div className="w-12 h-12 rounded-xl shadow-lg border-2 border-white" style={{ backgroundColor: schoolConfig.primaryColor }}></div>
                         <div><p className="text-[8px] font-black uppercase text-slate-400">Primária</p><p className="text-xs font-mono font-bold uppercase">{schoolConfig.primaryColor}</p></div>
                      </div>
                      <div className="flex items-center gap-4 p-4 bg-slate-50 rounded-2xl border border-slate-100">
                         <div className="w-12 h-12 rounded-xl shadow-lg border-2 border-white" style={{ backgroundColor: schoolConfig.secondaryColor }}></div>
                         <div><p className="text-[8px] font-black uppercase text-slate-400">Secundária</p><p className="text-xs font-mono font-bold uppercase">{schoolConfig.secondaryColor}</p></div>
                      </div>
                   </div>
                </div>
              </div>

              <div className="bg-slate-900 p-10 rounded-[3rem] text-white space-y-10 shadow-2xl relative overflow-hidden">
                <div className="relative z-10 flex flex-col md:flex-row justify-between gap-8">
                   <div className="space-y-6 flex-1">
                      <div className="flex items-center gap-3"><Server size={20} className="text-indigo-400"/><h3 className="text-xs font-black uppercase tracking-widest italic">Serviços de Infraestrutura</h3></div>
                      <div className="grid grid-cols-2 gap-6">
                         <div className="p-5 bg-white/5 rounded-2xl border border-white/5 shadow-inner">
                            <p className="text-[8px] font-black uppercase text-white/30 italic">Uptime Global</p>
                            <p className="text-2xl font-black italic text-emerald-400 tracking-tighter">99.99%</p>
                         </div>
                         <div className="p-5 bg-white/5 rounded-2xl border border-white/5 shadow-inner">
                            <p className="text-[8px] font-black uppercase text-white/30 italic">Latência Média</p>
                            <p className="text-2xl font-black italic text-indigo-400 tracking-tighter">14ms</p>
                         </div>
                      </div>
                   </div>
                   <div className="space-y-6 flex-1">
                      <div className="flex items-center gap-3"><BarChart3 size={20} className="text-indigo-400"/><h3 className="text-xs font-black uppercase tracking-widest italic">Carga de Trabalho</h3></div>
                      <div className="w-full bg-white/5 rounded-full h-1.5 overflow-hidden"><div className="w-1/3 h-full bg-indigo-500"></div></div>
                      <div className="flex justify-between text-[8px] font-black uppercase text-white/20 italic"><span>Firestore I/O: Normal</span><span>820 req/sec</span></div>
                   </div>
                </div>
                <Cpu size={250} className="absolute -bottom-20 -right-20 text-white/5 opacity-10" />
              </div>
            </div>

            <div className="lg:col-span-4 space-y-8">
              <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-8">
                  <div className="flex items-center gap-3"><Activity size={16} className="text-indigo-600"/><h3 className="text-[10px] font-black uppercase tracking-widest italic text-slate-800">Eventos de Governança</h3></div>
                  <div className="space-y-4">
                     {governanceLogs.map(log => (
                       <div key={log.id} className="border-l-2 border-indigo-500 pl-4 py-1">
                         <p className="text-[10px] font-bold leading-tight uppercase text-slate-800 italic">{log.action}</p>
                         <p className="text-[8px] text-slate-400 mt-1 uppercase font-bold">{log.user} • {log.timestamp?.seconds ? new Date(log.timestamp.seconds * 1000).toLocaleTimeString() : 'Agora'}</p>
                       </div>
                     ))}
                  </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'equipe' && (
          <div className="space-y-8 animate-in zoom-in-95">
             <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
                <div className="flex items-center gap-4">
                  <div className="p-4 bg-slate-900 text-white rounded-3xl shadow-xl"><Users size={24}/></div>
                  <div><h3 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Corpo Administrativo e Docente</h3><p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">Gestão de Identidade Corporativa</p></div>
                </div>
                <button onClick={() => { 
                  setSelectedMember(null); 
                  setMemberForm({
                    nome:'',email:'',documento:'',telefone:'',
                    endereco:{rua:'',numero:'',bairro:'',cidade:'',uf:''},
                    dadosCurriculares: { formacaoAcademica: '', especializacoes: '', experienciaProfissional: '', resumoBio: '' },
                    cargo:'professor',fotoUrl:'',status:'ativo',
                    acessos:['dashboard', 'professor', 'alunos', 'secretaria'],
                    username: '', password: ''
                  }); 
                  setIsMemberModalOpen(true); 
                }} className="bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[9px] font-black uppercase italic tracking-widest shadow-2xl hover:bg-indigo-600 transition-all flex items-center gap-2"><Plus size={16}/> Credenciar Membro</button>
             </div>

             <div className="bg-white rounded-[2.5rem] border border-slate-200 overflow-hidden shadow-sm">
                <table className="w-full text-left">
                   <thead className="bg-white text-[9px] font-black text-slate-400 uppercase tracking-widest border-b italic">
                      <tr>
                        <th className="px-10 py-8">ID / MEMBRO</th>
                        <th className="px-10 py-8">FUNÇÃO ACADÊMICA</th>
                        <th className="px-10 py-8">STATUS DIGITAL</th>
                        <th className="px-10 py-8 text-right">GESTÃO DE FICHA</th>
                      </tr>
                   </thead>
                   <tbody className="divide-y divide-slate-100">
                      {staff.map(member => (
                        <tr key={member.id} className="hover:bg-slate-50/50 transition-colors group">
                           <td className="px-10 py-8 flex items-center gap-5">
                              <div className="w-16 h-16 rounded-[1.8rem] overflow-hidden shadow-lg border-4 border-white shrink-0 group-hover:scale-105 transition-transform bg-slate-100 flex items-center justify-center">
                                 {member.photoURL ? <img src={member.photoURL} className="w-full h-full object-cover" /> : <div className="font-black text-indigo-600 italic text-xl">{(member.nome||'U').charAt(0)}</div>}
                              </div>
                              <div className="flex flex-col gap-1">
                                <p className="text-sm font-black text-slate-900 uppercase italic tracking-tight">{member.nome || member.displayName}</p>
                                <span className="text-[9px] font-black font-mono text-indigo-500 uppercase tracking-widest">{member.staffId || 'MASTER'}</span>
                              </div>
                           </td>
                           <td className="px-10 py-8">
                              <span className="text-[10px] font-black uppercase text-slate-700 italic px-5 py-2 bg-slate-100 rounded-xl border border-slate-200">{member.role?.replace('_', ' ')}</span>
                           </td>
                           <td className="px-10 py-8">
                              <div className="flex items-center gap-3">
                                <div className="w-3 h-3 rounded-full bg-emerald-500 animate-pulse"></div>
                                <span className="text-[10px] font-black uppercase italic text-emerald-600">Ativo</span>
                              </div>
                           </td>
                           <td className="px-10 py-8 text-right">
                              <div className="flex justify-end gap-3">
                                <button onClick={() => { setSelectedMember(member); setIsViewModalOpen(true); }} className="p-4 bg-white border border-slate-100 text-slate-200 hover:text-indigo-600 rounded-2xl shadow-sm transition-all"><Eye size={20}/></button>
                                <button onClick={() => { 
                                  setSelectedMember(member); 
                                  setMemberForm({
                                    nome: member.nome || member.displayName || '', 
                                    email: member.email || '', 
                                    documento: member.documento || '',
                                    telefone: member.telefone || '', 
                                    endereco: member.endereco || {rua:'',numero:'',bairro:'',cidade:'',uf:''},
                                    dadosCurriculares: member.dadosCurriculares || { formacaoAcademica: '', especializacoes: '', experienciaProfissional: '', resumoBio: '' },
                                    cargo: member.role || 'professor',
                                    fotoUrl: member.photoURL || '', 
                                    status: member.status || 'ativo',
                                    acessos: member.permissions || [],
                                    username: member.username || '',
                                    password: member.password || ''
                                  });
                                  setIsMemberModalOpen(true); 
                                }} className="p-4 bg-white border border-slate-100 text-slate-200 hover:text-amber-600 rounded-2xl shadow-sm transition-all"><Edit3 size={20}/></button>
                                <button onClick={() => handleDeleteMember(member.id, member.nome || member.displayName)} className="p-4 bg-white border border-slate-100 text-slate-100 hover:text-rose-600 rounded-2xl shadow-sm transition-all"><Trash2 size={20}/></button>
                              </div>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        )}

        {activeTab === 'seguranca' && (
           <div className="bg-white p-12 rounded-[3rem] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-10 animate-in zoom-in-95">
              <div className="flex items-center gap-5 border-b pb-8">
                 <div className="p-5 bg-emerald-50 text-emerald-600 rounded-3xl shadow-inner"><Shield size={32}/></div>
                 <div><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Políticas de Acesso (RBAC)</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2">Níveis de Autoridade por Perfil</p></div>
              </div>
              <div className="space-y-4">
                 {Object.entries(securityConfig.rbacRules || {}).map(([role, access]) => (
                   <div key={role} className="flex items-center justify-between p-6 bg-slate-50 rounded-2xl border border-slate-100 group hover:border-indigo-400 transition-all">
                      <span className="text-xs font-black uppercase italic text-slate-700 tracking-tight">{role.replace('_', ' ')}</span>
                      <div className="flex gap-2">
                         {(access as string[]).map(a => <span key={a} className="text-[8px] font-black uppercase bg-indigo-600 text-white px-3 py-1 rounded shadow-sm">{a === '*' ? 'ACESSO TOTAL' : a}</span>)}
                      </div>
                   </div>
                 ))}
              </div>
           </div>
        )}
      </main>

      {isMemberModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-white flex flex-col animate-in slide-in-from-bottom duration-500">
           <header className="bg-slate-900 p-8 lg:px-12 flex justify-between items-center border-b border-white/5">
             <div className="flex items-center gap-6">
               <div className="p-5 rounded-[2rem] bg-indigo-600 text-white shadow-xl">
                 {selectedMember ? <Edit3 size={40}/> : <Plus size={40}/>}
               </div>
               <h2 className="text-3xl lg:text-4xl font-black text-white uppercase italic tracking-tighter leading-none">{selectedMember ? 'Revisar Ficha Equipe' : 'Novo Credenciamento'}</h2>
             </div>
             <button onClick={() => { setIsMemberModalOpen(false); setSelectedMember(null); }} className="p-5 bg-white/5 text-white rounded-full hover:bg-rose-600 transition-all"><X size={32}/></button>
           </header>

           <form onSubmit={handleSaveMember} className="flex-1 overflow-y-auto bg-white flex flex-col items-center custom-scrollbar">
             <div className="w-full max-w-5xl p-12 lg:p-20 space-y-32 text-slate-900 pb-40">
               <div className="space-y-12">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">01</span><h3 className="text-xl font-black uppercase tracking-tight italic">Identidade Profissional</h3></div>
                 <div className="grid grid-cols-1 md:grid-cols-12 gap-10">
                   <div className="md:col-span-4 flex flex-col items-center gap-6">
                      <div 
                        onClick={() => fileInputRef.current?.click()}
                        className="w-52 h-52 rounded-[3.5rem] bg-slate-50 border-4 border-dashed border-slate-200 flex flex-col items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all shadow-inner relative group"
                      >
                         {memberForm.fotoUrl ? (
                           <img src={memberForm.fotoUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform" />
                         ) : (
                           <>
                             <Upload size={48} className="text-slate-200 mb-2" />
                             <span className="text-[8px] font-black uppercase text-slate-400 tracking-widest">Upload Foto</span>
                           </>
                         )}
                         <div className="absolute inset-0 bg-indigo-600/60 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                            <Camera size={40} className="text-white" />
                         </div>
                         <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                      </div>
                   </div>
                   <div className="md:col-span-8 grid grid-cols-1 sm:grid-cols-2 gap-8">
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Nome Completo</label><input required value={memberForm.nome} onChange={e => setMemberForm({...memberForm, nome: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-black text-xs" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">E-mail Corporativo</label><input required type="email" value={memberForm.email} onChange={e => setMemberForm({...memberForm, email: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Documento (CPF/RG)</label><input required value={memberForm.documento} onChange={e => setMemberForm({...memberForm, documento: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-mono text-xs" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Telefone Direto</label><input required value={memberForm.telefone} onChange={e => setMemberForm({...memberForm, telefone: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs" /></div>
                   </div>
                 </div>
               </div>

