import React, { useState, useEffect } from 'react';
// Correcting imports for Firebase modular SDK
import { onAuthStateChanged } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from './firebase';
import { UserRole, MainView, User, ProfessorSubView } from './types';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [activeProfessorSubView, setActiveProfessorSubView] = useState<ProfessorSubView>('cursos');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    let unsubscribeSnapshot: (() => void) | undefined;

    const unsubscribeAuth = onAuthStateChanged(auth, async (user) => {
      if (user) {
        // Usar onSnapshot para garantir que mudanças no perfil (como promoção a Diretor) reflitam em tempo real no Navbar
        const userRef = doc(db, 'users', user.uid);

        unsubscribeSnapshot = onSnapshot(userRef, (docSnap) => {
          if (docSnap.exists()) {
            const userData = docSnap.data();
            const role = (userData?.role as UserRole) || 'aluno';

            // Tratamento especial para o Master/Root para exibição amigável
            const displayRole = (userData?.staffId === 'MASTER' || !userData?.role) ? 'TI / MASTER' : role;

            setCurrentUser({
              uid: user.uid,
              email: user.email,
              displayName: userData?.nome || userData?.displayName || user.displayName || 'Usuário',
              role: displayRole as any,
              photoURL: userData?.photoURL || user.photoURL || undefined
            });
          } else {
            // Criar doc se não existir (primeiro login social por exemplo)
            setDoc(userRef, {
              nome: user.displayName || 'Novo Usuário',
              role: 'aluno',
              email: user.email,
              createdAt: new Date()
            });
          }
          setLoading(false);
        });
      } else {
        setCurrentUser(null);
        setLoading(false);
      }
    });

    return () => {
      unsubscribeAuth();
      if (unsubscribeSnapshot) unsubscribeSnapshot();
    };
  }, []);

  const navigateToSubView = (main: MainView, sub?: ProfessorSubView) => {
    setActiveView(main);
    if (sub) setActiveProfessorSubView(sub);
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-50">
        <div className="flex flex-col items-center gap-4">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div>
          <p className="text-xs font-bold uppercase tracking-widest text-slate-500">Escola Bíblica EAD</p>
        </div>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView onNavigate={navigateToSubView} />;
      case 'professor': return <ProfessorView user={currentUser} activeSubView={activeProfessorSubView} />;
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView user={currentUser} />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView onNavigate={navigateToSubView} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans antialiased text-slate-900">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setIsMobileMenuOpen(false); }}
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <div className="flex-1 flex overflow-hidden">
        {(activeView === 'professor') && (
          <Sidebar 
            activeSub={activeProfessorSubView} 
            setActiveSub={setActiveProfessorSubView} 
          />
        )}

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8 h-full">
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, CreditCard, ChevronRight, PenTool, 
  FileBadge, Save, Palette, Globe, Fingerprint, Lock, 
  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck,
  History, ShieldCheck, Zap, Briefcase, Calendar, Download,
  CloudLightning, HardDrive, Key, AlertTriangle, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award, MapPin, User as UserIcon, Upload, BookOpen, 
  BriefcaseBusiness, Cpu, Server, BarChart3, Globe2
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio' | 'ti';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    dadosCurriculares: {
      formacaoAcademica: '',
      especializacoes: '',
      experienciaProfissional: '',
      resumoBio: ''
    },
    cargo: 'professor' as RoleClassification,
    fotoUrl: '', status: 'ativo',
    acessos: ['dashboard', 'professor', 'alunos', 'secretaria'],
    username: '', password: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência para o Reino',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    autoEnrollment: false,
    publicCatalog: true
  });

  const [securityConfig, setSecurityConfig] = useState({
    rbacRules: {
      ti: ['*'],
      diretor: ['*'],
      vice_diretor: ['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'],
      secretaria: ['dashboard', 'alunos', 'secretaria', 'configuracoes'],
      coordenador: ['dashboard', 'professor', 'alunos', 'secretaria'],
      professor: ['dashboard', 'professor', 'alunos', 'secretaria'],
      apoio: ['secretaria']
    }
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({...prev, ...data.schoolConfig}));
        if (data.securityConfig) setSecurityConfig(prev => ({...prev, ...data.securityConfig}));
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(8)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(collection(db, 'users'), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      // FILTRAGEM RIGOROSA: Remove Master Root manual e qualquer um sem ID de staff da plataforma
      const filteredStaff = data.filter(u => 
        u.staffId && 
        u.staffId !== 'MASTER' && 
        u.role !== 'aluno' &&
        u.uid !== 'root_manual_id' // Placeholder para o seu ID manual se soubermos
      );
      filteredStaff.sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));
      setStaff(filteredStaff);
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = 400;
          const scaleSize = MAX_WIDTH / img.width;
          canvas.width = MAX_WIDTH;
          canvas.height = img.height * scaleSize;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
          // Comprime para JPEG 0.7 para garantir que caiba no limite de 1MB do doc Firestore
          const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
          setMemberForm({ ...memberForm, fotoUrl: dataUrl });
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        endereco: memberForm.endereco,
        dadosCurriculares: memberForm.dadosCurriculares,
        role: memberForm.cargo,
        photoURL: memberForm.fotoUrl, // Agora comprimida
        status: memberForm.status,
        permissions: memberForm.acessos,
        username: memberForm.username,
        password: memberForm.password,
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
      }
      setIsMemberModalOpen(false);
      setSelectedMember(null);
    } catch (err) {
