                               <p className="text-[9px] font-black uppercase text-indigo-400 tracking-[0.4em] italic z-10">VALIDAÇÃO MASTER ATIVA</p>
                               <img src={selectedMember.signatureUrl} className="h-24 object-contain grayscale opacity-60 group-hover:grayscale-0 group-hover:opacity-100 transition-all cursor-pointer z-10" />
                               <Globe2 size={150} className="absolute -bottom-10 -right-10 text-white/5 opacity-5" />
                               <button onClick={() => { setSigningUserId(selectedMember.id || selectedMember.uid); setIsSignModalOpen(true); }} className="mt-4 px-6 py-2 bg-white/10 hover:bg-white/20 rounded-xl text-[8px] font-black uppercase transition-all">Atualizar Assinatura</button>
                            </div>
                          ) : (
                            <button onClick={() => { setSigningUserId(selectedMember.id || selectedMember.uid); setIsSignModalOpen(true); }} className="w-full p-16 bg-amber-50 text-amber-600 rounded-[3rem] border-4 border-dashed border-amber-200 text-xs font-black uppercase italic tracking-widest hover:bg-amber-100 transition-all flex flex-col items-center gap-5"><PenTool size={48} className="animate-bounce" /> Coletar Assinatura Digital Agora</button>
                          )}
                       </div>
                    </div>
                 </div>
              </div>
           </main>
        </div>
      )}

      {isSignModalOpen && (
        <SignaturePad 
          title="Consolidação de Identidade Digital" 
          onCancel={() => setIsSignModalOpen(false)} 
          onSave={handleSaveSignature} 
        />
      )}
    </div>
  );
};

