                                    status: member.status || 'ativo',
                                    acessos: member.permissions || [],
                                    username: member.username || '',
                                    password: member.password || ''
                                  });
                                  setIsMemberModalOpen(true); 
                                }} className="p-4 bg-white border border-slate-100 text-slate-200 hover:text-amber-600 rounded-2xl shadow-sm transition-all"><Edit3 size={20}/></button>
                                <button onClick={() => handleDeleteMember(member.id, member.nome || member.displayName)} className="p-4 bg-white border border-slate-100 text-slate-100 hover:text-rose-600 rounded-2xl shadow-sm transition-all"><Trash2 size={20}/></button>
                              </div>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        )}

        {activeTab === 'seguranca' && (
           <div className="bg-white p-12 rounded-[3rem] border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-10 animate-in zoom-in-95">
              <div className="flex items-center gap-5 border-b pb-8">
                 <div className="p-5 bg-emerald-50 text-emerald-600 rounded-3xl shadow-inner"><Shield size={32}/></div>
                 <div><h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Políticas de Acesso (RBAC)</h3><p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-2">Níveis de Autoridade por Perfil</p></div>
              </div>
              <div className="space-y-4">
                 {Object.entries(securityConfig.rbacRules || {}).map(([role, access]) => (
                   <div key={role} className="flex items-center justify-between p-6 bg-slate-50 rounded-2xl border border-slate-100 group hover:border-indigo-400 transition-all">
                      <span className="text-xs font-black uppercase italic text-slate-700 tracking-tight">{role.replace('_', ' ')}</span>
                      <div className="flex gap-2">
                         {(access as string[]).map(a => <span key={a} className="text-[8px] font-black uppercase bg-indigo-600 text-white px-3 py-1 rounded shadow-sm">{a === '*' ? 'ACESSO TOTAL' : a}</span>)}
                      </div>
                   </div>
                 ))}
              </div>
           </div>
        )}
      </main>

      {/* FORMULÁRIO DE CADASTRO EQUIPE */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 z-[2000] bg-white flex flex-col animate-in slide-in-from-bottom duration-500">
