                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">02</span><h3 className="text-xl font-black uppercase tracking-tight italic">Residência e Localidade</h3></div>
                 <div className="grid grid-cols-1 md:grid-cols-12 gap-8">
                    <div className="md:col-span-9 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Logradouro / Endereço</label><input value={memberForm.endereco.rua} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, rua: e.target.value}})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-3 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Número</label><input value={memberForm.endereco.numero} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, numero: e.target.value}})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Bairro</label><input value={memberForm.endereco.bairro} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, bairro: e.target.value}})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs shadow-inner" /></div>
