                        <select value={memberForm.cargo} onChange={e => setMemberForm({...memberForm, cargo: e.target.value as any})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-black text-[11px] uppercase shadow-inner appearance-none cursor-pointer">
                           <option value="diretor">Diretor (Pleno)</option>
                           <option value="vice_diretor">Vice-Diretor (Suplente)</option>
                           <option value="ti">Gestão de Tecnologia (TI)</option>
                           <option value="coordenador">Coordenador (Supervisor)</option>
                           <option value="secretaria">Secretário(a) (Gestão)</option>
