                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Especializações</label><textarea value={memberForm.dadosCurriculares.especializacoes} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, especializacoes: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-28 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Experiência Profissional</label><textarea value={memberForm.dadosCurriculares.experienciaProfissional} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, experienciaProfissional: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-32 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                         </div>
                      </div>
                    </div>

                    <div className="lg:col-span-5 space-y-10">
                      <div className="p-10 bg-indigo-50/40 rounded-[3rem] border border-indigo-100 shadow-2xl space-y-8">
                        <div className="flex items-center gap-3 mb-2"><Key size={20} className="text-indigo-600"/><h4 className="text-[11px] font-black uppercase italic text-indigo-900 tracking-widest">Segurança de Acesso</h4></div>
                        <div className="space-y-6">
                          <div className="space-y-2"><label className="text-[9px] font-black uppercase text-indigo-400 ml-4 italic">Nome de Usuário (Login)</label><input required value={memberForm.username} onChange={e => setMemberForm({...memberForm, username: e.target.value})} className="w-full px-6 py-4 bg-white border border-indigo-100 rounded-2xl font-black text-xs outline-none focus:ring-2 focus:ring-indigo-600 shadow-sm" /></div>
                          <div className="space-y-2"><label className="text-[9px] font-black uppercase text-indigo-400 ml-4 italic">Senha Master Temporária</label><input required type="password" value={memberForm.password} onChange={e => setMemberForm({...memberForm, password: e.target.value})} className="w-full px-6 py-4 bg-white border border-indigo-100 rounded-2xl font-mono text-xs outline-none focus:ring-2 focus:ring-indigo-600 shadow-sm" /></div>
                        </div>
                      </div>
                      <div className="space-y-6">
                        <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Situação de Cadastro</label><select value={memberForm.status} onChange={e => setMemberForm({...memberForm, status: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-black text-[11px] uppercase shadow-inner"><option value="ativo">Conta Ativa</option><option value="inativo">Bloqueado</option></select></div>
                      </div>
                    </div>
                 </div>
               </div>

               <div className="space-y-12 pb-20">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">04</span><h3 className="text-xl font-black uppercase tracking-tight italic">Níveis de Acesso Habilitados</h3></div>
                 <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                    {[
                      { id: 'dashboard', label: 'Dashboard', icon: <Activity size={24}/> },
                      { id: 'professor', label: 'Professor', icon: <BookOpen size={24}/> },
                      { id: 'alunos', label: 'Alunos', icon: <Users size={24}/> },
                      { id: 'secretaria', label: 'Secretaria', icon: <PenTool size={24}/> },
                      { id: 'configuracoes', label: 'Configurações', icon: <SettingsIcon size={24}/> }
                    ].map(area => (
                      <button key={area.id} type="button" onClick={() => { const up = memberForm.acessos.includes(area.id) ? memberForm.acessos.filter(a => a !== area.id) : [...memberForm.acessos, area.id]; setMemberForm({...memberForm, acessos: up}); }} className={`p-10 rounded-[3rem] border-4 transition-all flex flex-col items-center gap-5 shadow-2xl ${memberForm.acessos.includes(area.id) ? 'bg-indigo-600 border-indigo-400 text-white scale-105' : 'bg-slate-50 border-white text-slate-300 hover:border-slate-100 hover:text-slate-500'}`}>
                        <div className={`p-4 rounded-2xl ${memberForm.acessos.includes(area.id) ? 'bg-white/10' : 'bg-white/40 shadow-inner'}`}>{area.icon}</div>
                        <span className="text-[10px] font-black uppercase tracking-widest italic">{area.label}</span>
                      </button>
                    ))}
                 </div>
                 <div className="pt-24 flex gap-6">
                    <button type="button" onClick={() => { setIsMemberModalOpen(false); setSelectedMember(null); }} className="px-12 py-7 bg-slate-100 text-slate-400 rounded-[2rem] text-xs font-black uppercase italic hover:bg-slate-200 transition-all">Descartar</button>
                    <button type="submit" className="flex-1 py-7 bg-slate-900 text-white rounded-[2rem] text-xs font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic tracking-[0.3em]">{selectedMember ? 'Gravar Alterações' : 'Efetivar Credenciamento'}</button>
                 </div>
               </div>
             </div>
           </form>
        </div>
      )}

      {/* FICHA COMPLETA: FULL-SCREEN */}
      {isViewModalOpen && selectedMember && (
        <div className="fixed inset-0 z-[3000] bg-white animate-in slide-in-from-right duration-500 overflow-y-auto custom-scrollbar flex flex-col text-slate-900">
           <header className="sticky top-0 bg-slate-900 px-12 py-6 flex items-center justify-between shadow-2xl z-[3100]">
              <div className="flex items-center gap-6">
                 <button onClick={() => setIsViewModalOpen(false)} className="p-3 bg-white/10 text-white rounded-xl hover:bg-rose-600 transition-all shadow-xl"><ArrowLeft size={24}/></button>
                 <div><h2 className="text-xl font-black text-white uppercase italic tracking-tighter leading-none">Perfil Acadêmico Completo</h2><p className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Dossiê EB-EAD Digital</p></div>
              </div>
              <div className="flex items-center gap-4">
                 <div className="px-5 py-2 rounded-xl text-[9px] font-black uppercase border italic bg-emerald-600/10 border-emerald-500/30 text-emerald-400">ATIVO</div>
                 <button onClick={() => setIsViewModalOpen(false)} className="p-3 bg-white/10 text-white rounded-full hover:bg-rose-600 transition-all"><X size={20}/></button>
              </div>
           </header>

           <main className="flex-1 bg-white p-12 lg:p-24 space-y-32 flex flex-col items-center">
              <div className="w-full max-w-6xl space-y-32">
                 <div className="flex flex-col md:flex-row items-center md:items-start gap-16">
                    <div className="w-72 h-72 rounded-[4rem] overflow-hidden shadow-2xl border-8 border-slate-50 shrink-0 bg-slate-50 flex items-center justify-center">
                       {selectedMember.photoURL ? <img src={selectedMember.photoURL} className="w-full h-full object-cover" /> : <div className="text-8xl font-black italic text-indigo-600">{(selectedMember.nome||'U').charAt(0)}</div>}
                    </div>
                    <div className="flex-1 space-y-12 text-center md:text-left">
                       <div className="space-y-4">
                          <span className="px-6 py-2 bg-indigo-50 text-indigo-600 rounded-full text-[11px] font-black uppercase italic shadow-inner border border-indigo-100">{selectedMember.role?.replace('_', ' ')}</span>
                          <h1 className="text-6xl lg:text-8xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{selectedMember.nome}</h1>
                          <p className="text-[12px] font-black text-slate-400 uppercase tracking-[0.5em] italic">Registro Staff: {selectedMember.staffId}</p>
                       </div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 gap-10">
                          <div className="space-y-2"><p className="text-[10px] font-black uppercase text-slate-300 italic tracking-widest">E-mail Corporativo</p><p className="text-xl font-bold">{selectedMember.email}</p></div>
                          <div className="space-y-2"><p className="text-[10px] font-black uppercase text-slate-300 italic tracking-widest">Telefone de Contato</p><p className="text-xl font-bold">{selectedMember.telefone || '---'}</p></div>
                          <div className="space-y-2"><p className="text-[10px] font-black uppercase text-slate-300 italic tracking-widest">Doc. Identidade</p><p className="text-xl font-bold">{selectedMember.documento || '---'}</p></div>
                          <div className="space-y-2"><p className="text-[10px] font-black uppercase text-slate-300 italic tracking-widest">Usuário Master</p><p className="text-xl font-black text-indigo-600 italic">@{selectedMember.username}</p></div>
                       </div>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 border-t border-slate-100 pt-32">
                    <div className="space-y-16">
                       <div className="space-y-8"><div className="flex items-center gap-4"><div className="w-1.5 h-8 bg-indigo-600 rounded-full"></div><h3 className="text-2xl font-black uppercase italic tracking-tighter">Currículo Docente</h3></div>
                          <div className="space-y-10">
                             <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100 shadow-inner">
                                <p className="text-[10px] font-black uppercase text-indigo-400 mb-4 italic flex items-center gap-2"><GraduationCap size={16}/> Formação Acadêmica</p>
                                <p className="text-sm font-medium text-slate-600 leading-relaxed italic">{selectedMember.dadosCurriculares?.formacaoAcademica || 'Não informada.'}</p>
                             </div>
                             <div className="p-8 bg-slate-50 rounded-[2.5rem] border border-slate-100 shadow-inner">
                                <p className="text-[10px] font-black uppercase text-indigo-400 mb-4 italic flex items-center gap-2"><Award size={16}/> Especializações</p>
                                <p className="text-sm font-medium text-slate-600 leading-relaxed italic">{selectedMember.dadosCurriculares?.especializacoes || 'Não informada.'}</p>
                             </div>
                          </div>
                       </div>
                    </div>
                    <div className="space-y-16">
                       <div className="space-y-8"><div className="flex items-center gap-4"><div className="w-1.5 h-8 bg-indigo-600 rounded-full"></div><h3 className="text-2xl font-black uppercase italic tracking-tighter">Dados de Residência</h3></div>
                          <div className="p-10 bg-white border-2 border-slate-50 rounded-[3rem] shadow-xl space-y-8">
                             <div className="flex items-center gap-5"><div className="p-4 bg-indigo-50 text-indigo-600 rounded-2xl shadow-inner"><MapPin size={24}/></div><div><p className="text-xl font-bold leading-tight">{selectedMember.endereco?.rua || 'S/E'}, {selectedMember.endereco?.numero || 'S/N'}</p><p className="text-sm font-bold text-slate-400 uppercase italic mt-1">{selectedMember.endereco?.bairro || '---'}</p><p className="text-sm font-black text-indigo-600 uppercase tracking-widest mt-0.5">{selectedMember.endereco?.cidade || '---'} / {selectedMember.endereco?.uf || '--'}</p></div></div>
                          </div>
                       </div>
                       <div className="space-y-8"><div className="flex items-center gap-4"><div className="w-1.5 h-8 bg-indigo-600 rounded-full"></div><h3 className="text-2xl font-black uppercase italic tracking-tighter">Assinatura Digital EB-EAD</h3></div>
                          {selectedMember.signatureUrl ? (
                            <div className="p-10 bg-slate-900 rounded-[3rem] shadow-2xl flex flex-col items-center justify-center gap-6 relative overflow-hidden group">
                               <p className="text-[9px] font-black uppercase text-indigo-400 tracking-[0.4em] italic z-10">VALIDAÇÃO MASTER ATIVA</p>
                               <img src={selectedMember.signatureUrl} className="h-24 object-contain grayscale opacity-60 group-hover:grayscale-0 group-hover:opacity-100 transition-all cursor-pointer z-10" />
                               <Globe2 size={150} className="absolute -bottom-10 -right-10 text-white/5 opacity-5" />
                               <button onClick={() => { setSigningUserId(selectedMember.id || selectedMember.uid); setIsSignModalOpen(true); }} className="mt-4 px-6 py-2 bg-white/10 hover:bg-white/20 rounded-xl text-[8px] font-black uppercase transition-all">Atualizar Assinatura</button>
                            </div>
                          ) : (
                            <button onClick={() => { setSigningUserId(selectedMember.id || selectedMember.uid); setIsSignModalOpen(true); }} className="w-full p-16 bg-amber-50 text-amber-600 rounded-[3rem] border-4 border-dashed border-amber-200 text-xs font-black uppercase italic tracking-widest hover:bg-amber-100 transition-all flex flex-col items-center gap-5"><PenTool size={48} className="animate-bounce" /> Coletar Assinatura Digital Agora</button>
                          )}
                       </div>
                    </div>
                 </div>
              </div>
           </main>
        </div>
      )}

      {isSignModalOpen && (
        <SignaturePad 
          title="Consolidação de Identidade Digital" 
          onCancel={() => setIsSignModalOpen(false)} 
          onSave={handleSaveSignature} 
        />
      )}
    </div>
  );
};

export default SettingsView;

