};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, CreditCard, ChevronRight, PenTool, 
  FileBadge, Save, Palette, Globe, Fingerprint, Lock, 
  Settings as SettingsIcon, BellRing, Activity, Database,
  ArrowLeft, Plus, Trash2, Mail, CheckCircle2, UserCheck,
  History, ShieldCheck, Zap, Briefcase, Calendar, Download,
  CloudLightning, HardDrive, Key, AlertTriangle, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award, MapPin, User as UserIcon, Upload, BookOpen, 
  BriefcaseBusiness, Cpu, Server, BarChart3, Globe2
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'financeiro' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio' | 'ti';

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    endereco: { rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    dadosCurriculares: {
      formacaoAcademica: '',
      especializacoes: '',
      experienciaProfissional: '',
      resumoBio: ''
    },
    cargo: 'professor' as RoleClassification,
    fotoUrl: '', status: 'ativo',
    acessos: ['dashboard', 'professor', 'alunos', 'secretaria'],
    username: '', password: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    motto: 'Educação Teológica de Excelência para o Reino',
    registrationNumber: '00.000.000/0001-00',
    website: 'www.eb-ead.edu.br',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    autoEnrollment: false,
    publicCatalog: true
  });

  const [securityConfig, setSecurityConfig] = useState({
    rbacRules: {
      ti: ['*'],
      diretor: ['*'],
      vice_diretor: ['dashboard', 'professor', 'alunos', 'secretaria', 'configuracoes'],
      secretaria: ['dashboard', 'alunos', 'secretaria', 'configuracoes'],
      coordenador: ['dashboard', 'professor', 'alunos', 'secretaria'],
      professor: ['dashboard', 'professor', 'alunos', 'secretaria'],
      apoio: ['secretaria']
    }
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({...prev, ...data.schoolConfig}));
        if (data.securityConfig) setSecurityConfig(prev => ({...prev, ...data.securityConfig}));
      }
      setLoading(false);
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(8)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubStaff = onSnapshot(collection(db, 'users'), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      const filteredStaff = data.filter(u => 
        u.staffId && 
        u.staffId !== 'MASTER' && 
        u.role !== 'aluno'
      );
      filteredStaff.sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));
      setStaff(filteredStaff);
    });

    return () => { unsubConfig(); unsubLogs(); unsubStaff(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement('canvas');
          const MAX_WIDTH = 400;
          const scaleSize = MAX_WIDTH / img.width;
          canvas.width = MAX_WIDTH;
          canvas.height = img.height * scaleSize;
          const ctx = canvas.getContext('2d');
          ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg', 0.7);
          setMemberForm({ ...memberForm, fotoUrl: dataUrl });
        };
        img.src = event.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        endereco: memberForm.endereco,
        dadosCurriculares: memberForm.dadosCurriculares,
        role: memberForm.cargo,
        photoURL: memberForm.fotoUrl, 
        status: memberForm.status,
        permissions: memberForm.acessos,
        username: memberForm.username,
        password: memberForm.password,
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
      }
      setIsMemberModalOpen(false);
      setSelectedMember(null);
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar dados do membro.");
    }
  };

  const handleDeleteMember = async (id: string, name: string) => {
    if (confirm(`Remover credenciamento de ${name} permanentemente?`)) {
      try {
        await deleteDoc(doc(db, 'users', id));
      } catch (err) {
        alert("Erro ao remover credenciamento.");
      }
    }
  };

  const handleCycleAcademicYear = async () => {
    if (confirm(`Iniciar Ciclo ${Number(schoolConfig.academicYear) + 1}?`)) {
      const nextYear = (Number(schoolConfig.academicYear) + 1).toString();
      await updateDoc(doc(db, 'system_settings', 'main_config'), { "schoolConfig.academicYear": nextYear });
      alert(`Ciclo ${nextYear} iniciado!`);
    }
  };

  const handleSaveSignature = async (base64: string) => {
    if (!signingUserId) return;
    await updateDoc(doc(db, 'users', signingUserId), { signatureUrl: base64, updatedAt: serverTimestamp() });
    if (selectedMember && (selectedMember.id === signingUserId || selectedMember.uid === signingUserId)) {
      setSelectedMember({ ...selectedMember, signatureUrl: base64 });
    }
    setIsSignModalOpen(false);
    setSigningUserId(null);
  };

  if (loading) return <div className="h-full flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20 text-slate-900">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Console de Governança</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2 uppercase tracking-widest text-[10px]">Gestão Administrativa & Infraestrutura EB-EAD</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm overflow-x-auto">
          {[
            { id: 'geral', label: 'Institucional', icon: <Building size={14}/> },
            { id: 'equipe', label: 'Equipe', icon: <Users size={14}/> },
            { id: 'seguranca', label: 'Segurança', icon: <Shield size={14}/> },
            { id: 'infra', label: 'Infraestrutura', icon: <HardDrive size={14}/> }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as SettingsTab)}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
      </header>

      <main className="min-h-[600px]">
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in slide-in-from-bottom-4">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-10">
                <div className="flex items-center gap-5 border-b border-slate-50 pb-8">
                  <div className="p-4 bg-indigo-50 text-indigo-600 rounded-3xl shadow-inner"><Building size={28} /></div>
