          <p className="text-slate-500 text-sm font-medium italic mt-2 uppercase tracking-widest text-[10px]">Gestão Administrativa & Infraestrutura EB-EAD</p>
        </div>
        <div className="flex bg-white p-1.5 rounded-2xl border border-slate-200 shadow-sm overflow-x-auto">
          {[
            { id: 'geral', label: 'Institucional', icon: <Building size={14}/> },
            { id: 'equipe', label: 'Equipe', icon: <Users size={14}/> },
            { id: 'seguranca', label: 'Segurança', icon: <Shield size={14}/> },
            { id: 'infra', label: 'Infraestrutura', icon: <HardDrive size={14}/> }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as SettingsTab)}
              className={`flex items-center gap-2 px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${
                activeTab === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
      </header>

      <main className="min-h-[600px]">
        {activeTab === 'geral' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 animate-in slide-in-from-bottom-4">
            <div className="lg:col-span-8 space-y-8">
              <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm space-y-10">
                <div className="flex items-center gap-5 border-b border-slate-50 pb-8">
                  <div className="p-4 bg-indigo-50 text-indigo-600 rounded-3xl shadow-inner"><Building size={28} /></div>
                  <div>
                    <h3 className="text-xl font-black text-slate-900 uppercase tracking-tighter italic leading-none">Identidade Institucional</h3>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-2">Dados Mestres da Organização</p>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  {[
                    { label: 'Nome da Escola', value: schoolConfig.schoolName, icon: <Building size={14}/> },
                    { label: 'Lema Acadêmico', value: schoolConfig.motto, icon: <Award size={14}/> },
                    { label: 'CNPJ', value: schoolConfig.registrationNumber, icon: <FileBadge size={14}/> },
                    { label: 'Portal Oficial', value: schoolConfig.website, icon: <Globe size={14}/> }
                  ].map((field, idx) => (
                    <div key={idx} className="space-y-2">
                      <label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic tracking-widest flex items-center gap-2">{field.icon} {field.label}</label>
                      <div className="w-full px-6 py-4 bg-slate-50 rounded-2xl font-black text-xs text-slate-900 border border-slate-100 shadow-inner">{field.value}</div>
