                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Especializações</label><textarea value={memberForm.dadosCurriculares.especializacoes} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, especializacoes: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-28 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Experiência Profissional</label><textarea value={memberForm.dadosCurriculares.experienciaProfissional} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, experienciaProfissional: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-32 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
