                    <div className="md:col-span-3 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Número</label><input value={memberForm.endereco.numero} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, numero: e.target.value}})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-xs outline-none focus:ring-2 focus:ring-indigo-600 shadow-sm" /></div>
                    <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Bairro</label><input value={memberForm.endereco.bairro} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, bairro: e.target.value}})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-5 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Cidade</label><input value={memberForm.endereco.cidade} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, cidade: e.target.value}})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-2 space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">UF</label><input value={memberForm.endereco.uf} maxLength={2} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, uf: e.target.value}})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-black text-xs shadow-inner uppercase text-center" /></div>
                 </div>
               </div>

               <div className="space-y-12">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">03</span><h3 className="text-xl font-black uppercase tracking-tight italic">Hierarquia e Dados Curriculares</h3></div>
                 <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
                    <div className="lg:col-span-7 space-y-10">
                      <div className="space-y-2">
                        <label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Função Acadêmica</label>
                        <select value={memberForm.cargo} onChange={e => setMemberForm({...memberForm, cargo: e.target.value as any})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-black text-[11px] uppercase shadow-inner appearance-none cursor-pointer">
                           <option value="diretor">Diretor (Pleno)</option>
                           <option value="vice_diretor">Vice-Diretor (Suplente)</option>
                           <option value="ti">Gestão de Tecnologia (TI)</option>
                           <option value="coordenador">Coordenador (Supervisor)</option>
                           <option value="secretaria">Secretário(a) (Gestão)</option>
                           <option value="professor">Professor (Docência)</option>
                           <option value="apoio">Equipe de Apoio (Atendimento)</option>
                        </select>
                      </div>

                      <div className="bg-slate-50 rounded-[2.5rem] p-10 border border-slate-100 shadow-inner space-y-8">
                         <div className="flex items-center gap-3 mb-2"><GraduationCap size={22} className="text-indigo-600"/><h4 className="text-[11px] font-black uppercase italic text-slate-900 tracking-widest">Dossiê Curricular Completo</h4></div>
                         <div className="grid grid-cols-1 gap-8">
                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Formação Acadêmica</label><textarea value={memberForm.dadosCurriculares.formacaoAcademica} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, formacaoAcademica: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-28 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Especializações</label><textarea value={memberForm.dadosCurriculares.especializacoes} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, especializacoes: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-28 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                            <div className="space-y-2"><label className="text-[8px] font-black uppercase text-slate-400 ml-4 italic">Experiência Profissional</label><textarea value={memberForm.dadosCurriculares.experienciaProfissional} onChange={e => setMemberForm({...memberForm, dadosCurriculares: {...memberForm.dadosCurriculares, experienciaProfissional: e.target.value}})} className="w-full px-6 py-5 bg-white border border-slate-200 rounded-[1.8rem] h-32 font-medium text-xs italic outline-none focus:ring-1 focus:ring-indigo-600 shadow-sm" /></div>
                         </div>
                      </div>
                    </div>

                    <div className="lg:col-span-5 space-y-10">
                      <div className="p-10 bg-indigo-50/40 rounded-[3rem] border border-indigo-100 shadow-2xl space-y-8">
                        <div className="flex items-center gap-3 mb-2"><Key size={20} className="text-indigo-600"/><h4 className="text-[11px] font-black uppercase italic text-indigo-900 tracking-widest">Segurança de Acesso</h4></div>
                        <div className="space-y-6">
                          <div className="space-y-2"><label className="text-[9px] font-black uppercase text-indigo-400 ml-4 italic">Nome de Usuário (Login)</label><input required value={memberForm.username} onChange={e => setMemberForm({...memberForm, username: e.target.value})} className="w-full px-6 py-4 bg-white border border-indigo-100 rounded-2xl font-black text-xs outline-none focus:ring-2 focus:ring-indigo-600 shadow-sm" /></div>
                          <div className="space-y-2"><label className="text-[9px] font-black uppercase text-indigo-400 ml-4 italic">Senha Master Temporária</label><input required type="password" value={memberForm.password} onChange={e => setMemberForm({...memberForm, password: e.target.value})} className="w-full px-6 py-4 bg-white border border-indigo-100 rounded-2xl font-mono text-xs outline-none focus:ring-2 focus:ring-indigo-600 shadow-sm" /></div>
                        </div>
                      </div>
                      <div className="space-y-6">
                        <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Situação de Cadastro</label><select value={memberForm.status} onChange={e => setMemberForm({...memberForm, status: e.target.value})} className="w-full px-6 py-5 bg-slate-50 border-none rounded-[1.8rem] font-black text-[11px] uppercase shadow-inner"><option value="ativo">Conta Ativa</option><option value="inativo">Bloqueado</option></select></div>
                      </div>
                    </div>
                 </div>
               </div>

               <div className="space-y-12 pb-20">
                 <div className="flex items-center gap-6"><span className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center font-black text-xl italic shadow-inner">04</span><h3 className="text-xl font-black uppercase tracking-tight italic">Níveis de Acesso Habilitados</h3></div>
                 <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                    {[
                      { id: 'dashboard', label: 'Dashboard', icon: <Activity size={24}/> },
                      { id: 'professor', label: 'Professor', icon: <BookOpen size={24}/> },
                      { id: 'alunos', label: 'Alunos', icon: <Users size={24}/> },
                      { id: 'secretaria', label: 'Secretaria', icon: <PenTool size={24}/> },
                      { id: 'configuracoes', label: 'Configurações', icon: <SettingsIcon size={24}/> }
                    ].map(area => (
                      <button key={area.id} type="button" onClick={() => { const up = memberForm.acessos.includes(area.id) ? memberForm.acessos.filter(a => a !== area.id) : [...memberForm.acessos, area.id]; setMemberForm({...memberForm, acessos: up}); }} className={`p-10 rounded-[3rem] border-4 transition-all flex flex-col items-center gap-5 shadow-2xl ${memberForm.acessos.includes(area.id) ? 'bg-indigo-600 border-indigo-400 text-white scale-105' : 'bg-slate-50 border-white text-slate-300 hover:border-slate-100 hover:text-slate-500'}`}>
                        <div className={`p-4 rounded-2xl ${memberForm.acessos.includes(area.id) ? 'bg-white/10' : 'bg-white/40 shadow-inner'}`}>{area.icon}</div>
                        <span className="text-[10px] font-black uppercase tracking-widest italic">{area.label}</span>
                      </button>
                    ))}
                 </div>
                 <div className="pt-24 flex gap-6">
                    <button type="button" onClick={() => { setIsMemberModalOpen(false); setSelectedMember(null); }} className="px-12 py-7 bg-slate-100 text-slate-400 rounded-[2rem] text-xs font-black uppercase italic hover:bg-slate-200 transition-all">Descartar</button>
                    <button type="submit" className="flex-1 py-7 bg-slate-900 text-white rounded-[2rem] text-xs font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic tracking-[0.3em]">{selectedMember ? 'Gravar Alterações' : 'Efetivar Credenciamento'}</button>
                 </div>
               </div>
             </div>
           </form>
        </div>
      )}

      {/* O SignaturePad deve ter um z-index maior que todos os outros modais */}
      {isSignModalOpen && (
        <div className="relative z-[5000]">
          <SignaturePad 
            title="Consolidação de Identidade Digital" 
            onCancel={() => setIsSignModalOpen(false)} 
            onSave={handleSaveSignature} 
          />
        </div>
      )}
    </div>
  );
};

export default SettingsView;
